export type TechniqueStatus='Learning'|'Drilling'|'Usable'|'Reliable'|'A-Game';
export type CompetencyStatus='Not assessed'|'Developing'|'Functional'|'Reliable'|'Verified';
export type TechniqueFailure={problem:string;fix:string};
export type BjjTechnique={id:string;name:string;position:string;category:string;applicability:('Gi'|'No-Gi')[];status:TechniqueStatus;competency?:CompetencyStatus;competencyAreaId?:string;tags:string[];goal?:string;setup:string;grips?:string[];baseManipulation?:string;bodyPosition?:string;steps:string[];finish?:string;mechanism?:string;cues:string[];mistakes:string[];troubleshooting?:TechniqueFailure[];reactions?:string[];followUps:string[];variations?:string[];drilling?:string[];notes:string;focus?:boolean;focusNote?:string;gameFollowUpIds?:string[];gameReaction?:string;videoUrl?:string};
export type CompetencyArea={id:string;name:string;targetCount:number;description:string};
export const BJJ_TECHNIQUES_KEY='workoutapp.bjj-techniques.v1';
export const techniqueStatuses:TechniqueStatus[]=['Learning','Drilling','Usable','Reliable','A-Game'];
export const competencyStatuses:CompetencyStatus[]=['Not assessed','Developing','Functional','Reliable','Verified'];
export const competencyAreas:CompetencyArea[]=[['movement','Movement',12,'Movement quality, base, hip movement, breakfalls and balance.'],['self-defense','Self-defense',9,'Safe responses to common standing and grappling threats.'],['standing','Standing techniques',3,'Posture, grips, entries and standing control.'],['takedowns','Takedowns',13,'Off-balancing, entries, finishes and safe top transitions.'],['guard-bottom','Guard · bottom',17,'Retention, attacks, sweeps and routes from bottom to top.'],['guard-top','Guard · top',18,'Posture, opening, passing and control from top.'],['half-top','Half guard · top',9,'Flattening, freeing the trapped leg, passing and stabilization.'],['side-bottom','Side control · bottom',4,'Frames, survival, escapes and recovery.'],['side-top','Side control · top',13,'Control, transitions and submissions.'],['north-south','North–south',2,'Control and transitions from north–south.'],['turtle-bottom','Turtle · bottom',6,'Protection, recovery, reversals and stand-ups.'],['turtle-top','Turtle · top',7,'Control, breakdowns and back exposure.'],['mount-bottom','Mount · bottom',2,'Survival and escapes from mount.'],['mount-top','Mount · top',5,'Maintenance, climbing, transitions and attacks.'],['technical-mount','Technical mount',6,'Control, back exposure and attacks from technical mount.'],['back-defense','Back · defense',3,'Hand fighting, survival and positional escape.'],['back-attacks','Back · attacks',4,'Control and finishing from the back.']].map(([id,name,targetCount,description])=>({id:id as string,name:name as string,targetCount:targetCount as number,description:description as string}));
export const starterTechniques:BjjTechnique[]=[
{id:'scissor-sweep',name:'Scissor Sweep',position:'Closed Guard',category:'Sweep',applicability:['Gi','No-Gi'],status:'Reliable',competency:'Reliable',tags:['A-Game','Sweep'],goal:'Break your opponent’s base from closed guard, sweep them to the side, and follow immediately into a stable top position.',setup:'Start in closed guard with your opponent kneeling. The basic gi version uses collar-and-sleeve control. Choose the side you intend to sweep before opening your guard.',grips:['If sweeping to your right, control your opponent’s left sleeve at the cuff/wrist. That is the arm they would naturally use to post and stop the fall.','Use your other hand for a reasonably deep collar grip. The collar connects you to the upper body so you can break posture, load their weight forward, and steer the torso through the sweep.','Principle: sweep toward the side where you have removed or controlled the opponent’s post.'],baseManipulation:'Do not try to sweep an opponent who is sitting upright with their weight centered over their knees. Use the collar connection to bring their upper body forward and off their heels. The sleeve prevents the near-side hand from posting. Your lower leg will remove the remaining knee/base on the sweep side.',bodyPosition:'Open the guard only after you have useful upper-body control. Turn onto your side rather than remaining square and flat. Bring the upper shin diagonally across the opponent’s torso as a frame. Drop the lower leg close to the mat beside or behind the opponent’s knee so it can remove that base.',steps:['Establish collar-and-sleeve control and decide which direction you are sweeping.','Break posture. Pull the opponent forward so their weight is no longer comfortably centered over their knees.','Open your guard and turn onto your side. Create enough hip angle for your legs to work across the opponent rather than straight up underneath them.','Bring your upper knee/shin across the opponent’s torso. Keep this leg structurally connected rather than making a loose kicking motion.','Drop the lower leg to the mat beside or behind the opponent’s knee on the sweep side. This leg is responsible for taking away the base.','Load the opponent forward with the collar while maintaining sleeve control. You should feel their weight become lighter on the knees/heels before committing to the sweep.','Scissor the legs as one coordinated action: the upper leg guides the torso while the lower leg cuts out the base. At the same time, use your grips and torso rotation to direct the opponent toward the controlled-post side.','Follow immediately as the opponent falls. Keep your connection, come to the top, and stabilize before releasing control or attacking.'],finish:'Come up with the sweep rather than remaining on your back. Establish a stable top position—often mount depending on the variation and reaction—before beginning the next attack.',mechanism:'The sweep works by removing the opponent’s ability to post, shifting their center of mass forward and sideways, and taking away the knee/base that would otherwise support them. The legs are not simply kicking the opponent over; the grips, angle, weight shift, and removal of the base make the scissoring action effective.',cues:['Control the post before you sweep.','Break posture before opening the guard.','Get onto your side—do not perform the sweep flat.','One leg high across the torso; one leg low at the base.','Load them first, then scissor.','Follow the sweep to top control.'],mistakes:['Opening the guard while the opponent is upright and balanced.','Failing to control the arm the opponent can use to post.','Remaining flat and square underneath the opponent.','Leaving the lower leg trapped underneath instead of positioning it to remove the knee/base.','Trying to leg-press or kick the opponent over without first moving their weight.','Completing the sweep but remaining on the bottom.'],troubleshooting:[{problem:'They do not begin to tip.',fix:'Check posture and weight first. If they are sitting comfortably on their heels, pull them forward and create kuzushi before trying to scissor.'},{problem:'They catch themselves with a hand.',fix:'You likely failed to control the posting arm on the side of the sweep. Re-establish sleeve/wrist control before committing.'},{problem:'The sweep feels weak or cramped.',fix:'Check your angle. Turn onto your side and move your hips enough that your shin can work across the torso instead of pushing straight upward.'},{problem:'They tip but their knee/base stops the sweep.',fix:'Check the lower leg. It needs to be positioned to remove or block the supporting knee rather than remaining underneath the opponent.'},{problem:'They fall but you stay underneath.',fix:'Follow the momentum immediately. Maintain the grips and come up as the opponent turns over instead of treating the fall as the end of the technique.'}],reactions:['If the opponent withdraws or changes the posting arm, reassess which side has the weaker base rather than forcing the original direction.','If posture becomes difficult to break, restore posture control before trying to generate more leg force.','If their defensive reaction creates another attack, transition rather than forcing a sweep whose required conditions are gone.'],followUps:['Mount','Hip Bump Sweep','Kimura'],variations:['Collar-and-sleeve scissor sweep (primary learning version)','No-gi versions replace cloth grips with appropriate wrist/head/upper-body connections while preserving the same principles: control the post, break balance, create angle, remove the base.'],drilling:['Begin cooperatively: establish grips, create the angle, place both legs correctly, and pause before sweeping so a coach/partner can check the structure.','Perform slow repetitions to both sides, emphasizing posture break and coming to top rather than speed.','Add progressive resistance: partner first maintains posture, then attempts to recover the posting hand/base, then gives realistic guard resistance.','In positional rounds, begin in closed guard with the goal of creating the sweep conditions rather than forcing the sweep immediately.'],notes:'A dependable sweep. Record which grips, angles, opponent reactions, and follow-up positions are consistently working in live rounds.'},
{id:'side-americana',name:'Americana from Side Control',position:'Side Control Top',category:'Submission',applicability:['Gi','No-Gi'],status:'Reliable',competency:'Reliable',tags:['Submission','A-Game'],goal:'Isolate the near arm from stable side control and apply a bent-arm shoulder lock without sacrificing top position.',setup:'Begin from established side control. Settle the opponent before attacking; the submission should grow out of control rather than replace it.',grips:['Use your near-side hand to pin the opponent’s wrist to the mat.','Thread your other arm underneath their upper arm/elbow and grip your own wrist to create the figure-four.','Keep the wrist connected to the mat as the elbow is repositioned.'],baseManipulation:'Pin the shoulder line and prevent the opponent from freely turning toward or away while you isolate the arm. If attacking the arm causes you to lose chest/hip control, rebuild side control first.',bodyPosition:'Stay heavy and balanced beside the opponent. Keep the trapped elbow bent and avoid reaching so far for the figure-four that your own base becomes narrow.',steps:['Stabilize side control and isolate the near arm.','Pin the wrist to the mat with the same-side hand.','Thread the opposite arm underneath the opponent’s upper arm and grip your own wrist.','Keep the opponent’s wrist on the mat and their elbow near a right angle.','Slide/draw the elbow down toward their ribs/hip line as needed to tighten the shoulder position.','Maintain the wrist on the mat and gradually lift the elbow to create shoulder rotation.','Apply the finish slowly and release immediately on the tap.'],finish:'Maintain side control as you apply gradual shoulder rotation. The lock should not require a large explosive lift.',mechanism:'The figure-four controls the wrist and elbow as a connected lever. Keeping the wrist fixed while the elbow rises internally/externally rotates the shoulder beyond its comfortable range.',cues:['Control before submission.','Wrist stays on the mat.','Move the elbow into position before lifting.','Finish slowly.'],mistakes:['Lifting the wrist off the mat.','Trying to muscle the elbow upward before the arm is properly positioned.','Giving away side control while reaching for the figure-four.','Applying the shoulder lock explosively.'],troubleshooting:[{problem:'Their elbow will not lift.',fix:'Check that the wrist is still pinned and draw the elbow lower/tighter before trying to raise it.'},{problem:'They turn and recover position.',fix:'You attacked before stabilizing their torso. Rebuild side control and isolate the arm without abandoning your base.'}],reactions:['If they straighten the arm, transition to a straight-arm control/attack rather than forcing the bent-arm shape.','If they hide the elbow, use the defensive movement to advance position or mount.'],followUps:['Straight Armlock','Armbar','Mount'],variations:['Americana from side control','Americana from mount'],drilling:['Practice building the figure-four without finishing.','Add the finish slowly with immediate release on the tap.','Use positional rounds where maintaining side control scores more highly than forcing the submission.'],notes:'Strong finishing option from a position that is already a strength.'},
{id:'mount-control',name:'Mount Control Cycle',position:'Mount Top',category:'Control',applicability:['Gi','No-Gi'],status:'Learning',competency:'Developing',tags:['Needs Work','Position'],goal:'Hold mount long enough to force predictable defensive reactions, climb to stronger control, and attack without giving the position away.',setup:'Begin after establishing mount. Your first task is to settle your hips and survive the opponent’s immediate bridge/elbow-knee escape before hunting a submission.',grips:['Use head-and-arm, crossface, underhook, wrist, collar, or other upper-body controls according to the reaction. The purpose of the connection is to stop the shoulders/elbows from freely reorganizing underneath you.'],baseManipulation:'Make the opponent carry your weight and force them to move first. When they bridge, widen or post the appropriate base. When elbows separate from the ribs, use that space to climb the knees and improve the mount.',bodyPosition:'Keep your hips responsive rather than rigid. Knees climb toward the armpits as control improves. Your upper body changes angle with the escape instead of remaining upright and disconnected.',steps:['Settle the hips and establish a wide, reactive base.','Win inside arm position and control the head/shoulder line.','Let the opponent reveal the escape direction before committing your weight.','Post/widen your base against the bridge while keeping your hips connected.','As elbows separate or space opens, walk the knees higher toward the armpits.','Use crossface, underhook, grapevine, or technical-mount transition according to the defensive reaction.','Only begin the submission once the opponent is carrying your weight and their defensive structure is compromised.'],finish:'A successful control cycle ends in a more stable/high mount, technical mount, or a submission entered without surrendering top control.',mechanism:'Mount becomes difficult to escape when the top player keeps weight connected, follows the direction of the escape, and progressively separates the elbows from the hips. The opponent’s escape attempts create the openings for advancement.',cues:['Position before submission.','Climb the mount.','Make them move first.','Follow the escape instead of fighting it rigidly.'],mistakes:['Attacking too early.','Sitting upright without controlling the upper body.','Keeping the knees low beside the hips indefinitely.','Failing to follow elbow-knee escape movement.'],troubleshooting:[{problem:'I reach mount and immediately lose it.',fix:'Do not attack yet. Spend the first exchange settling your hips, identifying the escape direction, and maintaining a reactive base.'},{problem:'I get stuck with no submissions.',fix:'Treat climbing the mount and separating elbows from hips as the next objective rather than searching randomly for a finish.'}],reactions:['Bridge creates a direction to post and an opportunity to follow the shoulders.','Elbow-knee escape creates an elbow/hip battle; climb or isolate the arm rather than remaining low.','Turning away can create technical mount/back exposure.'],followUps:['Technical Mount','Americana','Arm Triangle','Mounted Armbar'],variations:['Low mount stabilization','High mount','Technical mount transition'],drilling:['Start in mount with no submissions allowed and hold/advance for timed rounds.','Add one escape at a time so the top player learns the correct base response.','Only later add submissions after a stable control cycle.'],notes:'Development area: convert getting to mount into sustained control and predictable attacks.'},
{id:'knee-pick',name:'Underhook Knee Pick',position:'Standing',category:'Takedown',applicability:['Gi','No-Gi'],status:'Usable',competency:'Functional',tags:['Stand-up','Competition'],goal:'Use underhook and head position to move the opponent’s upper body away from a supporting leg, then remove that leg and follow directly to top control.',setup:'Use your preferred right-leg-forward stance. Establish a right-side underhook/body connection and win inside head position before reaching for the leg.',grips:['Right underhook connects your shoulder/arm to the opponent’s torso.','Use the other arm/hand to control the far side, upper body, or an appropriate gi grip so they cannot freely rotate away.','The knee pick is secondary to the upper-body connection; do not reach down and disconnect first.'],baseManipulation:'Pressure and head position make the opponent step, lean, or load one leg. Move the upper body away from the knee you intend to collect so the leg becomes a post rather than a mobile escape.',bodyPosition:'Stay connected chest/shoulder-to-body with your head driving in a useful direction. Bend through your level to reach the knee rather than folding at the waist and letting your head/hips drift away.',steps:['Win inside head position and establish the right underhook.','Close enough distance that the underhook is a body connection rather than a loose arm position.','Use head and upper-body pressure to create a reaction and identify the loaded/available near knee.','Change level while maintaining the upper-body connection.','Reach the near knee only after the opponent’s posture/base has moved.','Pick/block the knee while driving the upper body in the opposite direction.','Keep moving through the finish rather than stopping once the leg leaves the floor.','Follow the opponent down and establish top control before releasing your connections.'],finish:'Land connected on top, stabilize, score/control, then begin the pass or submission sequence.',mechanism:'The opponent cannot keep a stable base when the torso is driven one direction while the supporting knee is removed in the other. The underhook/head position create the kuzushi; the hand on the knee completes it.',cues:['Head drives the finish.','Move the upper body before taking the knee.','Do not reach before you are connected.','Stay connected on the landing.'],mistakes:['Reaching for the leg before creating an upper-body reaction.','Losing head position.','Bending at the waist and disconnecting the underhook.','Finishing the takedown but allowing a scramble instead of establishing top.'],troubleshooting:[{problem:'I cannot reach the knee without losing position.',fix:'You are probably reaching too early. Move their upper body and change your level while maintaining the underhook before extending the hand.'},{problem:'They step the leg away.',fix:'Use the step as information—continue your body connection into the next takedown/trip rather than chasing the retreating knee.'}],reactions:['If the knee retreats, continue to body-lock/trip options.','If they whizzer the underhook, improve head position and far-side safety before closing the hips.','If they give you the top directly, take top rather than adding an unnecessary finish.'],followUps:['Body Lock Trip','Wrestle-Up','Side Control'],variations:['Standing underhook knee pick','Wrestle-up knee pick from bottom-to-top sequence'],drilling:['Begin from established underhook/head position and practice creating the step before touching the knee.','Add progressive resistance where the partner may retreat the knee or whizzer.','Finish every repetition by establishing top control.'],notes:'Part of the current standing system.'}
];

export const movementCompetencies:BjjTechnique[]=[
{id:'movement-1',name:'Hip escape · shrimp',position:'Movement',category:'Fundamental',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Create space under pressure by moving your hips away, then recover a knee or guard between you and your partner.',setup:'Start on your back with knees bent. In partner practice, use compact frames at the shoulder and hip so the frame preserves space while your hips move.',grips:['This is primarily a framing skill rather than a gripping skill. Keep elbows close and use skeletal frames at the opponent’s shoulder/upper body and hip line instead of extending your arms and bench-pressing.'],baseManipulation:'The goal is not to move your opponent. Hold the available space with your frames while moving your own hips away from their pressure.',bodyPosition:'Turn onto your side before moving the hips. Plant the upper foot close enough to your hips to drive through the floor while keeping the other leg free to recover inside position.',steps:['Build compact shoulder-and-hip frames.','Turn onto your side instead of remaining flat.','Plant the upper foot near your hips.','Push through that foot and slide your hips backward, away from the pressure, while the frames preserve distance.','Bring the bottom knee into the space you created.','Square your hips and recover guard or another useful inside position.','Reset and practice on both sides.'],finish:'Finish with your knee/leg back between you and the opponent and your hips squared enough to establish guard or continue the escape.',mechanism:'Your frames preserve distance while the planted foot drives your hips away. Moving the hips changes the relationship without requiring you to push the opponent’s body away with arm strength.',cues:['Get onto your side first.','Move your hips, not your opponent.','Elbows stay close.','The escape is incomplete until a knee comes back inside.'],mistakes:['Remaining flat and trying to drag yourself with your shoulders.','Bench-pressing the opponent instead of using frames.','Moving the hips away but failing to recover the knee into the space.'],troubleshooting:[{problem:'I move but still remain pinned.',fix:'Check whether you actually turned onto your side and whether your frames preserved space while the hips moved.'},{problem:'I create space and immediately lose it.',fix:'Recover the bottom knee inside as part of the same sequence; do not treat hip movement alone as the finish.'}],reactions:['If the opponent follows your hips, maintain the frames and repeat the movement rather than extending your arms.','If enough space opens earlier, recover the knee/guard immediately instead of making an unnecessarily large shrimp.'],followUps:['Guard recovery','Elbow-knee escape','Technical stand-up'],variations:['Solo shrimp movement','Partner hip escape using shoulder-and-hip frames'],drilling:['Do five slow repetitions each way.','Pause after each rep with the knee inside and confirm that you actually recovered space.','Add light partner pressure only after the movement pattern is clean.'],notes:''},
{id:'movement-2',name:'Bridge',position:'Movement',category:'Fundamental',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Use your feet, hips, and shoulder line to elevate and redirect an opponent’s weight rather than pushing them with your arms.',setup:'Lie on your back with knees bent and feet planted close enough to drive strongly through the floor.',grips:['The bridge itself does not require a specific grip. In positional use, first control or account for the opponent’s posting arm/head as required by the escape or reversal.'],baseManipulation:'A useful bridge takes the opponent’s weight toward a direction where their post is controlled or unavailable. Elevation without redirecting the base usually just lifts them temporarily.',bodyPosition:'Keep the feet planted, knees bent, and drive through the floor. Lift the hips while turning toward a shoulder rather than finishing square on the back of your head.',steps:['Plant both feet firmly.','Bring the heels close enough that you can drive without your feet sliding.','Drive through the feet and extend the hips upward.','Turn your head and shoulder line toward the direction you need to move the opponent.','Reach full useful hip extension, then return under control or continue directly into the escape/reversal.'],finish:'The bridge should create a reaction, space, or reversal angle that immediately connects to the next movement.',mechanism:'Power comes from ground force through the feet and hip extension. Turning toward the shoulder converts a vertical bridge into directional force that can compromise an opponent’s base.',cues:['Feet drive the floor.','Hips do the work.','Bridge toward a shoulder, not straight up forever.','Connect the bridge to the next action.'],mistakes:['Trying to lift with the neck or arms.','Feet too far away to create strong hip extension.','Bridging straight up without directing the opponent’s weight.','Pausing after the bridge and giving the opponent time to settle.'],troubleshooting:[{problem:'My bridge feels weak.',fix:'Move the heels closer, drive through the feet, and make the hips—not the neck—the source of elevation.'},{problem:'They rise but do not lose position.',fix:'Direct the bridge toward a compromised post and connect it immediately to your escape or reversal.'}],reactions:['If the opponent widens their base, use the reaction to create space for hip movement or another escape.'],followUps:['Hip escape · shrimp','Upa escape','Elbow-knee escape'],variations:['Straight elevation bridge','Directional bridge toward one shoulder'],drilling:['Perform slow bridges emphasizing full hip extension.','Alternate directional bridges over each shoulder.','Add the bridge as the first movement of positional escape repetitions.'],notes:''},
{id:'movement-3',name:'Technical stand-up',position:'Movement',category:'Fundamental',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Stand from the ground while keeping distance, balance, and a defensive barrier between you and the opponent.',setup:'Begin seated with one foot planted, the opposite hand posted behind you, and the free hand available to frame/protect.',grips:['No gi grip is required. Your free hand acts as a frame or protective hand; do not sacrifice it by posting both hands behind you.'],baseManipulation:'Create enough distance that the opponent cannot simply collapse onto you while you stand. Your extended/free leg can manage range before it retracts underneath you.',bodyPosition:'Build a three-point base with posted hand, planted foot, and the opposite hip/leg. Keep your eyes and torso oriented toward the opponent.',steps:['Post one hand behind you and plant the opposite foot.','Keep the free hand up as a frame/protective hand.','Use the free leg to maintain distance if needed.','Drive through the planted foot and posted hand to lift your hips off the floor.','Retract the extended leg underneath and behind you without crossing your feet.','Land in a balanced stance facing the opponent.','Recover your hands to a ready position immediately.'],finish:'Finish standing in base, facing the opponent, with your feet underneath you and hands available to grip, frame, or disengage.',mechanism:'Lifting the hips creates enough clearance to retract the leg underneath while the diagonal hand-foot base keeps you balanced and the free limbs protect distance.',cues:['One hand posts; one hand protects.','Lift the hips before bringing the leg underneath.','Do not cross your feet.','Keep facing the opponent.'],mistakes:['Turning your back while standing.','Posting both hands behind you.','Dragging the retracting leg without enough hip clearance.','Crossing the feet and losing balance.'],troubleshooting:[{problem:'My leg gets stuck when I try to stand.',fix:'Lift the hips higher before retracting the leg underneath.'},{problem:'I feel unstable at the top.',fix:'Place the retracting foot into a normal stance rather than crossing it behind the planted leg.'}],reactions:['If the opponent closes distance, maintain the frame/range-management leg and create space before committing to the stand.'],followUps:['Standing stance','Grip fighting','Sprawl'],variations:['Self-defense technical stand-up','Grappling stand-up from seated guard when safe'],drilling:['Alternate sides slowly.','Pause with hips elevated before retracting the leg.','Add a partner who approaches gradually so you learn to manage distance before standing.'],notes:''},
{id:'movement-4',name:'Backward breakfall',position:'Movement',category:'Fundamental',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Disperse impact safely when falling backward while protecting the head and avoiding a stiff-arm post.',setup:'Begin from a low squat or seated position while learning, then progress to standing only when the mechanics are comfortable.',grips:[],baseManipulation:'This is a self-protection movement rather than an opponent-control movement.',bodyPosition:'Round the back, tuck the chin, and keep the head from striking the mat. Arms angle away from the body rather than reaching straight behind you.',steps:['Tuck your chin toward your chest.','Lower your center of gravity and sit backward rather than throwing the shoulders directly at the floor.','Round through the back so contact travels progressively across the body.','Keep the head off the mat.','Slap the mat with the arms at an angle beside the body to disperse force; do not reach backward with a straight arm.','Bring the legs into a safe defensive position and recover your orientation.'],finish:'Finish aware, with the head protected and limbs available to frame, guard, or stand.',mechanism:'A rounded body and broad contact area spread the impact over time and surface area; avoiding a straight-arm post reduces concentrated force through the wrist/elbow/shoulder.',cues:['Chin tucked.','Never post a straight arm behind you.','Round the back.','Head stays off the mat.'],mistakes:['Letting the head whip into the mat.','Posting on a straight hand/arm.','Falling rigidly onto a flat back.'],troubleshooting:[{problem:'My head touches the mat.',fix:'Practice from seated height and exaggerate the chin tuck until the head consistently remains clear.'}],reactions:[],followUps:['Guard position','Technical stand-up'],variations:['Seated backward breakfall','Squatting backward breakfall','Standing backward breakfall'],drilling:['Learn from seated height first.','Progress to a squat only when head position is automatic.','Add standing height under coach supervision.'],notes:''},
{id:'movement-5',name:'Side breakfall',position:'Movement',category:'Fundamental',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Land safely when directed sideways without posting a straight arm or taking the impact on the elbow/shoulder point.',setup:'Learn close to the floor before progressing to a larger fall.',grips:[],baseManipulation:'This is primarily a safe-landing competency.',bodyPosition:'Keep the chin protected, avoid landing directly on the elbow, and distribute contact along the side of the body and arm.',steps:['Lower your level toward the falling side.','Keep the chin tucked and head protected.','Do not reach for the floor with a straight hand.','Land along the side of the body rather than directly on the elbow or shoulder point.','Use the arm to slap/disperse impact at an appropriate angle.','Recover the legs into a defensive position.'],finish:'Finish protected and ready to frame, guard, or stand rather than lying extended.',mechanism:'Spreading the impact across a larger surface and avoiding rigid posts reduces concentrated force at vulnerable joints.',cues:['No straight-arm post.','Protect the head.','Do not land on the elbow point.','Recover your legs.'],mistakes:['Posting the hand to catch the fall.','Landing directly on the elbow/shoulder.','Allowing the head to strike the mat.'],troubleshooting:[{problem:'I instinctively reach for the floor.',fix:'Return to low repetitions and practice the arm slap/landing pattern until it replaces the posting reflex.'}],reactions:[],followUps:['Guard position','Technical stand-up'],variations:['Low side breakfall','Standing side breakfall'],drilling:['Practice both sides from low height.','Increase height only when the protective pattern is automatic.'],notes:''},
{id:'movement-6',name:'Shoulder roll',position:'Movement',category:'Fundamental',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Roll diagonally across the shoulder and back without loading the head or neck, preserving momentum and a safe recovery.',setup:'Begin kneeling or crouched with plenty of clear mat space.',grips:[],baseManipulation:'This is a movement/safety competency rather than a grip-based technique.',bodyPosition:'The pathway is shoulder-to-opposite-hip, not directly over the cervical spine. Round the body and keep the head out of the contact path.',steps:['Lower your level and choose the shoulder you will roll over.','Tuck the head away from the rolling shoulder.','Reach/shape the arms so the shoulder—not the top of the head—enters the mat pathway.','Push from the legs and roll diagonally across the upper back toward the opposite hip.','Keep the body rounded so momentum continues smoothly.','Recover to a seated, kneeling, or standing base under control.'],finish:'Finish balanced and oriented rather than sprawled flat after the roll.',mechanism:'The diagonal path distributes force across the shoulder/back while keeping direct pressure away from the head and neck.',cues:['Shoulder to opposite hip.','Head out of the pathway.','Stay round.','Carry momentum into a balanced finish.'],mistakes:['Rolling directly over the head/neck.','Trying to roll straight down the spine.','Flattening out midway through the movement.'],troubleshooting:[{problem:'I feel pressure on my neck.',fix:'Stop and reduce the height. Re-establish the diagonal shoulder-to-opposite-hip pathway before adding speed.'}],reactions:[],followUps:['Forward roll','Technical stand-up'],variations:['Kneeling shoulder roll','Standing shoulder roll'],drilling:['Trace the diagonal pathway slowly from kneeling.','Practice both shoulders.','Progress to standing entries only after the path is consistent.'],notes:''},
{id:'movement-7',name:'Forward roll',position:'Movement',category:'Fundamental',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Move forward through a safe rounded roll while protecting the head and neck and recovering balance.',setup:'Start crouched or kneeling with clear space in front of you.',grips:[],baseManipulation:'This is a locomotion/safety skill.',bodyPosition:'Round the body and keep the head tucked so the roll travels over the shoulder/upper back rather than directly onto the crown of the head.',steps:['Lower your level and tuck the chin.','Place the hands/arms to guide a safe entry without making the head the first point of contact.','Push gently from the legs and enter over a shoulder.','Stay rounded as the upper back and hips follow.','Allow the feet to return toward the floor as momentum carries you through.','Finish seated, kneeling, or standing in balance.'],finish:'Recover a stable base and orientation immediately after the roll.',mechanism:'A rounded shape converts forward momentum into rotation while spreading contact across the back rather than concentrating it at the neck.',cues:['Do not roll on your head.','Stay round.','Keep moving through the roll.','Finish in base.'],mistakes:['Planting the head as the pivot point.','Flattening the back and stopping momentum.','Finishing off-balance.'],troubleshooting:[{problem:'The roll stops halfway.',fix:'Stay rounded and allow the hips to continue over the shoulder rather than flattening the torso.'}],reactions:[],followUps:['Technical stand-up','Shoulder roll'],variations:['Kneeling forward roll','Standing forward roll'],drilling:['Start from kneeling.','Practice both shoulder pathways.','Progress height and speed gradually.'],notes:''},
{id:'movement-8',name:'Knee-on-belly spin',position:'Movement',category:'Transition',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Move around a grounded partner while maintaining mobile top pressure and orientation rather than stepping blindly across their body.',setup:'Begin in a controlled knee-on-belly position with your partner cooperating and hands available for upper-body control.',grips:['Use appropriate upper-body controls for your ruleset—commonly collar/upper-body and hip/pants connections in the gi—to keep the partner oriented while you move.'],baseManipulation:'Keep enough pressure and connection that the bottom player cannot simply sit up or turn freely while your hips travel around them.',bodyPosition:'Stay tall enough to move but connected enough to control. Your posted foot and knee should adjust continuously so you do not cross your feet or expose your back.',steps:['Establish knee-on-belly with stable upper-body and hip control.','Post the free foot where it can support rotation.','Shift your weight enough to make the knee mobile without completely abandoning pressure.','Pivot around the partner’s torso, turning your hips and shoulders together.','Re-place the knee as you arrive on the opposite side.','Rebuild knee-on-belly pressure and base before continuing.'],finish:'Finish in a stable knee-on-belly on the opposite side with control restored.',mechanism:'The transition uses a mobile post and hip rotation while maintaining enough connection to prevent the bottom player from freely following or escaping.',cues:['Control first, then move.','Hips and shoulders turn together.','Do not cross your feet.','Re-establish pressure at the finish.'],mistakes:['Trying to spin without controlling the upper body.','Standing so tall that all pressure disappears.','Crossing the feet and becoming easy to off-balance.'],troubleshooting:[{problem:'They turn with me and recover guard.',fix:'Improve the upper-body/hip connection and reduce the amount of time you completely unload the knee.'}],reactions:['If the partner frames strongly, use the transition only when your controls make the far side available rather than forcing the spin.'],followUps:['Knee-on-belly control','Side control','Mount'],variations:['Spin around the head-side','Knee-on-belly side switch'],drilling:['Walk the transition slowly around a cooperative partner.','Pause on each side and verify base before increasing speed.'],notes:''},
{id:'movement-9',name:'Knee-on-belly windshield wipers',position:'Movement',category:'Transition',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Switch knee-on-belly sides by changing the knee/leg relationship while keeping top control.',setup:'Begin from stable knee-on-belly with a balanced posted foot and useful upper-body control.',grips:['Maintain upper-body and hip-line connections appropriate to gi/no-gi so the leg switch does not become a complete release of control.'],baseManipulation:'Keep the bottom player’s shoulders/hips managed while the knees change position.',bodyPosition:'Keep your weight centered and mobile; the legs exchange roles in a windshield-wiper action without crossing or tangling underneath you.',steps:['Stabilize knee-on-belly and establish your controls.','Shift enough weight to free the controlling knee.','Rotate the legs in a windshield-wiper pattern as your hips turn toward the opposite side.','Bring the new knee across the torso while the previous knee/leg becomes the supporting side.','Settle your weight and rebuild the posted-foot base.','Confirm control before attacking or moving again.'],finish:'Stable knee-on-belly on the opposite side.',mechanism:'The coordinated hip and leg switch lets you change sides without taking a large step over the opponent or giving up all top connection.',cues:['Small controlled leg switch.','Keep your center over your base.','Do not cross the legs.','Settle before attacking.'],mistakes:['Switching the legs before controlling the upper body.','Throwing both legs at once and losing base.','Landing with the knee poorly aligned or no supporting post.'],troubleshooting:[{problem:'I fall or get rolled during the switch.',fix:'Reduce the size/speed of the movement and keep your center supported by a deliberate post while only one leg becomes light at a time.'}],reactions:['If the partner bridges during the switch, prioritize base and control over completing the side change.'],followUps:['Knee-on-belly control','Side control','Mount'],variations:['Slow technical side switch','Reaction-based switch when the partner turns away'],drilling:['Alternate sides without submissions.','Pause after every switch to check base and pressure.'],notes:''},
{id:'movement-10',name:'Knee-on-belly headstand transition',position:'Movement',category:'Transition',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Use a controlled inversion/head-supported transition to change sides around a grounded partner while preserving top orientation.',setup:'This is an advanced movement drill. Learn it with a coach on a cooperative partner and only after basic knee-on-belly side switches are comfortable.',grips:['Maintain secure upper-body/hip connections so the inversion is a controlled transition rather than an unsupported acrobatic movement.'],baseManipulation:'Keep the partner controlled and use the transition to travel around their frames, not to jump over uncontrolled movement.',bodyPosition:'Load weight through the hands/arms and shoulder structure as taught by your coach; avoid dumping bodyweight directly through the cervical spine. Keep the core tight and legs controlled during the inversion.',steps:['Establish controlled knee-on-belly and grips/connections.','Create the space and posts required for the transition.','Shift weight deliberately into the supporting upper-body structure.','Lift the hips and move the legs over/around in a controlled arc.','Track the partner as you rotate to the opposite side.','Return the feet/knee to the mat and immediately rebuild knee-on-belly base and pressure.'],finish:'Finish balanced in top control on the opposite side.',mechanism:'The elevated hip position allows the legs to clear frames and travel around the partner while the upper-body posts provide a temporary base.',cues:['Coach this movement before loading it.','Do not dump weight into the neck.','Control the legs; do not fling them.','Rebuild top pressure immediately.'],mistakes:['Attempting the movement without sufficient upper-body support.','Putting excessive pressure through the head/neck.','Using uncontrolled momentum.','Landing without a stable base.'],troubleshooting:[{problem:'I feel neck pressure or instability.',fix:'Stop the repetition. Return to basic side-switch drills and have your coach correct the support structure before attempting it again.'}],reactions:[],followUps:['Knee-on-belly control','Side control'],variations:['Academy-specific headstand/inversion transition'],drilling:['Practice only under coaching supervision.','Begin with movement-specific progressions before adding a partner.'],notes:'Confirm your academy’s exact mechanics for this transition before treating it as a live-round technique.'},
{id:'movement-11',name:'Sprawl',position:'Movement',category:'Defense',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Remove your legs from a takedown attack while putting your hips/weight onto the attacker and establishing a defensive angle.',setup:'Begin in a balanced standing stance with knees soft and hands ready to frame/control the attacker’s upper body.',grips:['As the attack arrives, use hands/forearms to manage the shoulders/head as appropriate. After the hips clear, establish head/arm control rather than leaving your hands disconnected.'],baseManipulation:'The attacker wants your hips over your feet and your legs within reach. The sprawl sends the legs back while your hips become heavy over their upper body, breaking their forward structure.',bodyPosition:'Hips drive back and down as the legs extend away. Keep your chest/head positioned so you do not simply fall forward underneath the attacker.',steps:['Recognize the level change/entry and bring your hands to useful upper-body control.','Throw or step the legs back out of reach.','Drive the hips down into the attacker’s shoulder/upper-back line as appropriate.','Keep your head/chest organized and avoid reaching the arms so far that your base collapses.','Angle off rather than remaining directly in front if the position allows.','Establish front-head/upper-body control or disengage to stance.'],finish:'Finish with the takedown stopped and either establish dominant front-head/top control or return safely to standing.',mechanism:'Removing the legs denies the attacker access to the hips/knees while hip pressure makes it difficult for them to continue driving underneath you.',cues:['Legs back; hips heavy.','Do not leave the hips high.','Control the upper body after you clear the shot.','Angle off.'],mistakes:['Dropping the chest but leaving the legs close enough to grab.','Keeping the hips high.','Sprawling and then doing nothing with the attacker’s head/arms.'],troubleshooting:[{problem:'They keep driving through my sprawl.',fix:'Check that the legs actually cleared and the hips are applying pressure rather than hovering high behind the attacker.'}],reactions:['If they abandon the shot, recover stance rather than staying extended on the floor.','If their posture collapses, establish front-head control and begin your top offense.'],followUps:['Front headlock','Go-behind','Standing reset'],variations:['Hip sprawl','Angle sprawl'],drilling:['Partner gives slow level changes; sprawl and recover stance.','Progress to controlled shots and finish every defense with an angle/control rather than stopping at the sprawl.'],notes:''},
{id:'movement-12',name:'Kuzushi · breaking balance',position:'Movement',category:'Principle',applicability:['Gi','No-Gi'],status:'Learning',competency:'Not assessed',tags:['Competency'],goal:'Move an opponent’s center of mass away from a stable base so a takedown, sweep, pass, or reversal requires less force.',setup:'Begin from any controlled connection—standing grips, guard grips, underhook/body connection, or another position where you can influence the opponent’s posture and base.',grips:['A grip is useful only if it lets you transmit force into posture/base. Connect to meaningful levers such as collar/head, sleeve/wrist, elbow, underhook, belt/waist, or leg according to the position.'],baseManipulation:'Identify where the opponent is currently supported, then move their weight toward an edge or remove the post they need in that direction. Good kuzushi happens before the finishing action.',bodyPosition:'Use your whole body and angle rather than isolated arm pulling. Keep your own base organized while you move theirs.',steps:['Identify the opponent’s current base: feet, knees, hands, or combination.','Choose the direction you want them to move.','Control or threaten the post they would use to recover in that direction.','Use your connection, angle, and body movement to shift their center toward the edge of the base.','Feel for the moment their weight commits or a post becomes light.','Enter the takedown, sweep, pass, or reversal while the base is compromised.'],finish:'Convert the balance break immediately into positional advancement rather than allowing the opponent to rebuild their base.',mechanism:'A stable opponent can oppose force efficiently. Once their center moves outside or toward the edge of their support, they must post, step, or shift weight; that reaction creates the opening for your technique.',cues:['Move the weight before the finish.','Know which post saves them.','Use your body, not just your arms.','Attack during the recovery reaction.'],mistakes:['Trying to finish against a fully stable base.','Pulling hard without changing angle or weight distribution.','Ignoring the opponent’s available post.','Creating a reaction and waiting until they recover.'],troubleshooting:[{problem:'My techniques feel like strength contests.',fix:'Pause before the finish and identify whether you actually moved the opponent’s center or removed a post.'},{problem:'They keep catching themselves.',fix:'Determine which hand, foot, or knee is saving them and control, block, or redirect that post before repeating the attack.'}],reactions:['A step, post, widened knee, or posture change is information: attack the new base rather than forcing the original shape.'],followUps:['Scissor Sweep','Underhook Knee Pick','Body Lock Trip'],variations:['Standing kuzushi','Guard sweep kuzushi','Wrestle-up/post removal'],drilling:['With a cooperative partner, create small balance breaks in multiple directions without finishing.','Call out which post becomes light or must move.','Then attach one familiar finish to the reaction.'],notes:''}
] as BjjTechnique[];
