const slug=(s:string)=>s.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');

const guardBottomInstruction:Record<string,Partial<BjjTechnique>>={
'Cross choke':{goal:'Use opposing collar grips from closed guard to control posture and apply a blood choke while keeping the opponent trapped between your legs.',setup:'Begin in closed guard with posture controlled. Create access to both sides of the collar before committing both hands.',grips:['Feed the first hand deep into the opposite collar, palm up, aiming to bring the wrist/forearm close to the side of the neck.','The second hand reaches underneath or over the first arm to the opposite collar. Keep both elbows structurally close rather than flaring.'],baseManipulation:'Break posture so the opponent cannot simply sit tall and pull their neck away. Your closed guard and knees keep their torso connected to you while the grips occupy both sides of the neck.',bodyPosition:'Stay connected underneath the opponent with your shoulders active and knees drawing them toward you. Do not sacrifice all hip control just to reach deeper.',steps:['Break posture and open the collar enough to establish the first deep cross-collar grip.','Secure the second collar grip on the opposite side.','Keep your wrists aligned along the sides of the neck and elbows close.','Use your guard and upper body to keep the opponent’s posture down.','Draw the elbows toward your ribs/hips while expanding your chest and keeping the forearms connected to the neck.','Apply gradually and release immediately on the tap.'],finish:'Maintain closed-guard control while gradually tightening both sides of the neck; do not explosively yank the collars.',mechanism:'The two forearms/wrists compress the carotid regions from opposite sides while posture control prevents the opponent from creating space.',cues:['First grip deep.','Break posture before chasing the second grip.','Elbows close.','Use the guard to keep them connected.'],mistakes:['First grip too shallow.','Trying to squeeze with the arms while the opponent is upright.','Flaring the elbows and creating space.'],troubleshooting:[{problem:'My arms burn but there is little choking pressure.',fix:'Check grip depth, wrist position, and posture control before squeezing harder.'},{problem:'They posture out while I reach for the second grip.',fix:'Re-break posture and use your legs before committing the second hand.'}],reactions:['If they defend the second grip, use the hand fight to create angles for armbar/triangle attacks.'],followUps:['Armbar from closed guard','Triangle from closed guard','Scissor Sweep'],variations:['Palm-up cross choke','Academy-specific over/under second-hand finishes'],drilling:['Practice first-grip depth and posture breaking without finishing.','Add the second grip and slow finish with immediate release.']},
'Armbar from closed guard':{goal:'Isolate one arm, control the opponent’s posture and shoulder line, then use your hips and legs to apply elbow extension.',setup:'Begin in closed guard with posture broken enough to control one arm above the elbow line.',grips:['Control the target arm at wrist/sleeve and above the elbow as appropriate.','Use a head/collar/shoulder connection to keep the opponent from simply posturing away while you create the angle.'],baseManipulation:'Pull the target arm across/into your center while controlling posture. Your angle removes the opponent’s ability to stack squarely before your legs are in position.',bodyPosition:'Pivot your hips so your body becomes perpendicular rather than staying square underneath. One leg controls the upper back/shoulder; the other clears over the head.',steps:['Break posture and isolate the target arm.','Keep the elbow above your hip line and prevent the arm from retracting.','Open the guard and pivot your hips to create a strong angle.','Bring the near leg high over the opponent’s back/shoulder to control posture.','Swing the other leg over the head without releasing the arm.','Pinch the knees and control the wrist so the thumb/elbow orientation is correct.','Control posture before extending the hips gradually for the finish.'],finish:'Keep the knees connected, heels active, and extend the hips gradually against the elbow joint. Release immediately on the tap.',mechanism:'Your hips become the fulcrum under the elbow while your legs control the opponent’s head/shoulders and the wrist prevents the arm from rotating free.',cues:['Elbow above your hips.','Angle first.','Leg over the head before extending.','Knees tight; finish slowly.'],mistakes:['Trying to armbar while square underneath.','Crossing the ankles loosely and letting the knees separate.','Losing the arm while swinging the leg over the head.','Extending before controlling posture.'],troubleshooting:[{problem:'They pull the arm free.',fix:'Keep the elbow captured above your hip line and maintain wrist/upper-arm control during the pivot.'},{problem:'They stack me.',fix:'Create the angle earlier and keep posture controlled with the leg over the upper back/head.'}],reactions:['If they retract the elbow, transition to triangle/omoplata opportunities created by the arm movement.'],followUps:['Triangle from closed guard','Omoplata','Sweep from failed armbar'],variations:['Standard closed-guard armbar','Angle armbar'],drilling:['Pause at each checkpoint: arm isolated, angle created, leg over head, knees connected.','Add posture resistance before adding full submission resistance.']},
'Triangle from closed guard':{goal:'Trap the opponent’s neck and one arm between your legs, create an angle, and compress both sides of the neck.',setup:'Begin in closed guard and create a one-arm-in/one-arm-out relationship while controlling posture.',grips:['Control wrists/sleeves or collar/head as needed to put one arm inside your leg line and the other outside.','Once the triangle is entered, control the head/posture so the opponent cannot simply rise away.'],baseManipulation:'Break posture and isolate one shoulder inside the choke. Cutting an angle makes the trapped shoulder help close one side of the neck.',bodyPosition:'Bring one leg over the neck/shoulder, lock the figure-four with the other leg, then pivot so you are looking more toward the opponent’s ear than straight up their centerline.',steps:['Break posture and establish one arm in, one arm out.','Bring the choking leg high over the opponent’s neck/shoulder.','Control the head/posture and lift your hips if needed to clear the arm.','Lock your ankle behind the opposite knee rather than over the foot.','Pivot your hips to create an angle and bring the opponent’s trapped arm across as appropriate.','Pull the shin/knee line into position, flex the feet, and squeeze the knees while maintaining posture control.','Finish gradually and release on the tap.'],finish:'Use angle and leg structure, not only adductor strength. Maintain head control until the choke is secure.',mechanism:'One thigh compresses one side of the neck while the opponent’s trapped shoulder is driven into the other; the figure-four closes the space.',cues:['One arm in, one arm out.','Leg high on the neck.','Angle before squeeze.','Lock behind the knee, not on the foot.'],mistakes:['Staying square underneath.','Triangle locked over the foot/ankle incorrectly.','Opponent’s shoulder not driven into the neck.','Trying to squeeze before controlling posture.'],troubleshooting:[{problem:'There is lots of space around the neck.',fix:'Re-angle, pull the shin tighter, and ensure the trapped shoulder is actually inside the choke structure.'},{problem:'They posture up.',fix:'Control the head/posture before spending energy squeezing.'}],reactions:['If they hide the trapped arm or turn, use the angle for armbar/omoplata transitions.'],followUps:['Armbar from closed guard','Omoplata','Sweep'],variations:['Standard triangle','Angle/cutting triangle'],drilling:['Drill one-arm-in entry and angle before finishing.','Add partner posture resistance progressively.']},
'Kimura from closed guard':{goal:'Control the wrist and shoulder with a figure-four, create an angle, and apply controlled internal shoulder rotation.',setup:'Begin in closed guard when the opponent posts a hand or leaves an arm available near the mat.',grips:['Secure the opponent’s wrist with your same-side hand.','Reach over/around the upper arm with your other hand and grip your own wrist to form the figure-four.'],baseManipulation:'Sit up and connect your torso to the opponent’s shoulder so they cannot simply straighten the arm or posture away. Break their hand/arm away from a strong post.',bodyPosition:'Angle your hips and upper body toward the trapped arm. Keep the opponent’s elbow bent and your figure-four tight to your body.',steps:['Control the wrist and sit up toward the target shoulder.','Reach over the upper arm and secure your own wrist.','Break the opponent’s posture/hand away from a strong posting position.','Angle your body and keep the elbow bent.','Bring the wrist behind the opponent’s back while keeping the elbow controlled.','Rotate the shoulder gradually without separating your figure-four.'],finish:'Apply slow shoulder rotation while controlling the wrist and elbow. Release immediately on the tap.',mechanism:'The figure-four fixes the wrist and elbow, allowing your body to rotate the humerus at the shoulder while the opponent’s torso is controlled.',cues:['Two-on-one figure-four.','Sit up and connect.','Angle your body.','Move the shoulder, not just the hand.'],mistakes:['Trying to finish while flat.','Loose figure-four.','Letting the opponent straighten the arm.','Cranking the hand without controlling the elbow/shoulder.'],troubleshooting:[{problem:'They straighten the arm.',fix:'Keep the elbow bent and your torso connected; transition if the arm shape is lost rather than forcing it.'}],reactions:['A straightening arm can create alternate arm attacks or posture openings.','If they roll to relieve pressure, follow to top control.'],followUps:['Hip bump / sit-up sweep','Armbar from closed guard','Back take'],variations:['Closed-guard Kimura','Kimura sweep when opponent rolls/posts'],drilling:['Build the figure-four and angle without finishing.','Add controlled resistance to posture and arm straightening.']},
'Guillotine from closed guard':{goal:'Control the opponent’s head/neck as posture collapses and use your arms, torso, and guard to apply a controlled front-head choke.',setup:'Enter when the opponent’s head comes low or you can snap/control it below your chest/arm line.',grips:['Wrap the neck with the choking arm and secure an appropriate guillotine grip taught by your academy.','Use the second hand to reinforce the choking hand/wrist while keeping the opponent’s head captured.'],baseManipulation:'Keep the opponent’s posture folded and prevent them from driving their head/shoulder to a safe side. Your guard controls distance and limits their ability to circle free.',bodyPosition:'Keep the choking-side connection tight and use your torso angle rather than pulling only with the arms. Closed guard may be used to control the hips while you adjust.',steps:['Capture the head as the opponent’s posture lowers.','Secure your guillotine grip without leaving large space around the neck.','Control their hips/posture with your guard.','Adjust your angle so your torso and forearm structure reinforce the choke.','Keep the head trapped and remove slack from the grip.','Apply pressure gradually according to the guillotine variation.'],finish:'Finish with controlled pressure and release immediately on the tap; neck attacks should never be applied explosively.',mechanism:'The grip and torso position compress the neck while the guard prevents the opponent from easily posturing/circling away.',cues:['Capture posture first.','Remove slack.','Use your torso, not only your arms.','Finish slowly.'],mistakes:['Trying to pull the head off with arm strength.','Allowing the opponent to posture/circle to the safe side.','Loose grip with space around the neck.'],troubleshooting:[{problem:'My arms fatigue quickly.',fix:'Reassess grip depth, torso angle, and hip control instead of squeezing harder.'}],reactions:['If they defend the neck and drive forward, use the reaction to sweep or improve top position rather than burning out your arms.'],followUps:['Hip bump / sit-up sweep','Sweep to top','Front headlock'],variations:['Arm-in and arm-out guillotine structures vary; use your academy’s preferred mechanics.'],drilling:['Practice capture and grip placement without finishing.','Add posture/circling defense at low resistance.']},
'Omoplata':{goal:'Use your legs to isolate an arm and rotate the opponent’s shoulder while controlling their posture and ability to roll away.',setup:'Enter from guard when one arm can be separated and your leg can pass over the opponent’s shoulder line.',grips:['Control the target wrist/sleeve so the arm remains trapped as your leg clears the shoulder.','Control the waist/belt/hip or far side as needed to prevent the opponent from simply rolling or posturing out.'],baseManipulation:'Break posture and turn the opponent’s shoulder toward the mat. Prevent their forward roll/escape before trying to finish.',bodyPosition:'Pivot so your legs point away from the opponent rather than staying square. Sit up toward their hip/back while keeping the trapped shoulder connected to your legs.',steps:['Isolate the target arm and create enough angle for your leg to clear the shoulder.','Bring the leg over the shoulder and trap the arm between your thighs.','Pivot your hips so you face away/alongside the opponent.','Sit up and control the opponent’s waist/hip to prevent the roll.','Flatten or lower their posture toward the mat.','Scoot/angle your hips away as needed while keeping the shoulder trapped.','Apply gradual shoulder rotation by sitting forward/up with control.'],finish:'Control the roll first, then apply the shoulder lock gradually. Release immediately on the tap.',mechanism:'Your legs control the upper arm while your body rotation fixes the shoulder and turns the opponent’s torso away from the trapped limb.',cues:['Angle before finish.','Control the roll.','Sit up—do not stay flat.','Keep the shoulder trapped.'],mistakes:['Trying to finish while square/flat.','Failing to control the opponent’s hip/waist.','Letting the arm slip free during the pivot.'],troubleshooting:[{problem:'They forward-roll out.',fix:'Control the hip/waist and sit up before applying the finish.'},{problem:'I cannot sit up.',fix:'Create more hip angle and use your free hand/leg to build height rather than pulling only on the arm.'}],reactions:['If they roll, follow and establish top position.','If they posture before the shoulder is trapped, return to guard attacks instead of forcing it.'],followUps:['Triangle from closed guard','Armbar from closed guard','Top control after roll'],variations:['Standard omoplata','Omoplata sweep'],drilling:['Drill the pivot and sit-up separately from the submission.','Add roll prevention, then progressive escape resistance.']},
'Hip bump / sit-up sweep':{goal:'Exploit an opponent who postures back by sitting up, controlling a posting arm, and driving your hips through their base to reverse to top.',setup:'Begin in closed guard as the opponent’s torso becomes upright or their weight shifts backward.',grips:['Post one hand behind you for base as you sit up.','Use the other arm to control/trap the opponent’s arm on the sweep side, commonly overhooking or controlling near the elbow so they cannot post.'],baseManipulation:'The opponent’s backward posture puts weight behind their knees. Trap the arm they need to post and drive your hips diagonally through the remaining base.',bodyPosition:'Sit up tall and bring your chest close to the opponent rather than trying to sweep from your back. Your hips must rise off the mat and connect to their torso.',steps:['Recognize the opponent sitting/posturing backward.','Open the guard and sit up quickly, posting one hand behind you.','Bring your hips close to the opponent and control the posting arm on the sweep side.','Plant your feet/leg position so you can elevate the hips.','Drive your hips up and diagonally through the opponent while rotating toward the trapped-arm side.','Follow the opponent to the mat and establish mount/top control.'],finish:'Come all the way to top; do not celebrate the tip while remaining seated.',mechanism:'You remove the opponent’s near post while your rising hips move their center beyond the backward/side edge of their kneeling base.',cues:['They posture back → you sit up.','Hip to chest.','Trap the post.','Drive diagonally, then follow.'],mistakes:['Trying to sweep from flat guard.','Sitting up but leaving the hips far away.','Failing to trap the posting arm.','Falling back after they tip.'],troubleshooting:[{problem:'They post and stop the sweep.',fix:'Control the arm on the sweep side before driving.'},{problem:'I cannot move their weight.',fix:'Get your hips closer and higher; the movement is a hip drive, not an arm pull.'}],reactions:['If they drive forward to stop your sit-up, use the posture change for guillotine/Kimura/closed-guard attacks.'],followUps:['Kimura from closed guard','Guillotine from closed guard','Mount'],variations:['Hip-bump sweep','Sit-up sweep'],drilling:['Partner alternates upright and forward posture; choose hip bump only on the upright reaction.','Finish every rep by stabilizing mount.']},
'Flower sweep':{goal:'Use an isolated arm, a strong hip angle, and leg elevation to rotate a kneeling opponent over a compromised post into top position.',setup:'Begin in closed guard with posture controlled and one arm isolated so the opponent cannot post freely on the sweep side.',grips:['Control the sleeve/wrist on the side that must not post.','Use the other hand to control the opposite leg/pants or upper body according to your academy’s version.'],baseManipulation:'Take away one hand post and elevate/redirect the opponent’s weight while controlling a leg or far-side base so they cannot widen out.',bodyPosition:'Pivot your hips to create an angle. Your sweeping leg should be able to make a broad pendulum/flower motion rather than pushing straight upward.',steps:['Break posture and control the posting arm.','Create an angle by pivoting your hips.','Secure the leg/pants or other secondary control used in your version.','Open the guard while keeping upper-body connection.','Swing the free leg in a broad arc to generate rotation and lift.','Use the grips to guide the opponent over the missing post.','Follow the rotation immediately to mount/top.'],finish:'Arrive on top with control, commonly mount, and stabilize before releasing grips.',mechanism:'The isolated arm removes a post while the leg arc and hip angle rotate the opponent’s center over the remaining base.',cues:['Kill the post.','Create angle.','Big relaxed leg arc.','Follow to top.'],mistakes:['Trying to muscle the opponent with a small leg movement.','No hip angle.','Letting go of the posting arm too early.'],troubleshooting:[{problem:'They catch themselves.',fix:'Recheck the arm/post control and whether your secondary grip is limiting their base.'}],reactions:['If the opponent retracts the controlled arm, use the movement to transition to another guard attack.'],followUps:['Mount','Armbar from closed guard','Pendulum sweep'],variations:['Flower sweep with pants/leg control','Armbar-to-flower sweep connection'],drilling:['Practice the hip pivot and leg arc without resistance.','Add post-control resistance progressively.']},
'Pendulum sweep':{goal:'Use a strong perpendicular angle and pendulum leg motion to elevate/rotate the opponent while controlling the arm and far-side base.',setup:'Begin from closed guard with one arm isolated and posture sufficiently controlled to create a deep angle.',grips:['Control the arm on the sweep side so it cannot post.','Use the other hand to control the far leg/pants or another anchor that limits the opponent’s base.'],baseManipulation:'Remove the hand post and control the far leg while your legs rotate the torso over the remaining base.',bodyPosition:'Pivot deeply so your torso is angled across the opponent. One leg helps load/elevate while the other swings in a pendulum arc.',steps:['Control the posting arm and break posture.','Pivot to a strong angle rather than remaining square.','Secure the far leg/pants/base.','Open the guard while maintaining connection.','Use one leg to load/elevate the opponent and swing the other leg in a broad pendulum motion.','Rotate the opponent toward the missing post.','Follow immediately into mount/top control.'],finish:'Complete the rotation and stabilize top position before transitioning.',mechanism:'The deep angle turns your legs into long levers while the controlled arm and leg prevent the opponent from rebuilding a wide base.',cues:['Deep angle.','Control arm and far base.','Pendulum, do not leg-press.','Come up with them.'],mistakes:['Staying square.','Small, tense leg swing.','Losing the arm post.'],troubleshooting:[{problem:'The opponent feels too heavy.',fix:'Increase your angle and load their weight before trying to swing them.'}],reactions:['The same angle can connect to armbar attacks if the opponent resists the sweep.'],followUps:['Armbar from closed guard','Flower sweep','Mount'],variations:['Pendulum sweep','Pendulum-to-armbar chain'],drilling:['Drill the angle and pendulum leg motion slowly.','Add controlled base resistance.']},
'Balloon sweep':{goal:'Use an opponent’s forward pressure and your feet/legs as elevation points to lift their center and redirect them overhead or to the side into top position.',setup:'Use when the opponent is standing or driving forward in a posture your academy teaches for the balloon sweep. Maintain grips before placing the feet.',grips:['Use secure sleeve/collar or upper-body grips that keep the opponent connected while you elevate.','Control enough of the arms that the opponent cannot simply post or disengage as their weight comes forward.'],baseManipulation:'Invite/load the opponent’s weight forward over your hips, then elevate at the moment their center passes over their feet/base.',bodyPosition:'Keep your hips underneath the opponent’s center and your feet placed on safe, effective elevation points taught by your coach; do not extend the knees prematurely.',steps:['Establish grips and manage the opponent’s standing/forward posture.','Place your feet at the appropriate hip/torso elevation points.','Draw the opponent’s weight forward over your hips.','Keep your knees bent until their center is loaded.','Extend/elevate with the legs while guiding with the grips.','Redirect their body past the point where their feet can recover underneath them.','Follow the sweep and establish top control.'],finish:'Use controlled elevation and guide the landing; follow safely to top rather than launching the partner uncontrolled.',mechanism:'The feet act as lifting frames underneath the opponent’s center while the grips prevent disengagement and steer their rotation.',cues:['Load first, extend second.','Hips underneath their center.','Guide the landing.','Control both people’s safety.'],mistakes:['Extending the legs before the opponent is loaded.','Using explosive launch force without steering.','Loose grips that allow disengagement.'],troubleshooting:[{problem:'They simply step back.',fix:'You tried to elevate before their weight committed forward.'}],reactions:['If they refuse forward pressure, transition to other open-guard controls rather than forcing elevation.'],followUps:['Open guard','Top control'],variations:['Academy-specific balloon sweep direction and foot placement'],drilling:['Practice loading/elevation with a cooperative partner and controlled landing.','Add forward-pressure timing gradually.']},
'Ankle pull sweep':{goal:'Exploit a standing opponent by controlling their ankles/posts while disrupting upper-body balance so their feet cannot follow their center.',setup:'Begin from an open/seated/supine guard relationship against a standing opponent.',grips:['Control one or both ankles/pant cuffs according to the version.','Use a collar/sleeve/upper-body connection when available to move the torso opposite the controlled feet.'],baseManipulation:'Fix the feet in place while pulling/pushing the upper body beyond the support line, or remove an ankle as their weight shifts.',bodyPosition:'Stay close enough that your legs can manage distance and you can come up immediately once the opponent sits/falls.',steps:['Establish ankle/pant controls before the opponent freely circles away.','Use your feet/legs and upper-body connection to make the opponent shift weight.','Pull or block the ankle that needs to remain behind as their torso moves.','Guide the opponent backward or sideways beyond their base.','Release/adjust the grips only as needed to come up.','Technical stand or wrestle up immediately into top position.'],finish:'Come to top before the opponent can rebuild a standing base.',mechanism:'A standing person recovers balance by stepping. Controlling the ankle removes that recovery step while their center moves outside the feet.',cues:['Control the step.','Move torso and feet in different directions.','Come up immediately.'],mistakes:['Pulling ankles while the opponent’s center remains perfectly stacked.','Staying seated after they fall.'],troubleshooting:[{problem:'They keep their balance.',fix:'Create upper-body movement first; ankle control alone is not enough if their center remains over the feet.'}],reactions:['If they step the free leg, follow the new base into tripod/sickle-style attacks.'],followUps:['Tripod sweep','Sickle sweep','Technical stand-up'],variations:['Double ankle pull','Single ankle control with upper-body off-balance'],drilling:['Partner stands; create a weight shift before attempting the ankle removal.','Finish every rep by coming to top.']},
'Tripod sweep':{goal:'Control a standing opponent’s ankle while one foot disrupts the hip and the other blocks/hooks the opposite leg, creating a three-point off-balance.',setup:'Begin in open guard against a standing opponent with access to an ankle and hip line.',grips:['Control the ankle on the sweep side firmly enough that the foot cannot step away.','Maintain a sleeve/collar or secondary control when useful, but prioritize the ankle/base relationship.'],baseManipulation:'One foot pushes the hip, the other blocks/hooks the opposite leg, and the hand fixes the near ankle. The opponent cannot step in the direction their center is being moved.',bodyPosition:'Stay square enough to manage both legs but mobile enough to follow the fall. Keep your hips close enough that the hip foot has meaningful leverage.',steps:['Secure the near ankle.','Place one foot on the opponent’s hip on the controlled-ankle side.','Place the other foot/leg behind or around the opposite leg as the blocking/hooking point.','Pull/control the ankle while pushing the hip away.','Use the opposite leg to prevent the recovery step.','As the opponent falls, keep enough control to stop them immediately standing.','Come up to top position.'],finish:'Follow to top while managing the legs so the opponent cannot technical-stand before you.',mechanism:'The three controls—ankle, hip, opposite leg—move the center while eliminating both stepping responses.',cues:['Own the ankle.','Push hip, block opposite leg.','Do not watch them fall—come up.'],mistakes:['Losing the ankle before the opponent is committed.','Hip foot too low/loose to move the center.','No control of the opposite recovery step.'],troubleshooting:[{problem:'They hop and stay standing.',fix:'Strengthen the opposite-leg block/hook and coordinate it with the hip push.'}],reactions:['If they retract one leg, switch to sickle/ankle-pull or wrestle-up options based on the new stance.'],followUps:['Sickle sweep','Ankle pull sweep','Technical stand-up'],variations:['Classic tripod sweep','Tripod from collar-sleeve/open guard'],drilling:['Build the three control points and pause.','Sweep slowly, then race only to establish top position.']},
'Sickle sweep':{goal:'Control one ankle and use your opposite leg as a low sweeping bar while the other foot shifts the opponent’s hips beyond their base.',setup:'Begin in open guard against a standing opponent, commonly as a complement to the tripod sweep.',grips:['Control the ankle that must not step away.','Use available upper-body control to keep the opponent connected while your legs change the base.'],baseManipulation:'Push/redirect the hip while the low sweeping leg removes the far leg and the hand fixes the near ankle.',bodyPosition:'Angle your hips so the sweeping leg can travel low across the opponent’s lower leg rather than kicking upward.',steps:['Secure the near ankle.','Place the opposite-side foot on the opponent’s hip to move their center.','Position the other leg low against/behind the far ankle or lower leg.','Push the hip while pulling/fixing the controlled ankle.','Sweep the far leg with a low sickle-like motion.','Maintain leg/ankle awareness as the opponent falls.','Come up immediately to top.'],finish:'Establish top position before releasing all lower-body controls.',mechanism:'The opponent loses both stepping options: one ankle is held while the other leg is swept as the hip is pushed beyond the support line.',cues:['Sweep low.','Control one ankle; remove the other.','Hip push moves the center.','Come up.'],mistakes:['Kicking high at the knee instead of sweeping low.','No hip movement.','Releasing the controlled ankle early.'],troubleshooting:[{problem:'Their far leg feels immovable.',fix:'Move their hips/weight first so the far foot becomes light before sweeping it.'}],reactions:['If the stance changes, transition to tripod or ankle-pull controls.'],followUps:['Tripod sweep','Ankle pull sweep','Top position'],variations:['Sickle sweep from open guard'],drilling:['Alternate tripod and sickle based on which leg the partner makes light.']},
'Ankle lock submission':{goal:'Control the opponent’s leg and ankle with your arms, ribs, hips, and lower-body position, then apply a straight ankle lock within your ruleset.',setup:'Enter from an academy-approved straight-ankle-lock position with the opponent’s foot captured and your own legs positioned safely.',grips:['Wrap the ankle so the blade of your forearm/wrist sits at the appropriate Achilles/ankle line taught by your coach.','Secure a reinforcing grip that removes slack without twisting into prohibited directions.'],baseManipulation:'Control the opponent’s knee/hip line so they cannot freely rotate, stand, or pull the leg out before you apply the finish.',bodyPosition:'Keep the captured foot tight to your ribs and your spine/hips aligned. Use whole-body extension rather than curling the arm alone.',steps:['Secure the opponent’s leg position before chasing the foot.','Capture the ankle deeply with the forearm at the correct line.','Clamp the foot to your ribs and remove slack from the grip.','Control the opponent’s knee/hip rotation with your leg configuration.','Align your torso and look/lean in the legal finishing direction.','Extend your hips/body gradually while keeping the ankle trapped.','Release immediately on the tap.'],finish:'Apply controlled straight-line ankle pressure only within the ruleset you are training. Never explosively bridge into a foot lock.',mechanism:'The forearm becomes a fulcrum at the ankle while your torso/hip extension bends the foot over that fulcrum and your leg control prevents escape.',cues:['Position before foot.','No slack.','Foot tight to ribs.','Whole body, slow finish.'],mistakes:['Trying to curl with the arms only.','Loose knee/hip control.','Foot too shallow in the armpit/ribs.','Applying prohibited rotational pressure.'],troubleshooting:[{problem:'They pull the foot free.',fix:'Secure the leg/knee line and deepen the ankle capture before extending.'},{problem:'My arms fatigue.',fix:'Remove slack and connect the foot to your ribs so your torso/hips—not biceps—create the finish.'}],reactions:['If the opponent clears the knee/hip line, prioritize position and safe re-guard/top transition rather than chasing the foot.'],followUps:['Top position','Open guard'],variations:['Straight ankle lock; exact leg configurations depend on academy and competition rules.'],drilling:['Drill position and grip without finishing.','Add slow finishing pressure with explicit tap awareness and coach supervision.']},
'Seated guard':{goal:'Use an upright, mobile bottom position to manage distance, establish grips, threaten wrestle-ups/sweeps, and avoid being flattened.',setup:'Sit facing the opponent with a balanced base, knees/feet positioned to move, and hands ready to grip or post safely.',grips:['Seek meaningful first connections: collar/sleeve in gi, wrist/arm/head/leg connections in no-gi.','Keep at least one hand available to post/frame when the opponent tries to collapse your posture.'],baseManipulation:'Make the passer react to your grips, feet, and forward threat. Do not allow them to stand comfortably over a passive seated posture.',bodyPosition:'Stay tall through the spine with your head over your hips enough to move forward. Avoid sitting square on both butt cheeks with your hands behind you.',steps:['Establish a balanced seated stance and protect inside space.','Make first contact with a useful grip rather than reaching without purpose.','Use your feet/shins to manage distance and prevent direct chest-to-chest pressure.','Create an angle instead of backing straight away.','Threaten a wrestle-up, collar drag, ankle control, or sweep so the passer must react.','If the opponent disengages, come forward and reclaim space.','If they collapse your posture, frame and rebuild height before attacking.'],finish:'Seated guard is a hub: finish by taking top, entering a sweep/takedown, or transitioning to a stronger guard rather than remaining static.',mechanism:'An upright posture allows your arms and legs to connect to the opponent while keeping your hips mobile enough to follow, stand, or attack their base.',cues:['Head up, hips mobile.','Make first contact meaningful.','Threaten forward—not only retreat.','If neither person controls the exchange, come up.'],mistakes:['Sitting flat and waiting for the pass.','Both hands posted behind you.','Reaching with straight arms and losing posture.','Backing away without creating an attack.'],troubleshooting:[{problem:'I keep getting flattened.',fix:'Protect your head/inside position, keep a hand available to frame, and rebuild upright posture before attacking.'},{problem:'They disengage and circle away.',fix:'Use the space to come forward/stand rather than following them from your butt.'}],reactions:['A retreating opponent invites you to stand or wrestle up.','Forward pressure creates collar-drag, underhook, shin-to-shin, or guard-transition opportunities.'],followUps:['Seated single · collar drag / wrist grip','Technical stand-up','Tripod sweep'],variations:['Gi seated guard','No-gi seated guard'],drilling:['Start seated versus a standing/kneeling partner; score only by establishing a meaningful connection or coming to top.','Add passing resistance progressively.']},
'Seated single · collar drag / wrist grip':{goal:'Use a collar/wrist connection from seated guard to pull the opponent past their base, connect to a leg/body, and wrestle up to top.',setup:'Begin seated and upright with the opponent within gripping range. Keep your posture mobile enough to move forward onto a knee.',grips:['In gi, a collar grip can drag the opponent’s upper body past their feet while the other hand connects to the leg/body.','A wrist/sleeve grip can remove a post and help you enter the single.','Once you come up, transition from loose hand grips to a strong leg/body connection.'],baseManipulation:'Drag or redirect the upper body so one leg becomes loaded/available. Remove the near post and come up into the space rather than trying to pull the opponent onto you.',bodyPosition:'Get off both butt cheeks and onto your side/knee as you enter. Keep your head connected safely to the opponent and your hips underneath you so you can drive.',steps:['Establish collar and/or wrist/sleeve control from seated guard.','Create a forward/sideways reaction with the drag.','As the opponent steps or posts, connect to the available near leg.','Get onto your side and then up to a knee; do not stay seated while holding the leg.','Bring your head and chest into a strong wrestling position.','Connect your hands around the leg/body as appropriate.','Identify the opponent’s remaining post and remove/trap it.','Drive, turn, or knee-pick according to the reaction and finish on top.'],finish:'Establish top control before releasing the leg/body connection.',mechanism:'The drag moves the opponent’s center and occupies a post; the wrestle-up converts the temporary imbalance into a standing/kneeling takedown rather than relying on a pure bottom sweep.',cues:['Drag → come up.','Do not admire the grip.','Head connected, hips underneath you.','Identify the post, remove it, take top.'],mistakes:['Pulling while remaining seated.','Reaching for the leg before creating a reaction.','Head disconnected from the opponent.','Stopping on the knees instead of finishing to top.'],troubleshooting:[{problem:'They pull the leg away before I can finish.',fix:'Come up sooner and connect your head/chest/body to them instead of holding the leg at arm’s length.'},{problem:'Their posting knee stops me.',fix:'Treat the knee as the problem: trap/remove it and continue the drive rather than starting over.'}],reactions:['If they retreat completely, technical-stand and reset to your standing game.','If they whizzer, improve head position and far-arm safety before closing the hips.'],followUps:['Underhook Knee Pick','Body Lock Trip','Technical stand-up'],variations:['Collar-drag single','Wrist/sleeve wrestle-up'],drilling:['Partner gives one predictable step/post; drag and come to a knee.','Progress to partner choosing retreat, post, or whizzer; solve the first layer and take top.']}
};


const guardTopInstruction:Record<string,Partial<BjjTechnique>>={
'X choke defense':{goal:'Recognize and neutralize cross-collar choking grips from inside guard before trying to open or pass.',setup:'Begin inside the opponent’s closed/open guard as they establish one or both cross-collar grips.',grips:['Control the choking wrist/forearm and the opponent’s gripping sleeve as appropriate.','Use posture and hand fighting to prevent the second deep collar grip or to peel it before the choke structure closes.'],baseManipulation:'Build posture from your knees/feet and hips rather than pulling your neck backward with arm strength. Keep your elbows inside so the bottom player cannot freely pull you forward.',bodyPosition:'Keep your spine organized, chin/neck protected, and hips underneath your shoulders. Do not extend both arms and expose yourself to arm attacks.',steps:['Identify the first deep collar grip early.','Protect the second side of your collar and control the choking wrist/sleeve.','Rebuild posture with your hips and spine while keeping elbows close.','Peel or strip the most dangerous grip using two-on-one leverage when needed.','Clear the second grip before returning both hands to normal guard-opening posture.','Only resume passing once the choking structure is gone.'],finish:'Finish with posture restored, both sides of the neck safe, and your hands back in a defensively responsible guard-opening position.',mechanism:'Cross chokes require deep opposing collar grips and broken posture. Denying grip depth, protecting the second collar, and rebuilding posture removes the choke structure.',cues:['Respect the first deep grip.','Protect the second collar.','Posture with hips/spine, not neck strength.','Defense before pass.'],mistakes:['Ignoring the first grip while beginning a pass.','Trying to yank the head backward against two deep grips.','Extending an arm carelessly while stripping grips.'],troubleshooting:[{problem:'The choke tightens while I posture.',fix:'Stop trying to simply pull away. Control/peel the choking grip and protect the second collar before rebuilding posture.'}],reactions:['Once the grip is cleared, immediately re-establish safe hand position so the bottom player cannot regrip or attack an extended arm.'],followUps:['Open closed guard from knees','Open closed guard standing'],variations:['Two-on-one grip peel','Posture-and-strip defense'],drilling:['Partner progressively establishes first and second grips; top player identifies the danger point and clears before passing.']},
'Armbar defense':{goal:'Protect the elbow line and posture when the bottom player attacks an armbar, then safely extract the arm and return to top guard control.',setup:'Begin inside guard as the opponent isolates an arm and starts creating an angle.',grips:['Connect your threatened hand/arm to your own body or other hand to prevent immediate extension.','Control the opponent’s leg/hip line only after the elbow is protected.'],baseManipulation:'Keep your elbow from being pulled beyond the opponent’s hip line. Square or stack only when doing so safely reduces their angle and prevents leg control.',bodyPosition:'Do not leave the threatened arm straight and disconnected. Keep the elbow bent/connected while moving your torso to recover the elbow line.',steps:['Recognize the arm isolation before the opponent’s leg fully clears your head.','Bend/connect the threatened arm and protect the elbow line.','Prevent the opponent from freely controlling your head with their leg.','Adjust your base and posture to reduce their perpendicular angle.','Create enough space to pull the elbow back below their hip line.','Clear the leg from your head and recover both arms to safe top position.','Resume passing only after the arm is fully free.'],finish:'Finish with elbow recovered, posture/base restored, and no limb left extended in the guard.',mechanism:'The armbar needs your elbow isolated above the opponent’s hip fulcrum plus control of your shoulder/head. Recovering the elbow line removes the lever.',cues:['Protect elbow line first.','Do not yank a straight arm.','Clear head control.','Recover posture after escape.'],mistakes:['Trying to rip the hand out while the elbow remains trapped.','Stacking recklessly without protecting the arm.','Leaving the other arm exposed during the defense.'],troubleshooting:[{problem:'My hand is free but the elbow still hurts.',fix:'Your elbow is still above the fulcrum. Prioritize moving your elbow below the opponent’s hip line before pulling away.'}],reactions:['If the opponent transitions to triangle as you retract, keep track of both arms and immediately address the one-in/one-out configuration.'],followUps:['Triangle defense','Open closed guard standing','Knee slice pass'],variations:['Early elbow-line recovery','Late defensive stacking only under coached, controlled conditions'],drilling:['Start at increasing stages of armbar entry and practice recovering the elbow line without explosive movement.']},
'Triangle defense':{goal:'Prevent or dismantle the one-arm-in triangle structure, restore posture, and safely clear your head/arm before passing.',setup:'Begin when the bottom player has one leg over your neck/shoulder and is attempting to lock the triangle.',grips:['Control the opponent’s hips/leg line and protect the trapped arm from being dragged across.','Use safe frames rather than pushing an arm deeper into the triangle.'],baseManipulation:'Stop the opponent from cutting the finishing angle. Build posture and orient your trapped shoulder so both sides of your neck are not compressed.',bodyPosition:'Keep your base under you and avoid driving forward with your head low. Work to stack/posture only in a way that opens the lock rather than tightening it.',steps:['Recognize the one-arm-in configuration before the figure-four closes.','Keep the trapped arm structurally safe and prevent it from being pulled across your neck.','Control the opponent’s hips/leg so they cannot freely pivot to a finishing angle.','Rebuild posture and create space at the knee/lock line.','Turn/position according to your academy’s escape so the leg lock opens without exposing the arm.','Clear your head and arm completely.','Re-establish top guard/passing control.'],finish:'Finish outside the triangle with both arms accounted for and posture restored.',mechanism:'A triangle needs the opponent’s leg and your own shoulder to compress both sides of your neck. Denying angle, posture break, and shoulder positioning disrupts that structure.',cues:['One arm in = immediate danger.','Do not let them cut the angle.','Protect the trapped arm.','Clear fully before passing.'],mistakes:['Driving deeper into the triangle with broken posture.','Trying to pull the head straight out of a locked triangle.','Ignoring the trapped arm while fighting the legs.'],troubleshooting:[{problem:'The choke gets tighter when I try to escape.',fix:'You are likely giving the opponent angle or driving your trapped shoulder deeper. Rebuild structure before adding force.'}],reactions:['If the triangle opens into an armbar attempt, keep the elbow protected and transition immediately to armbar defense.'],followUps:['Armbar defense','Knee slice pass','Stack pass'],variations:['Early posture defense','Academy-specific late triangle escapes'],drilling:['Begin before the triangle is locked; progressively allow deeper entries while keeping all finishing pressure controlled.']},
'Kimura defense':{goal:'Prevent the bottom player from separating your arm into a damaging figure-four and recover posture/arm position without giving up a sweep.',setup:'Begin inside guard as the opponent controls your wrist and starts sitting up/angling for a Kimura.',grips:['Connect the threatened hand to your thigh, belt/waist, or your other hand as appropriate to stop the arm from being rotated behind you.','Use the free hand/forearm to control the opponent’s upper body only after the threatened shoulder is safe.'],baseManipulation:'Do not allow the bottom player to sit up freely into your shoulder. Re-square their torso and keep your elbow close to your ribs.',bodyPosition:'Keep the threatened elbow tight and shoulder connected to your torso. Avoid posting the hand far outside your base where it can be isolated.',steps:['Recognize wrist control and the opponent sitting toward your shoulder.','Pull the elbow tight to your body and anchor the threatened hand.','Prevent the opponent from freely angling around the shoulder.','Use posture and hip movement to square their torso.','Peel/clear the figure-four once shoulder rotation is no longer available.','Recover both hands to safe guard-control position.'],finish:'Finish with the arm inside your frame, posture restored, and the opponent unable to maintain the figure-four.',mechanism:'Kimura power depends on separating the elbow from the torso and controlling the wrist. Anchoring the hand and elbow reconnects the limb to your body and shortens the lever.',cues:['Elbow to ribs.','Anchor the hand.','Square them up.','Do not let them sit around your shoulder.'],mistakes:['Trying to straighten the arm against a strong figure-four.','Letting the elbow drift away from the body.','Focusing on the hand while allowing the opponent to angle their whole body.'],troubleshooting:[{problem:'They keep using the Kimura to sweep me.',fix:'Your base/posture is being compromised while you hand-fight. Keep the elbow anchored and square their hips/torso before stripping.'}],reactions:['If they abandon the Kimura to hip-bump, widen/post your base without re-exposing the arm.'],followUps:['Open closed guard from knees','Open closed guard standing'],variations:['Early elbow-anchor defense','Grip-break defense'],drilling:['Partner begins with wrist control; top player prevents elbow separation and squares the position.']},
'Guillotine defense':{goal:'Protect the neck, create breathing/neck space, and move your body to the safe side while preventing the bottom player from controlling your posture.',setup:'Begin when your head is captured from top guard or during a guard-opening/passing exchange.',grips:['Immediately control the choking wrist/forearm and reinforce with the second hand as needed.','Use your free arm/body connection to control the opponent’s torso/hip and prevent them from freely angling.'],baseManipulation:'Stop the opponent from folding your head toward their chest and closing their guard/hips around you. Move toward the safer side dictated by the grip rather than pulling straight backward.',bodyPosition:'Keep your neck long, shoulder connected, and base underneath you. Avoid panic-posturing with the neck alone.',steps:['Hand-fight the choking arm immediately.','Create space at the wrist/neck line and protect the airway/neck.','Identify the choking side and move your torso/head toward the appropriate safe side taught by your academy.','Control the opponent’s hips so they cannot freely angle or follow.','Rebuild posture as the grip weakens.','Clear the head completely before returning to passing.'],finish:'Finish with your neck free, posture restored, and hands safely controlling guard position.',mechanism:'A guillotine requires head control plus angle and hip connection. Hand-fighting the wrist while denying angle/hip control removes the opponent’s ability to close the choke.',cues:['Fight the choking hand first.','Move body, not just neck.','Deny angle.','Clear fully before passing.'],mistakes:['Trying to yank the head straight out.','Ignoring the choking wrist.','Driving deeper with no neck protection.'],troubleshooting:[{problem:'Pulling away makes it worse.',fix:'Stop extending the neck against the grip; control the wrist and move your torso toward the safe angle.'}],reactions:['If the opponent opens their guard to adjust, use the space to improve base/position only after the neck is safe.'],followUps:['Open closed guard standing','Knee slice pass'],variations:['Early hand-fight defense','Academy-specific positional guillotine escapes'],drilling:['Start with loose guillotine control and practice hand placement/angle before adding gradual resistance.']},
'Omoplata defense':{goal:'Prevent the opponent from sitting up and controlling your shoulder/hip after their leg traps your arm, then free the shoulder or safely roll to recover position.',setup:'Begin as the opponent pivots their leg over your shoulder for an omoplata.',grips:['Connect the trapped hand/arm to your body when possible.','Use the free hand to control the opponent’s leg/hip or create a safe post without exposing another submission.'],baseManipulation:'Keep the opponent from flattening your shoulder toward the mat and controlling your far hip. Maintain posture or create a controlled roll before the shoulder is immobilized.',bodyPosition:'Turn with the pressure rather than letting the trapped shoulder be pinned while your hips remain square.',steps:['Recognize the leg crossing your shoulder and keep posture as long as possible.','Prevent the opponent from sitting fully upright behind your shoulder.','Control their hip/leg and begin freeing the elbow/shoulder line.','If posture recovery is available, rotate the arm/shoulder free and square up.','If the position requires a roll, roll early and under control before the shoulder is locked.','Follow the roll to a defensible/top position rather than stopping underneath.'],finish:'Finish with the trapped arm free and immediately re-establish positional control.',mechanism:'The omoplata needs the upper arm trapped plus control of your posture/hip. Denying the sit-up or moving before the shoulder is fixed prevents the finishing rotation.',cues:['Do not let them sit up behind you.','Move before the shoulder is pinned.','Roll early if rolling is the escape.','Recover position after the escape.'],mistakes:['Waiting until the shoulder is fully immobilized.','Trying to rip the arm backward against the legs.','Rolling without controlling where you land.'],troubleshooting:[{problem:'I roll but they stay on top of the shoulder.',fix:'You rolled after they already controlled your hip/posture. Address their control earlier and follow the roll into position.'}],reactions:['If they lose leg control during the defense, square up and begin passing rather than leaving the arm extended.'],followUps:['Stack pass','Knee slice pass'],variations:['Posture recovery','Controlled forward-roll escape'],drilling:['Practice recognition and early posture recovery first; add controlled roll escapes only with a partner protecting the shoulder.']},
'Open closed guard from knees':{goal:'Open closed guard from a stable kneeling base while protecting posture and limbs, then immediately establish passing control.',setup:'Begin centered inside closed guard with knees/base stable and hands positioned safely on torso/hip lines.',grips:['Use safe torso/hip/pants controls taught by your academy; avoid posting hands where they can be easily isolated.','Keep elbows inside and hands connected to structural frames rather than straight-arm pushing.'],baseManipulation:'Control the opponent’s hips and prevent them from pulling your posture forward while creating a wedge/angle that separates their ankles.',bodyPosition:'Keep head over hips and spine tall enough to resist posture breaks. Build a staggered or widened kneeling base as required without placing a knee where it is vulnerable.',steps:['Establish safe posture and hand position.','Control the opponent’s hip line so their hips cannot freely follow you.','Create a stable kneeling base and angle one knee/body wedge into the guard-opening structure.','Shift your hips backward/away while maintaining posture and hip control.','Use the wedge and hand position to separate the ankles without prying with the fingers.','Immediately control a knee/leg as the guard opens.','Transition directly into your chosen pass before the opponent establishes open guard.'],finish:'The opening is not complete until you have useful leg/hip control for the next pass.',mechanism:'Posture and hip control stop the bottom player from following while your wedge increases the distance/angle their closed legs must maintain.',cues:['Posture first.','Control hips.','Use a wedge, not finger strength.','Open → immediately control legs.'],mistakes:['Trying to pry the ankles apart with hands.','Leaning forward and giving up posture.','Opening the guard and pausing with no leg control.'],troubleshooting:[{problem:'They keep pulling me forward.',fix:'Rebuild head-over-hips posture and use structural hip control before trying to create distance.'}],reactions:['If they open early, stop the opening motion and immediately establish passing grips/position.'],followUps:['Knee slice pass','Combat base','Bullfighter pass'],variations:['Kneeling wedge opening'],drilling:['Practice opening and immediately freezing with leg control; add the pass only after that connection is automatic.']},
'Knee slice pass':{goal:'Split the opponent’s legs, win upper-body control, and drive your knee/hip line through to side control or a dominant top position.',setup:'Enter from open/half guard with one knee positioned between/over the opponent’s thighs and access to upper-body control.',grips:['Win an underhook or other inside upper-body control on the side you are passing toward when possible.','Use the opposite hand/arm for crossface, collar, shoulder, or hip control to prevent the opponent from turning into you.'],baseManipulation:'Flatten or turn the opponent away from their strongest frames and prevent the bottom knee from reconnecting between your bodies.',bodyPosition:'Point the slicing knee toward the mat on the far side while keeping your hip heavy. Your head/shoulder pressure should support the pass rather than leaning your weight away from the opponent.',steps:['Win inside knee position and control the opponent’s upper body.','Secure underhook/crossface or equivalent controls before committing the hips.','Turn/flatten the opponent so their knee shield/frames cannot square back into you.','Slide the slicing knee across the thigh toward the mat.','Keep your trailing foot/leg free from entanglement as the hip follows.','Clear the opponent’s bottom knee/leg line.','Settle chest-to-chest and establish side control before releasing grips.'],finish:'Stabilize side control or another dominant top pin for several beats before attacking.',mechanism:'Upper-body control prevents the opponent from following your hips while the slicing knee splits the lower-body frames and your hip pressure clears the leg line.',cues:['Upper body before lower body.','Underhook/crossface wins the direction.','Knee to the mat.','Clear the trailing foot.','Settle after pass.'],mistakes:['Trying to knee-slice with no upper-body control.','Leaving the trailing foot trapped.','Passing the legs but allowing the opponent to turn in immediately.'],troubleshooting:[{problem:'Their knee keeps coming back inside.',fix:'Improve upper-body control and hip pressure; do not let their shoulders/hips remain square to you.'},{problem:'My foot gets stuck.',fix:'Address the trailing foot deliberately before declaring the pass complete.'}],reactions:['If they frame strongly into the slice, redirect into backstep/longstep or other passing lane rather than forcing straight through.'],followUps:['Side control','Mount','Backstep'],variations:['Knee slice from open guard','Knee slice from half guard'],drilling:['Start with underhook/crossface already won; rep the leg-clear and stabilization.','Then add resistance at the frame/knee-shield stage.']},
'Chair sit':{goal:'Use a controlled hip sit/rotation to move around the opponent’s legs or transition around a seated/turtle position while maintaining connection.',setup:'Use from a top passing/control situation where your upper-body connection is secure and sitting your hip changes the angle around the opponent’s frames.',grips:['Maintain a strong upper-body connection—seatbelt, underhook/overhook, collar/arm, or academy-specific control—before sitting.'],baseManipulation:'Control the opponent’s shoulders/hips so your sit changes your angle without allowing them to freely turn and face you.',bodyPosition:'Sit to the hip with your torso connected rather than dropping backward away from the opponent. Keep the legs ready to re-base.',steps:['Secure upper-body control.','Choose the hip/direction that takes you around the opponent’s frames.','Sit your hip toward the mat while maintaining chest/shoulder connection.','Swing/reposition the legs around the opponent as the angle changes.','Keep their shoulders controlled so they cannot simply turn into you.','Re-establish your base in the new position.'],finish:'Finish in a stronger passing, back-control, or pinning position with your base restored.',mechanism:'The hip sit changes your angle around the opponent while upper-body control prevents them from rotating with you.',cues:['Connection before sit.','Sit around them, not away.','Control shoulders.','Re-base immediately.'],mistakes:['Sitting without upper-body control.','Falling backward and creating separation.','Failing to re-establish base after the transition.'],troubleshooting:[{problem:'They turn and face me during the sit.',fix:'Your shoulder/upper-body connection was insufficient; secure it before moving the hips.'}],reactions:['If they follow the rotation, use their turn to enter the next control rather than forcing the original endpoint.'],followUps:['Back control','Side control','Knee slice pass'],variations:['Chair-sit passing transition','Chair-sit back-control transition'],drilling:['Practice the hip movement with a cooperative partner while maintaining continuous upper-body connection.']},
'Knee wedge':{goal:'Use the knee as a structural wedge to separate or pin the opponent’s legs/hips and create a passing lane without relying on arm strength.',setup:'Begin from top guard with enough posture and hip control to insert your knee safely between or against the opponent’s leg line.',grips:['Control hips/knees or upper body so the opponent cannot freely rotate around the wedge.'],baseManipulation:'The wedge occupies space the opponent needs to reconnect their knees/guard while your other controls move their hips away from that space.',bodyPosition:'Keep the knee structurally supported by your hip and foot; do not reach it forward while your weight remains behind.',steps:['Establish posture and hip/leg control.','Insert the knee into the available space as a frame/wedge.','Angle the knee so it blocks the opponent’s ability to close or square their legs.','Shift your hips/body around the wedge rather than pushing only with the knee.','Control the newly exposed leg/hip line.','Transition immediately to the appropriate pass.'],finish:'Finish with the guard opened/leg line controlled and a clear passing lane established.',mechanism:'A skeletal knee frame can maintain separation with less muscular effort while your body moves around the opponent’s lower-body structure.',cues:['Knee is a wedge, not a spear.','Support it with your hips.','Control the hip line.','Use the opening immediately.'],mistakes:['Driving the knee forward unsupported.','Inserting the wedge with no control of the opponent’s hips.','Creating space but not transitioning.'],troubleshooting:[{problem:'They simply move around my knee.',fix:'Your wedge is disconnected from hip/upper-body control; control their rotation before relying on the knee.'}],reactions:['If they turn away from the wedge, follow the exposed hip into your next pass.'],followUps:['Knee slice pass','Combat base','Leg drag'],variations:['Guard-opening knee wedge','Passing knee wedge'],drilling:['Practice inserting and holding the wedge while partner slowly changes hip angle.']},
'Combat base':{goal:'Create a stable staggered kneeling/half-standing posture that protects your balance and gives you immediate access to passing.',setup:'Use after opening guard or during transitions where both knees on the mat would make you easy to pull forward or re-close.',grips:['Control a knee/hip and upper-body connection appropriate to the guard while your base changes.'],baseManipulation:'The staggered base gives you a forward post and rear support so the bottom player has fewer easy directions to off-balance you.',bodyPosition:'One knee is typically up with the foot planted while the other knee supports underneath; keep head/shoulders aligned over the base rather than leaning outside it.',steps:['Control the opponent before changing your base.','Bring one foot forward and plant it while the opposite knee remains down.','Keep the planted knee/foot positioned so it cannot be easily collapsed inward.','Maintain posture and control the opponent’s leg/hip line.','Use the base to begin your chosen pass or stand safely.'],finish:'Transition from combat base into a pass without lingering in a static stance.',mechanism:'The staggered base increases your ability to resist forward/sideways kuzushi while freeing one leg to step or drive through a passing lane.',cues:['Base before pass.','Head stays over base.','Protect the planted knee.','Use the stance—do not camp there.'],mistakes:['Planting the foot too narrow and getting tipped.','Leaning outside the base.','Changing stance without controlling the opponent.'],troubleshooting:[{problem:'I get swept as soon as I raise a knee.',fix:'Widen/stabilize the planted foot and establish leg/hip control before changing levels.'}],reactions:['If the bottom player attacks the planted leg, redirect to standing or a different passing base.'],followUps:['Knee slice pass','X pass','Bullfighter pass'],variations:['Combat base after guard opening','Combat base passing stance'],drilling:['Move from kneeling posture to combat base while partner gives light kuzushi.']},
'Double under / stack pass':{goal:'Control underneath both legs, stack the opponent’s hips toward their shoulders, and walk around the leg frames into side control.',setup:'Enter when both of your arms can safely get underneath the opponent’s legs from open guard.',grips:['Thread both arms under the legs and connect hands or control belt/waist/hips according to your academy’s version.','Keep the legs collected so the opponent cannot easily pummel a knee back inside.'],baseManipulation:'Lift/control the hips and fold the knees toward the opponent’s upper body, taking away hip mobility and making the guard point away from you.',bodyPosition:'Keep your head/shoulders connected and spine strong. Stack with body position rather than trying to curl the opponent with your arms.',steps:['Pummel both arms underneath the legs.','Collect the hips/legs tightly and prevent knee re-entry.','Drive forward enough to bring the opponent’s knees toward their chest/shoulders.','Shift your body to one side while maintaining the stack.','Walk around the legs rather than trying to throw them aside.','Clear the hip/knee line.','Lower your chest into side control and stabilize.'],finish:'Settle side control before releasing the leg collection.',mechanism:'Stacking folds the opponent’s hips and removes their ability to face you with active leg frames; walking around then bypasses the guard.',cues:['Collect hips.','Stack with body, not biceps.','Walk around.','Settle before releasing legs.'],mistakes:['Leaving space for a knee/elbow to pummel back inside.','Trying to fling the legs rather than controlling the hips.','Stacking unsafely onto the neck.'],troubleshooting:[{problem:'They keep recovering a knee.',fix:'Tighten the hip/leg collection and keep their hips pointed away while you walk around.'}],reactions:['If they invert/turn, maintain safe hip control and follow the direction rather than forcing neck pressure.'],followUps:['Side control','Over-under · stack pass'],variations:['Double-under stack pass'],drilling:['Practice hip collection and walking around at low pressure; protect partner’s neck throughout.']},
'Over-under · longstep pass':{goal:'Use an over-under leg configuration to control the hips, then longstep around the opponent’s frames into dominant top position.',setup:'Enter from open guard with one arm under a leg and the other controlling over/around the opposite thigh/hip.',grips:['Underhook one leg deeply enough to control its hip connection.','Overhook/control the opposite thigh/hip so the opponent cannot square both knees back toward you.'],baseManipulation:'Pin/turn the hips so the knees point away from your passing direction, then remove your own legs from the opponent’s hooks with the longstep.',bodyPosition:'Keep chest/shoulder pressure connected to the hips/thighs and head positioned safely. Your longstep should move your hips around the legs without releasing upper-body pressure.',steps:['Establish the over-under configuration and connect tightly to the hips.','Angle the opponent’s knees/hips away from the direction you will pass.','Apply shoulder/chest pressure to prevent them from squaring up.','Step your outside leg long and back around the opponent’s leg line.','Rotate your hips as the legs clear.','Follow with the trailing leg and bring your chest above their torso.','Settle side control.'],finish:'Stabilize chest-to-chest control after your legs have fully cleared the guard.',mechanism:'The over-under controls opposing sides of the hip line; the longstep moves your own hips outside the opponent’s leg frames while their hips remain pinned away.',cues:['Own the hips.','Knees point away.','Longstep your hips around the frames.','Chest follows the pass.'],mistakes:['Loose over-under connection.','Stepping before turning/pinning the hips.','Clearing the legs but leaving the upper body disconnected.'],troubleshooting:[{problem:'They square back up as I step.',fix:'Improve hip control and shoulder pressure before moving your legs.'}],reactions:['If they frame into the longstep, redirect into stack/over-under pressure rather than abandoning hip control.'],followUps:['Side control','Over-under · stack pass'],variations:['Over-under longstep'],drilling:['Pause with hip control established, then rep only the longstep and stabilization.']},
'Over-under · stack pass':{goal:'Control the opponent’s hips with an over-under configuration, stack/fold the leg line, and walk around to side control.',setup:'Enter with one arm underneath a leg and the other over/around the opposite thigh/hip.',grips:['Underhook one leg and connect to hip/waist.','Control the opposite thigh/hip over the top to stop the knees from squaring.'],baseManipulation:'Fold the hips/knees toward the opponent while keeping the knees turned away from your passing direction.',bodyPosition:'Keep pressure through your shoulder/chest and use your legs to drive/walk rather than arm-curling the opponent.',steps:['Secure tight over-under control.','Bring your chest/shoulder pressure into the hip/thigh line.','Drive the knees toward the torso enough to limit hip extension.','Angle the knees away from your passing direction.','Walk your feet/body around the controlled legs.','Clear the knee/hip line while maintaining pressure.','Settle into side control.'],finish:'Maintain hip control until your torso has replaced the leg-control pressure in side control.',mechanism:'The over-under prevents independent leg movement while stacking reduces hip mobility, allowing your whole body to circle around the guard.',cues:['Tight over-under.','Fold hips safely.','Walk—do not arm wrestle.','Replace leg control with chest control.'],mistakes:['Loose hip connection.','Trying to pass with arms instead of moving feet/body.','Unsafe pressure into the neck.'],troubleshooting:[{problem:'They keep making space with their hips.',fix:'Close the gap at the hip line and angle their knees before walking around.'}],reactions:['If the opponent extends to resist the stack, switch to longstep while preserving over-under control.'],followUps:['Over-under · longstep pass','Side control'],variations:['Over-under stack pass'],drilling:['Alternate longstep and stack finish based on partner’s hip reaction.']},
'Open closed guard standing':{goal:'Stand safely inside closed guard, control the opponent’s hips/posture, open the ankles, and immediately establish a passing position.',setup:'Begin inside closed guard with safe posture and hand placement before bringing a foot up.',grips:['Use secure torso/collar and hip/pants controls appropriate to your academy so the opponent cannot pull you forward as you stand.','Keep elbows protected from arm attacks.'],baseManipulation:'Stand one leg at a time with posture and hip control, then create downward/away pressure at the hip/knee line so the opponent cannot keep their ankles locked.',bodyPosition:'Head stays over hips and feet form a stable staggered stance. Avoid bending at the waist with your head over the opponent.',steps:['Establish posture and safe grips.','Bring the first foot up without letting your knee collapse inward.','Stand the second leg while keeping your spine tall and hips underneath you.','Control the opponent’s hip line so they cannot climb their guard higher.','Create the opening by pushing/angling the knee/hip line as taught rather than prying the ankles.','As the guard opens, immediately step/control the legs.','Enter your chosen standing pass.'],finish:'Finish in a stable open-guard passing stance with leg control—not merely with the ankles separated.',mechanism:'Standing lengthens the distance the closed legs must maintain while posture/hip control prevents the bottom player from following your center upward.',cues:['Posture before feet.','One foot at a time.','Control hips.','Open → pass immediately.'],mistakes:['Standing with no posture/grips.','Bending forward at the waist.','Opening the guard and leaving both legs uncontrolled.'],troubleshooting:[{problem:'They pull me forward as I stand.',fix:'Rebuild torso/hip control and keep your head stacked over your hips before bringing up the second foot.'}],reactions:['If the opponent opens early to attack your legs, transition immediately to your passing stance instead of insisting on the planned opening.'],followUps:['X pass','Bullfighter pass','Leg drag'],variations:['Staggered standing guard break'],drilling:['Rep stand-up and guard opening separately, then connect directly to one chosen pass.']},
'Leg drag':{goal:'Redirect both of the opponent’s legs to one side, pin the hip line, and move your body around the legs into side/back exposure.',setup:'Enter from open guard when you can control an ankle/shin and redirect the opponent’s knees away from you.',grips:['Control the near ankle/shin/pants and the far leg/hip as appropriate.','Transition quickly to hip/waist/upper-body control once the legs are dragged aside.'],baseManipulation:'Turn the opponent’s knees away from you and pin their hips so they cannot simply square their legs back between you.',bodyPosition:'Step your hips close to the opponent’s hip line. Keep your chest facing their torso while your knees/feet block their ability to rotate back.',steps:['Control the legs and move them together toward one side.','Guide the far leg across your body so both knees point away.','Step your body close to the exposed hip rather than remaining at the feet.','Pin/control the hip and prevent the opponent from turning their knees back toward you.','Move your upper body toward chest/back control.','Clear the legs fully and stabilize side control or back exposure.'],finish:'Finish with hip and upper-body control before releasing the leg drag.',mechanism:'Turning both knees away disconnects the opponent’s leg frames from your torso; pinning the hip prevents them from simply rotating back to guard.',cues:['Knees away.','Close distance immediately.','Pin the hip.','Leg drag becomes body control.'],mistakes:['Dragging the legs but staying far away.','No hip pin.','Trying to run around while the opponent’s knees can freely square back.'],troubleshooting:[{problem:'They recover guard as I move around.',fix:'Close to the hip sooner and control rotation before advancing your chest.'}],reactions:['If they turn away to protect the hip, follow the back exposure rather than forcing side control.'],followUps:['Side control','Back control','Knee slice pass'],variations:['Standing leg drag','Leg drag from headquarters/open guard'],drilling:['Drag, close to hip, pause and verify knees cannot square; then finish the pass.']},
'X pass':{goal:'Use standing posture, leg control, and a quick angle change to redirect the opponent’s legs and step around their hip line.',setup:'Begin standing over open guard with control of a leg/knee/ankle and enough posture to move laterally.',grips:['Control a knee/pants/shin with one hand while the other manages the opposite leg/upper body according to your version.'],baseManipulation:'Pin or redirect one leg while moving your feet outside the opponent’s knee line faster than their hips can follow.',bodyPosition:'Stay tall/mobile with knees bent enough to change direction. Do not lean your chest over the opponent while your feet remain far away.',steps:['Establish standing leg control.','Pin/redirect the near knee or shin away from your passing lane.','Create the X-like leg/hand movement that clears your path around the hip.','Step laterally around the opponent’s knees.','Bring your hips close to the exposed side before they can re-square.','Transition your hands from leg control to hip/upper-body control.','Settle side control or knee-on-belly.'],finish:'Close distance and stabilize; the speed pass is incomplete if you remain standing at the feet.',mechanism:'The pass combines a momentary leg pin with fast lateral footwork so your hips cross the opponent’s knee line before their guard can rotate to follow.',cues:['Pin leg, move feet.','Pass the knee line.','Close distance after speed.','Hands transition from legs to body.'],mistakes:['Trying to run around without first redirecting a leg.','Staying far away after clearing the feet.','Leaning forward and losing mobility.'],troubleshooting:[{problem:'They follow me with their knees.',fix:'Improve the initial leg pin/redirect and step closer to the hip once you clear the knee line.'}],reactions:['If they retract the controlled leg, switch to bullfighter/leg-drag controls based on the new hip angle.'],followUps:['Knee-on-belly','Side control','Leg drag'],variations:['Standing X pass'],drilling:['Rep the footwork around a cooperative guard, then add active hip-following resistance.']},
'Bullfighter pass':{goal:'Control and redirect the opponent’s legs while moving laterally around the hip line into side control or knee-on-belly.',setup:'Begin standing against open guard with access to both pant legs/knees/shins or equivalent no-gi controls.',grips:['In gi, control pants near the knees/shins as appropriate; in no-gi use shin/ankle/knee-line controls.','Keep your arms connected to your body so the opponent cannot easily extend you away.'],baseManipulation:'Push/steer the knees away from the direction you are moving and make the opponent’s hips point away while your feet circle around.',bodyPosition:'Stay mobile on your feet with your head/hips balanced. Use lateral movement rather than diving your chest into the legs.',steps:['Establish control of both legs.','Move the opponent’s knees toward one side while you step toward the opposite exposed hip.','Keep the knees pinned/redirected long enough to pass their knee line.','Circle your feet around the legs instead of trying to throw the legs across the room.','Close the distance to the hip/torso immediately.','Transition from leg grips to hip/upper-body control.','Settle side control or knee-on-belly.'],finish:'Finish chest/hip connected in top control; do not remain standing at the edge of the guard.',mechanism:'The grips temporarily point the opponent’s knees away while your lateral footwork moves your center beyond their leg frames.',cues:['Move knees one way, body the other.','Feet do the passing.','Clear knee line.','Close distance.'],mistakes:['Trying to bench-press the legs aside.','Standing still while moving only the arms.','Clearing legs but failing to control hips.'],troubleshooting:[{problem:'They keep re-guarding as I circle.',fix:'Keep the knees pointed away until your hips/chest close the distance to their exposed side.'}],reactions:['If they stiff-arm or turn, redirect into leg drag/X-pass lanes instead of forcing the same circle.'],followUps:['Knee-on-belly','Side control','Leg drag'],variations:['Gi toreando/bullfighter pass','No-gi shin-control bullfighter'],drilling:['Partner actively follows with hips while top player practices steering knees and changing lateral direction.']}
};


const halfGuardTopInstruction:Record<string,Partial<BjjTechnique>>={
'Knee slice from half guard':{goal:'Flatten the bottom player, win upper-body control, free your trapped knee/foot, and convert half guard into side control.',setup:'Begin on top of half guard with one leg trapped between the opponent’s legs.',grips:['Fight for a crossface/head control and an underhook on the far side when available.','Use the free hand/forearm to manage the opponent’s knee shield, hip, or near-side frame.'],baseManipulation:'Turn the opponent away from their strongest underhook and flatten their shoulders. Once their torso cannot freely rotate, their legs have much less ability to retain your trapped leg.',bodyPosition:'Keep chest pressure connected and point the trapped knee toward the mat on the far side. Your free leg/base stays wide enough to resist bridges and wrestle-ups.',steps:['Win the head-and-arm battle before focusing on your trapped foot.','Flatten the opponent with crossface/underhook or equivalent upper-body control.','Clear or collapse the knee shield if present.','Slide your trapped knee across the opponent’s thigh toward the mat.','Keep hip pressure as the knee clears the half-guard line.','Use your free foot/leg to peel or windshield-wiper the trapped foot free.','Replace leg pressure with chest-to-chest side control and stabilize.'],finish:'Settle side control before releasing the crossface/underhook structure.',mechanism:'Flattening removes the bottom player’s hip rotation and underhook-based offense; the knee slice then separates their legs while pressure prevents re-guard.',cues:['Win upper body first.','Flatten them.','Knee clears before foot.','Do not celebrate until the foot is free.'],mistakes:['Trying to yank the trapped foot out while the opponent is on their side.','Knee slicing without upper-body control.','Letting the bottom player win the underhook.'],troubleshooting:[{problem:'My foot stays trapped after my knee clears.',fix:'Keep pressure and use your free foot/hip angle to peel the remaining hook rather than pulling straight backward.'},{problem:'They wrestle up underneath me.',fix:'Re-win the underhook/head position before committing your hips to the pass.'}],reactions:['If they frame hard into the slice, redirect into backstep or pressure passing while preserving upper-body control.'],followUps:['Side control','Mount','Back step'],variations:['Half-guard knee slice','Tripod-style knee slice finish'],drilling:['Start with crossface/underhook already won and rep knee-then-foot clearing.','Then start neutral and make winning upper-body control the first scoring objective.']},
'Stack pass from half guard':{goal:'Fold and control the bottom player’s hips/leg line enough to free the trapped leg and walk around into dominant top control.',setup:'Begin in top half guard when you can collect/control the opponent’s legs and turn their hips away from you.',grips:['Control the opponent’s lower-body frame at the thigh/knee/hip line and maintain enough upper-body connection that they cannot freely sit up.'],baseManipulation:'Bring the knees/hips toward the torso while turning the bottom player away from a square guard-retention posture.',bodyPosition:'Drive with your legs and torso rather than curling with the arms. Keep pressure distributed safely and avoid forcing the opponent onto the neck.',steps:['Control the upper body enough to stop the wrestle-up.','Collect the opponent’s leg/hip line.','Fold the knees toward the torso enough to reduce hip extension.','Angle the hips away from your passing direction.','Walk your body around while maintaining the fold.','Free your trapped knee and then foot as the hip angle opens.','Settle side control.'],finish:'Replace lower-body control with chest/hip control once your leg is fully free.',mechanism:'Folding reduces the bottom player’s ability to extend and rotate their hips, making the half-guard clamp easier to clear while you circle around.',cues:['Control torso before legs.','Fold hips safely.','Walk around.','Knee then foot.'],mistakes:['Stacking without controlling the upper body.','Trying to arm-curl the legs.','Driving pressure dangerously into the neck.'],troubleshooting:[{problem:'They keep turning onto their side and recovering.',fix:'Control their shoulders/upper body and keep the hips pointed away before walking around.'}],reactions:['If they strongly extend against the stack, switch to longstep/backstep direction rather than forcing the fold.'],followUps:['Side control','Over-under · longstep from half guard'],variations:['Half-guard stack pass'],drilling:['Rep the fold and walk-around at low pressure, protecting the partner’s neck throughout.']},
'Over-under · longstep from half guard':{goal:'Use over-under hip control to turn the opponent’s knees away, longstep your hips around the trapped leg, and establish side control.',setup:'Begin in top half guard with access to an over-under configuration around the opponent’s thighs/hips.',grips:['Underhook/control one leg deeply while controlling over the opposite thigh/hip.','Keep the controls tight to the opponent’s pelvis rather than holding at the ends of the legs.'],baseManipulation:'Turn the knees away from your passing direction and pin the pelvis so the bottom player cannot square back underneath you.',bodyPosition:'Keep chest/shoulder pressure connected to the hip line while your outside leg makes the longstep.',steps:['Secure tight over-under control.','Angle the opponent’s knees away from your passing side.','Apply shoulder/chest pressure to pin the hip line.','Longstep your outside leg back and around the opponent’s legs.','Rotate your hips while keeping the trapped leg controlled.','Free the remaining foot/knee as your chest moves toward the torso.','Settle side control.'],finish:'Finish chest-to-chest with the hips controlled and your legs completely outside their guard.',mechanism:'The over-under fixes the pelvis while the longstep changes your hip angle around the leg entanglement instead of pulling the trapped leg straight out.',cues:['Own hips.','Knees away.','Longstep around, not backward.','Chest follows hips.'],mistakes:['Loose over-under connection.','Stepping before turning the hips.','Creating separation between chest and pelvis.'],troubleshooting:[{problem:'They square back up during the step.',fix:'Increase hip pin/shoulder pressure and turn their knees away before moving your feet.'}],reactions:['If they curl tightly into the longstep, transition to stack/pressure passing while keeping the over-under.'],followUps:['Side control','Over-under · under / stack pass from half guard'],variations:['Half-guard over-under longstep'],drilling:['Pause after establishing hip control; longstep only when partner’s knees are clearly pointed away.']},
'Over-under · under / stack pass from half guard':{goal:'Control both sides of the hip line, fold the opponent’s legs, and walk around the half guard without giving their hips room to square.',setup:'Begin in top half guard with an over-under or under/stack leg-control configuration.',grips:['Keep one arm under a leg connected to the waist/hip and the other controlling the opposite thigh/hip.'],baseManipulation:'Fold the knees toward the torso and turn them away so the opponent cannot use the half-guard clamp as a mobile frame.',bodyPosition:'Use shoulder pressure and your walking base to create the pass; avoid reaching your arms away from your torso.',steps:['Establish tight leg/hip controls.','Prevent the bottom player from winning an upper-body underhook.','Fold the leg line toward the torso.','Turn the knees away from the side you will pass.','Walk your feet and hips around the controlled legs.','Clear the trapped knee and foot.','Replace leg control with chest-to-chest side control.'],finish:'Stabilize side control with the opponent’s hips and shoulders pinned before releasing the pass grips.',mechanism:'The stack shortens the bottom player’s hip extension while the over-under prevents independent leg pummeling, letting your whole body circle around the entanglement.',cues:['Tight hip connection.','Fold then walk.','No arm wrestling.','Replace with chest pressure.'],mistakes:['Loose control at the pelvis.','Walking before the knees are turned.','Ignoring the bottom underhook.'],troubleshooting:[{problem:'They keep pummeling a knee back inside.',fix:'Close space at the pelvis and keep both knees controlled as you circle.'}],reactions:['If they extend their hips to resist folding, redirect into longstep rather than forcing the stack.'],followUps:['Side control','Over-under · longstep from half guard'],variations:['Half-guard under/stack pass'],drilling:['Alternate stack and longstep based on partner’s extension/folding reaction.']},
'Z pass · front or back':{goal:'Use the opponent’s knee-shield/Z-guard structure as a reference point, pin the hips, and pass either in front of or behind the knee depending on their reaction.',setup:'Begin on top against a knee shield/Z guard with posture and enough distance to control the knees/hips.',grips:['Control the knee/shin and hip line so the shield cannot freely follow your chest.','Add upper-body control as the passing lane opens.'],baseManipulation:'Pin or redirect the shield while moving your hips to an angle where the bottom player cannot keep both knees between you.',bodyPosition:'Stay balanced over your feet/knees and move laterally; do not lean your torso into the shield while your hips remain stationary.',steps:['Control the shield knee and the opponent’s hip/other leg.','Apply pressure that fixes the knee line long enough to create an angle.','Read whether the space is opening in front of or behind the shield.','Step/drive your hips through the available lane.','Clear your own knee/foot beyond the opponent’s leg line.','Transition hands from leg control to upper-body control.','Settle side control.'],finish:'Finish with chest/hip control after both knees are no longer between you.',mechanism:'The pass works by fixing the knee shield while your hips move around it; choosing front/back prevents you from forcing against the strongest frame.',cues:['Pin shield.','Move hips, not just hands.','Take the open lane.','Control body after legs.'],mistakes:['Trying to smash directly through an active knee shield.','Moving arms without changing hip angle.','Clearing one knee but leaving the other inside.'],troubleshooting:[{problem:'Their knee follows me everywhere.',fix:'Improve the hip/knee pin before committing your lateral movement.'}],reactions:['If the shield retracts, enter the front lane; if it stiffens/turns, circle behind according to your control.'],followUps:['Side control','Knee slice from half guard','Back step'],variations:['Front Z pass','Back-side Z pass'],drilling:['Partner alternates shield pressure; top player identifies front/back lane before moving.']},
'Wet blanket pass':{goal:'Use continuous chest/hip pressure and incremental positional wins to immobilize the bottom player, free the trapped leg, and settle side control.',setup:'Begin top half guard with enough upper-body contact to keep the opponent carrying your weight.',grips:['Use crossface, underhook, shoulder/head, and hip controls to keep the torso pinned.','Connections should transfer bodyweight rather than become arm-strength grips.'],baseManipulation:'Flatten the opponent and deny the space required for knee insertion, underhook wrestle-up, or hip rotation.',bodyPosition:'Keep your center heavy and connected. Adjust posts only enough to follow bridges without lifting your weight completely off the opponent.',steps:['Win head-and-arm control and flatten the opponent.','Settle chest/hip weight so they must move you before rebuilding guard.','Walk your trapped knee incrementally toward freedom.','Follow bridges and hip escapes with your pressure rather than chasing submissions.','Clear the knee line while keeping shoulders pinned.','Peel/free the foot with small hip/leg adjustments.','Settle side control and only then transition to offense.'],finish:'A stable pin after the leg is free; the opponent should not get an immediate re-guard window.',mechanism:'Continuous distributed pressure reduces the bottom player’s ability to create the space and rotation their half guard needs, making each small leg-clear permanent.',cues:['Make them carry you.','Small wins.','Shoulders pinned, hips followed.','Clear leg before attack.'],mistakes:['Rushing the leg extraction and creating space.','Holding breath/static squeezing instead of adjusting pressure.','Chasing submissions before the guard is passed.'],troubleshooting:[{problem:'Every time I move my leg they recover space.',fix:'Move less at once; keep torso pressure constant while advancing the knee/foot incrementally.'}],reactions:['Bridges tell you where to widen/post; hip escapes tell you where to follow with your hips.'],followUps:['Side control','Mount'],variations:['Pressure half-guard pass'],drilling:['Timed top rounds where submissions are forbidden; score only for maintaining pressure and clearing the leg.']},
'Back step':{goal:'Change hip direction over the opponent’s half guard, clear the trapped knee/leg, and land in reverse-half/side-control style top position.',setup:'Begin top half guard when the bottom player’s frames/underhook make forward passing difficult but their far side is available.',grips:['Control upper body/hip line before turning so the opponent cannot simply follow your rotation to top.'],baseManipulation:'Pin the opponent’s hips/shoulders and rotate your hips away from the trapped-leg direction, forcing their half-guard clamp to open/change angle.',bodyPosition:'Keep your weight connected during the turn. The stepping leg travels safely over/behind while your torso maintains awareness of the opponent.',steps:['Secure upper-body/hip control.','Shift enough weight to make the outside leg mobile.','Turn your hips and step the outside leg back over/around the opponent’s legs.','Land with your hips facing the opposite direction while maintaining control.','Free the trapped knee/foot as the half-guard angle opens.','Rotate/settle into side control or the appropriate reverse position.'],finish:'Finish with your leg free and upper-body control established before turning away from the opponent.',mechanism:'The backstep changes the direction of your hip pressure so the bottom player’s half-guard clamp no longer aligns with your trapped leg.',cues:['Control before turning.','Keep weight connected.','Backstep changes the angle.','Free leg, then settle.'],mistakes:['Turning without controlling the upper body.','Jumping the leg and creating separation.','Exposing the back during the rotation.'],troubleshooting:[{problem:'They come up on top as I turn.',fix:'You rotated without pinning their shoulders/hips; establish control before making the leg light.'}],reactions:['If they follow the backstep strongly, use the rotation to enter the next passing/control direction rather than forcing a static finish.'],followUps:['Side control','Reverse half guard','Knee slice from half guard'],variations:['Backstep half-guard pass'],drilling:['Practice the rotation slowly with partner keeping a light half-guard clamp; emphasize continuous torso connection.']},
'Crossface teepee / bouncy pass':{goal:'Use crossface-driven upper-body control and rhythmic hip/knee pressure to flatten the bottom player and work the trapped leg free.',setup:'Begin top half guard with access to a strong crossface and enough base to pressure the opponent’s shoulders.',grips:['Crossface/head-and-shoulder control turns the opponent’s face away and limits their ability to come onto the side.','Use the opposite arm for underhook/hip control when available.'],baseManipulation:'Flatten the shoulders and repeatedly adjust hip pressure so the opponent’s leg clamp loosens without creating a large escape space.',bodyPosition:'Chest stays connected while your hips make small pressure/repositioning movements; do not bounce weight onto the partner’s neck.',steps:['Establish a safe crossface and complementary upper-body control.','Flatten the opponent away from their preferred side.','Bring your hips/knee line into the trapped-leg clearing position.','Use small rhythmic weight shifts/hip movements to make space at the knee line.','Advance the trapped knee incrementally as space appears.','Peel/free the foot while keeping shoulder control.','Settle side control.'],finish:'Finish with leg fully free and pressure transferred into a stable side-control pin.',mechanism:'Crossface control removes upper-body rotation while repeated small hip adjustments gradually weaken the half-guard clamp without sacrificing chest pressure.',cues:['Crossface controls direction.','Small pressure shifts.','Advance knee incrementally.','Never bounce onto the neck.'],mistakes:['Using uncontrolled bouncing force.','Losing upper-body control while working the leg.','Trying to yank the foot free first.'],troubleshooting:[{problem:'The half guard stays locked despite pressure.',fix:'Focus on clearing the knee line first and change hip angle; do not pull only on the foot.'}],reactions:['If the bottom player turns away under crossface pressure, follow the exposed hip/upper-body position.'],followUps:['Side control','Mount'],variations:['Academy-specific teepee/bouncy half-guard pass'],drilling:['Use slow, controlled pressure shifts; partner should never experience neck-impact pressure.']},
'D’Arce choke from half guard top':{goal:'Use the bottom player’s underhook/turned posture to thread a head-and-arm D’Arce configuration while maintaining top control.',setup:'Begin top half guard as the bottom player turns onto their side or reaches an underhook that exposes the space beneath the far armpit.',grips:['Thread the choking arm under the near armpit and across the neck, reaching toward the far side.','Connect to your biceps/upper arm with the reinforcing hand positioned behind/around the head according to the finish.'],baseManipulation:'Keep the opponent’s shoulder driven into the neck and prevent them from squaring their torso or pulling the trapped arm free.',bodyPosition:'Sprawl/angle your chest and hips so your bodyweight reinforces the head-and-arm connection without cranking the neck.',steps:['Recognize the underhook/side-turn that exposes the threading lane.','Thread your arm under the armpit and across the neck as deeply as possible.','Secure the D’Arce grip configuration.','Control the opponent’s head/shoulder line and prevent them from turning square.','Adjust your angle/sprawl so their trapped shoulder compresses into the neck.','Apply gradual finishing pressure with your body and arms working together.','Release immediately on the tap.'],finish:'Finish as a controlled blood-choke structure; do not explosively twist the neck.',mechanism:'Your forearm compresses one side of the neck while the opponent’s trapped shoulder is driven into the other, with your grip/body angle closing the space.',cues:['Thread deep.','Shoulder into neck.','Angle before squeeze.','Body pressure, slow finish.'],mistakes:['Shallow threading arm.','Squeezing while square with poor angle.','Trying to crank the head instead of compressing the head-and-arm structure.'],troubleshooting:[{problem:'My arms fatigue and they are not choking.',fix:'Deepen the threading arm and improve the angle that drives their shoulder into the neck before squeezing harder.'}],reactions:['If they hide the underhook/arm, return to passing pressure rather than forcing a shallow choke.'],followUps:['Side control','Back take','Knee slice from half guard'],variations:['D’Arce from top half guard'],drilling:['Practice threading and angle with no finish; add gradual choke pressure only after alignment is correct.']}
};


const sideControlBottomInstruction:Record<string,Partial<BjjTechnique>>={
'Replace guard from side control':{goal:'Survive side control, build frames, create hip space, and put a knee/leg back between you and the top player to recover guard.',setup:'Begin pinned in side control. First make sure your near arm is not trapped and your neck/shoulders are protected.',grips:['Use forearm/elbow frames against the opponent’s shoulder/neck line and hip rather than pushing with straight arms.','Keep elbows connected to your ribs so the top player cannot easily swim underneath them.'],baseManipulation:'Frames preserve a small amount of distance while your bridge and hip escape move your own body away from pressure. The goal is to create enough space for the knee—not to bench-press the opponent off.',bodyPosition:'Turn slightly onto your side toward the opponent when safe, knees ready to move. Keep your inside elbow/knee relationship protected.',steps:['Establish safe shoulder/neck and hip frames.','Use a directional bridge to make the top player post or become light.','As their pressure changes, turn onto your side and hip-escape away.','Bring the near/bottom knee into the space between your bodies.','Use the knee/shin as a new frame so the opponent cannot immediately close the distance.','Recover the second leg around/inside as appropriate.','Square your hips and establish a recognizable guard before attacking.'],finish:'Finish with both hips facing the opponent and a functional guard/inside-leg position established.',mechanism:'Frames hold space temporarily; bridge changes the pressure; hip escape moves your pelvis far enough for the knee to re-enter. The knee then replaces the weaker arm frame with a stronger leg frame.',cues:['Frame, bridge, hip escape, knee inside.','Move yourself—not them.','Elbows close.','Escape is not done until guard exists.'],mistakes:['Straight-arm bench pressing.','Shrimping while completely flat.','Creating space but failing to insert the knee.','Trying to attack before recovering position.'],troubleshooting:[{problem:'I shrimp but their chest follows me.',fix:'Use the bridge/frame to change their pressure first; hip movement without preserved space lets them simply follow.'},{problem:'My knee cannot get inside.',fix:'Create a larger hip angle and protect the elbow-knee space before trying to thread the knee.'}],reactions:['If the top player switches their hip/head position, rebuild frames appropriate to the new side before continuing.'],followUps:['Closed guard','Half guard','Seated guard'],variations:['Elbow-knee guard recovery','Hip-escape guard replacement'],drilling:['Start with frames established and rep bridge → shrimp → knee insertion.','Then start fully pinned and require survival/frame recovery first.']},
'Underhook to turtle transition':{goal:'Use a protected underhook from bottom side control to get onto your side, come to your knees, and transition to turtle/wrestle-up without exposing your neck/back unnecessarily.',setup:'Begin in side control after creating enough frame/hip space to turn onto your side.',grips:['Win an underhook around the opponent’s torso/near side while keeping the other arm available to frame/protect your head.','Keep the underhook tight enough that your elbow does not become an easy lever away from your body.'],baseManipulation:'The underhook gets your shoulder line underneath/around the top player and prevents them from freely flattening you as you rotate to your knees.',bodyPosition:'Get onto your side before trying to come up. Bring your knees underneath your hips while keeping your head tight and protected from front-headlock attacks.',steps:['Build frames and create enough space to turn onto your side.','Thread the underhook and connect your shoulder/chest toward the opponent.','Keep your head protected and close rather than reaching the underhook with a long arm.','Hip-escape or scoot enough to bring your bottom knee underneath you.','Rotate toward your knees while maintaining the underhook connection.','Build a compact turtle/base rather than extending your arms on the mat.','Immediately choose: wrestle up, recover guard, or protect/clear the top player’s control.'],finish:'Finish in a stable turtle/kneeling base with your neck protected and a next action already available.',mechanism:'The underhook occupies the space the top player needs to flatten your near shoulder, allowing your hips and knees to rotate underneath your torso.',cues:['Side first.','Underhook tight.','Head protected.','Come to knees compactly.'],mistakes:['Reaching for an underhook while flat.','Leaving the head exposed to guillotine/front headlock.','Posting both arms long on the mat during the turn.'],troubleshooting:[{problem:'They flatten me as I try to come up.',fix:'Your underhook/shoulder position is too shallow or you started the turn before getting onto your side.'}],reactions:['If they whizzer heavily, use the connection to recover guard or adjust the wrestle-up rather than driving blindly into it.'],followUps:['Turtle · bottom','Seated single · collar drag / wrist grip','Guard recovery'],variations:['Underhook-to-turtle escape','Underhook wrestle-up'],drilling:['Rep from established underhook to compact turtle.','Then let partner alternate crossface pressure and whizzer so you learn when the transition is available.']},
'Phantom escape':{goal:'Use timing, shoulder/hip movement, and the space created by the top player’s pressure shift to slip out of side control with minimal pushing.',setup:'Begin under side control with defensive frames and awareness of where the top player’s weight is committed.',grips:['Use light structural frames to monitor shoulder/hip pressure rather than locking yourself into a strength contest.'],baseManipulation:'Wait for or create a moment when the top player’s weight shifts away from the space you need; redirect your shoulders/hips through that opening.',bodyPosition:'Stay mobile through the shoulders and hips. The escape depends on changing your body angle at the moment pressure becomes misaligned.',steps:['Protect your neck/inside space and establish light frames.','Feel which direction the top player’s weight is committed.','Create or wait for a small pressure shift with a bridge/frame reaction.','Turn your shoulders and hips into the newly available space rather than pushing the opponent away.','Slide the hips/torso through and recover inside position.','Immediately establish guard, knees, or a stable base before the opponent reconnects.'],finish:'Finish in a clear guard/recovery position rather than merely becoming loose underneath side control.',mechanism:'Top control depends on aligned chest/hip pressure. When that pressure shifts, moving your body through the unweighted space can be more efficient than trying to move the top player.',cues:['Feel weight first.','Move through empty space.','Small frame, big body movement.','Recover position immediately.'],mistakes:['Treating it as a bench-press escape.','Moving before pressure shifts.','Escaping the chest but leaving hips pinned.'],troubleshooting:[{problem:'There is never enough space.',fix:'Use a small bridge/frame reaction to make the top player adjust before attempting the shoulder/hip movement.'}],reactions:['If the top player follows the first movement, chain into hip escape/underhook recovery rather than forcing the same opening.'],followUps:['Replace guard from side control','Underhook to turtle transition'],variations:['Academy-specific phantom escape mechanics'],drilling:['Have partner hold moderate side-control pressure and deliberately shift weight; identify and move through the light side.'],notes:'Confirm your academy’s exact phantom-escape mechanics; naming and details vary.'},
'Knee-on-belly escape · Granby to guard':{goal:'Remove knee-on-belly pressure, create a rotational lane, and use a Granby-style shoulder roll to bring your legs back between you and the top player.',setup:'Begin underneath knee-on-belly with your neck protected and hands framing rather than pushing directly on the knee with extended arms.',grips:['Frame at the opponent’s hip/knee/upper-body line as taught while keeping elbows safe.','Use the frames to redirect pressure enough to begin your shoulder rotation.'],baseManipulation:'Shift the opponent’s knee/weight away from the centerline and create room for your hips to rotate underneath rather than trying to lift their whole body.',bodyPosition:'Turn onto a shoulder and keep the head/neck out of the rolling path. The hips travel overhead/around while the legs pummel back toward the opponent.',steps:['Protect your neck and establish compact frames against the knee/hip line.','Bridge or redirect enough pressure to make the knee lighter.','Turn onto the appropriate shoulder and bring your hips away from the direct pressure.','Begin the Granby rotation across the shoulder—not the head/neck.','Swing your legs through the created space toward the opponent.','Square your hips as the legs return between you.','Establish guard/inside position immediately.'],finish:'Finish facing the opponent with legs inside and a functional guard structure.',mechanism:'Redirecting knee pressure creates the rotational space; the shoulder roll moves the hips around the pin while the legs recover inside position.',cues:['Make knee light first.','Roll over shoulder, never neck.','Hips rotate; legs recover inside.','Square up at finish.'],mistakes:['Trying to roll while the knee is fully loaded.','Rolling over the neck/head.','Completing the roll but failing to face the opponent.'],troubleshooting:[{problem:'I get stuck halfway through the roll.',fix:'Create more initial hip/knee space and commit the hips through the shoulder-roll pathway instead of flattening mid-rotation.'}],reactions:['If the top player follows the roll, use the movement to recover half guard or another inside-leg position rather than insisting on full guard.'],followUps:['Open guard','Half guard','Seated guard'],variations:['Granby guard recovery from knee-on-belly'],drilling:['Practice Granby pathway solo first.','Add a cooperative knee-on-belly partner and require a clear guard position at the end.']}
};


const sideControlTopInstruction:Record<string,Partial<BjjTechnique>>={
'Straight arm lock from side control':{goal:'Use side-control pressure to isolate a straight arm, control the wrist and elbow line, and apply a gradual elbow lock without sacrificing top position.',setup:'Begin from stable side control after the opponent frames or extends an arm.',grips:['Control the wrist with one hand while the other controls above/around the elbow.','Keep the arm connected to your torso so the opponent cannot freely rotate the shoulder or retract the elbow.'],baseManipulation:'Pin the opponent’s shoulders/hips before attacking. The extended arm is useful only if their torso cannot freely turn and follow it.',bodyPosition:'Stay heavy through chest/hips with a wide base. Align your body behind the elbow rather than pulling the wrist away from the opponent.',steps:['Stabilize side control first.','Identify an extended framing arm and secure wrist/elbow control.','Separate the arm from a strong frame without lifting your chest away.','Align the elbow over your controlling fulcrum/body line.','Control wrist rotation so the elbow remains oriented for extension.','Apply gradual extension with your body while maintaining the pin.'],finish:'Extend only until controlled elbow pressure is established; release immediately on the tap.',mechanism:'The elbow is fixed against a fulcrum while wrist control prevents rotation that would relieve extension pressure.',cues:['Pin first.','Wrist and elbow together.','Body behind the lock.','Slow finish.'],mistakes:['Chasing the arm before stabilizing side control.','Pulling only on the wrist.','Allowing the elbow to rotate away from the fulcrum.'],troubleshooting:[{problem:'They turn and recover the arm.',fix:'Re-establish shoulder/hip control and keep the elbow connected to your torso before extending.'}],reactions:['If they bend the elbow, transition into Americana/Kimura control rather than forcing the straight arm.'],followUps:['Americana from Side Control','Kimura from side control','Mount'],variations:['Straight armbar from side control'],drilling:['Start from a cooperative frame; isolate wrist/elbow while maintaining chest pressure, then add slow resistance.']},
'Kimura from side control':{goal:'Isolate the opponent’s near or far arm in a figure-four while controlling their torso, then rotate the shoulder gradually.',setup:'Begin from established side control when the opponent bends an arm or exposes the wrist/elbow during framing.',grips:['Control the wrist, thread around the upper arm, and grip your own wrist for the figure-four.','Keep the elbow bent and separated from the opponent’s ability to hide it against the ribs.'],baseManipulation:'Use chest/hip pressure to stop the opponent from turning freely while the figure-four separates the shoulder from the torso.',bodyPosition:'Stay close to the shoulder with your elbows compact. Move your body around the arm rather than lifting your weight off the opponent.',steps:['Stabilize side control.','Pin/control the target wrist.','Thread your second arm around the upper arm and secure your own wrist.','Keep the elbow bent and bring it away from the opponent’s defensive rib position.','Adjust your hips/torso so the shoulder cannot follow the rotation.','Move the wrist behind the opponent while controlling the elbow.','Apply gradual internal shoulder rotation.'],finish:'Rotate the shoulder slowly and release immediately on the tap.',mechanism:'The figure-four fixes wrist and elbow while torso control prevents the shoulder girdle from rotating to relieve pressure.',cues:['Position before submission.','Tight figure-four.','Control elbow and torso.','Move body, not just hands.'],mistakes:['Loose figure-four.','Trying to finish while the opponent can roll freely.','Cranking the wrist without isolating the shoulder.'],troubleshooting:[{problem:'They straighten the arm.',fix:'Follow the arm into straight-arm control or re-bend it before continuing; do not force a lost Kimura shape.'}],reactions:['If they turn away to defend, follow the rotation into back exposure or stronger top control.'],followUps:['Straight arm lock from side control','Back control','Mount'],variations:['Near-side Kimura','Far-side Kimura control'],drilling:['Build figure-four and hold position first; add finish only after partner cannot freely rotate.']},
'Paper / bread-cutter choke':{goal:'Use collar grips and shoulder/chest pressure from side control to compress both sides of the neck while retaining top control.',setup:'Begin from stable gi side control with access to the opponent’s collars and enough upper-body pressure to prevent easy turning.',grips:['Feed one hand underneath/behind the neck to secure the far collar as deeply as your structure allows.','The second hand controls the near collar/shoulder line to create the cutting forearm position.'],baseManipulation:'Pin the shoulders and turn the opponent’s head/upper body so they cannot simply rotate into the choke or recover guard.',bodyPosition:'Keep your chest low and base wide. The choking forearm aligns across the neck while your bodyweight reinforces the collar structure.',steps:['Stabilize side control and expose the collar safely.','Feed the under-neck hand to the far collar.','Secure the second collar grip and align the forearm across the appropriate neck line.','Lower your elbow/shoulder structure while keeping the opponent’s shoulders pinned.','Walk/angle your body to remove slack from the collars.','Apply pressure gradually without abandoning side control.'],finish:'Use progressive collar/forearm pressure; release immediately on the tap.',mechanism:'Opposing collar tension and forearm position compress the neck while top pressure prevents the opponent from rotating away.',cues:['Deep collar first.','Shoulders pinned.','Remove slack with body angle.','Pressure, not arm squeeze.'],mistakes:['Shallow collar grips.','Lifting the chest and losing side control.','Trying to finish with biceps alone.'],troubleshooting:[{problem:'The choke feels like jaw pressure only.',fix:'Recheck forearm/collar alignment and grip depth rather than adding force.'}],reactions:['If they turn strongly away, use the reaction to advance mount/back exposure.'],followUps:['Mount','Back control','Cross choke from side control'],variations:['Paper-cutter / bread-cutter collar choke'],drilling:['Practice collar feed and body angle without finishing; add gradual pressure after alignment is consistent.']},
'Far-side armbar':{goal:'Isolate the far arm from side control, control the opponent’s shoulder/head, and transition your legs around the arm into a stable armbar.',setup:'Begin from side control when the far elbow separates from the ribs during framing or defense.',grips:['Control the far wrist/arm and keep the elbow from retracting.','Maintain head/shoulder control until your legs replace your upper-body pin.'],baseManipulation:'Keep the opponent’s shoulders from freely turning while you move around the isolated far arm.',bodyPosition:'Stay connected during the transition; do not stand upright and create a large escape window while stepping around the head.',steps:['Stabilize side control and isolate the far arm.','Bring the far elbow above/away from the opponent’s rib line.','Control wrist and shoulder as you adjust your base.','Step the appropriate leg around/over the head while staying connected.','Sit close to the shoulder with the elbow above your hip line.','Pinch knees and control wrist orientation.','Apply gradual hip extension.'],finish:'Finish with knees connected and controlled hip extension; release immediately on the tap.',mechanism:'Your hips become the elbow fulcrum while your legs control the shoulder/head and wrist control prevents rotational escape.',cues:['Isolate far elbow.','Stay connected during transition.','Elbow over hips.','Slow hip extension.'],mistakes:['Creating too much space while stepping over.','Losing the elbow during the transition.','Falling backward before head/shoulder control is replaced by the legs.'],troubleshooting:[{problem:'They turn into me as I step over.',fix:'Maintain shoulder/head control longer and sit closer to the isolated arm.'}],reactions:['If they bend/retract the arm, return to side control or transition to Kimura control rather than forcing the armbar.'],followUps:['Kimura from side control','Side control','Mount'],variations:['Far-side armbar from standard side control'],drilling:['Pause at isolation, leg-over-head, and seated checkpoints before adding the finish.']},
'Baseball choke':{goal:'Use opposing collar grips and rotational body movement to close a gi choke from top side-control/passing positions.',setup:'Begin with collar access from side control or a passing position where you can establish baseball-bat style opposing grips.',grips:['Place the hands close together on opposing collar material in the baseball-bat orientation taught by your academy.','Remove collar slack before committing to the rotational finish.'],baseManipulation:'Control the opponent’s shoulders/hips long enough to establish grips, then use your movement around the head to prevent them from following the choke direction.',bodyPosition:'Keep elbows structurally tight and rotate your torso/feet around the opponent rather than trying to squeeze in place.',steps:['Establish the first collar grip without sacrificing top control.','Secure the second opposing grip close to the first.','Remove slack and align your forearms/wrists to the sides of the neck.','Begin circling your body around the opponent’s head while keeping the grips fixed.','Bring elbows/forearms into the finishing structure as your torso rotates.','Apply pressure gradually.'],finish:'Finish through collar alignment and body rotation, not explosive arm pulling; release on the tap.',mechanism:'The opposing grips create two-sided collar compression while circling your body tightens the loop around the neck.',cues:['Grips close together.','Remove slack.','Move feet/body around head.','Do not arm-wrestle the choke.'],mistakes:['Grips too far apart.','Trying to squeeze without rotating.','Losing position before grips are secure.'],troubleshooting:[{problem:'I rotate but the choke stays loose.',fix:'Recheck grip depth/spacing and remove collar slack before circling farther.'}],reactions:['If the opponent turns to relieve pressure, follow their shoulder line and use the exposed positional transition.'],followUps:['Side control','North–south','Mount'],variations:['Top baseball-bat choke'],drilling:['Establish grips and practice the circling footwork with no finish, then add gradual choke pressure.']},
'Samurai':{goal:'Use the academy-specific Samurai transition/attack from side control to advance control while preserving chest-to-chest connection.',setup:'Begin from stable side control with the opponent’s near-side frames controlled.',grips:['Maintain the upper-body and hip controls specified in your academy’s Samurai sequence.'],baseManipulation:'Prevent the opponent from squaring their hips/shoulders as you change your angle around their frames.',bodyPosition:'Keep your weight connected during the transition and move your base around the opponent rather than lifting away.',steps:['Stabilize side control before beginning the transition.','Control the opponent’s near-side frame/arm and hip line.','Shift your base to the Samurai angle taught by your academy.','Maintain upper-body connection as your knees/hips reposition.','Use the new angle to advance to the intended pin, mount, or submission entry.','Re-establish a stable base before attacking.'],finish:'Finish in the academy-defined Samurai endpoint with control established before submission attempts.',mechanism:'The transition changes your angle around defensive frames while continuous torso control prevents the opponent from using the movement to recover guard.',cues:['Control before transition.','Stay connected.','Move around frames.','Re-base at endpoint.'],mistakes:['Treating the transition as a memorized spin without controlling the opponent.','Creating chest-to-chest separation.','Attacking before the endpoint is stable.'],troubleshooting:[{problem:'They recover guard during the movement.',fix:'Slow down and identify which hip/knee line your academy’s version requires you to block throughout the transition.'}],reactions:['If the opponent turns with the transition, follow the exposed mount/back pathway rather than forcing the original endpoint.'],followUps:['Mount','Back control','Side control'],variations:['Academy-specific Samurai sequence'],drilling:['Rep the transition without submissions and require continuous chest/hip control.'],notes:'“Samurai” is academy-dependent terminology. Confirm the exact sequence with your coach; this record intentionally teaches the control principles without inventing a school-specific choreography.'},
'Cross choke from side control':{goal:'Use opposing gi collar grips from side control to control posture/head position and apply a gradual two-sided neck compression.',setup:'Begin from stable side control with access to both collars.',grips:['Feed the first hand deeply into the opposite collar near the neck.','Secure the second opposing collar grip while maintaining shoulder pressure.'],baseManipulation:'Pin the opponent’s shoulders so they cannot turn their whole torso with the choke.',bodyPosition:'Stay chest-connected with elbows compact; use body angle to remove collar slack rather than lifting away.',steps:['Stabilize side control.','Establish the first deep cross-collar grip.','Secure the second grip without giving the opponent an underhook/escape lane.','Align wrists/forearms along the neck.','Keep shoulders pinned and remove slack by adjusting your torso.','Draw elbows into a strong structural position and apply gradual pressure.'],finish:'Maintain positional control while tightening both collar sides; release on the tap.',mechanism:'The collar/wrist structure compresses both sides of the neck while the pin prevents the torso from rotating with the grips.',cues:['Deep first grip.','Keep chest connected.','Elbows compact.','Use body angle.'],mistakes:['Shallow grips.','Lifting off the opponent to chase the second collar.','Flaring elbows and losing structure.'],troubleshooting:[{problem:'My arms fatigue.',fix:'Improve grip depth and torso angle; do not compensate with harder arm squeezing.'}],reactions:['If they turn away, follow into mount/back exposure.'],followUps:['Mount','Back control','Paper / bread-cutter choke'],variations:['Side-control cross choke'],drilling:['Practice grip sequence while partner lightly attempts to turn/recover guard.']},
'Near-side armbar':{goal:'Isolate the near arm from side control and transition around the opponent’s head/shoulder into an armbar while preventing the elbow from escaping.',setup:'Begin from stable side control when the near elbow separates from the ribs or becomes trapped by your upper-body control.',grips:['Control the near wrist and elbow/upper arm.','Keep shoulder/head control until your leg position takes over.'],baseManipulation:'Pin the torso and separate the near elbow from its defensive connection to the ribs.',bodyPosition:'Move tightly around the shoulder; your hips should arrive close to the elbow rather than falling away from it.',steps:['Stabilize side control and isolate the near arm.','Control wrist/elbow and prevent the elbow from returning to the ribs.','Shift your base while keeping pressure on the shoulder line.','Bring the appropriate leg over/around the head and sit close.','Capture the elbow above your hip line.','Pinch knees and control wrist orientation.','Apply gradual hip extension.'],finish:'Controlled elbow extension with knees connected; release immediately on the tap.',mechanism:'Torso control isolates the shoulder, then your hips become the elbow fulcrum while the legs prevent the opponent from following.',cues:['Separate elbow from ribs.','Stay close.','Elbow over hips.','Control wrist rotation.'],mistakes:['Falling away from the shoulder.','Losing wrist/elbow connection during the leg transition.','Trying to finish before the legs control the torso.'],troubleshooting:[{problem:'They pull the elbow out as I sit.',fix:'Keep the elbow connected to your torso and sit closer to the shoulder before leaning back.'}],reactions:['If the arm bends, connect to Kimura/Americana structures or return to side control.'],followUps:['Kimura from side control','Americana from Side Control','Side control'],variations:['Near-side armbar'],drilling:['Isolate and transition without finishing; partner gradually increases elbow-retraction resistance.']},
'Arm triangle from side control':{goal:'Trap the opponent’s arm against their neck, control the head-and-arm structure, and use chest/shoulder pressure to apply a blood choke.',setup:'Begin side control when the opponent’s far arm can be moved across their face/neck line.',grips:['Control the head and guide the opponent’s arm across their neck.','Connect your hands/head-and-arm structure according to your preferred arm-triangle finish.'],baseManipulation:'Keep the trapped shoulder pressed into one side of the neck and prevent the opponent from turning toward you to create space.',bodyPosition:'Lower your shoulder/chest into the neck line while your body moves toward the appropriate finishing angle. Keep your hips/base stable rather than squeezing from directly square.',steps:['Move the opponent’s arm across their neck and prevent it from returning.','Capture the head and trapped arm together.','Lower your head/shoulder position to close space.','Walk/angle your body toward the finishing side while keeping the trapped shoulder connected.','Settle your chest/shoulder pressure and remove remaining space.','Apply gradual compression with body position before adding arm squeeze.'],finish:'Finish with controlled shoulder/chest compression and release immediately on the tap.',mechanism:'Your shoulder compresses one carotid while the opponent’s trapped shoulder is driven into the other side of their neck.',cues:['Arm across neck.','No space at shoulder/head.','Angle before squeeze.','Chest/shoulder does the work.'],mistakes:['Trying to squeeze while square.','Opponent’s arm not truly across the neck.','Leaving space between your shoulder and their neck.'],troubleshooting:[{problem:'They can breathe and my arms burn.',fix:'Improve the trapped-arm position and walk your body to the finishing angle before squeezing.'}],reactions:['If they turn away to relieve pressure, use the turn to advance positional control.'],followUps:['Mount','Side control','Back control'],variations:['Side-control arm triangle','Mount-to-side arm triangle finish'],drilling:['Build the head-and-arm shape and angle first; add very gradual finishing pressure.']},
'Arm crush from knee-on-belly':{goal:'Use knee-on-belly control to isolate a defensive arm and compress/control it with your upper/lower-body structure while retaining positional dominance.',setup:'Begin in stable knee-on-belly when the opponent frames against your knee/torso with an arm that can be isolated.',grips:['Control the wrist/forearm and elbow so the arm cannot retract freely.','Use your knee/shin/torso only in the academy-approved configuration; avoid uncontrolled pressure on small joints.'],baseManipulation:'Keep the opponent’s hips/shoulders pinned enough that they cannot simply turn and retrieve the arm.',bodyPosition:'Maintain a mobile knee-on-belly base with the posted leg available for balance; do not sacrifice your base to chase the arm.',steps:['Stabilize knee-on-belly and identify the framing arm.','Control wrist and elbow before changing pressure.','Isolate the arm against the safe structural surface used in your academy’s version.','Adjust your base so your weight remains controlled and the opponent cannot rotate free.','Apply gradual compression/extension only within the taught joint alignment.','Release immediately on the tap or if alignment is uncertain.'],finish:'A controlled arm lock/compression while maintaining safe top balance.',mechanism:'The opponent’s arm is isolated between fixed control points while your body position supplies leverage that their shoulder/torso cannot follow.',cues:['Base first.','Control wrist and elbow.','Know the joint line.','Slow pressure.'],mistakes:['Dropping uncontrolled bodyweight onto the arm.','Attacking before knee-on-belly is stable.','Using pressure when joint alignment is unclear.'],troubleshooting:[{problem:'The arm slips free.',fix:'Improve wrist/elbow isolation before adding pressure; do not compensate by dropping more weight.'}],reactions:['If the opponent retracts the arm, use the opening to transition mount/side control.'],followUps:['Mount','Side control','Americana from Side Control'],variations:['Academy-specific knee-on-belly arm crush'],drilling:['Practice isolation and position with no finishing pressure until the exact academy mechanics are confirmed.'],notes:'Arm-crush mechanics vary substantially by academy; preserve joint safety and confirm the exact version with your coach.'},
'Knee-on-belly to mount transition':{goal:'Use knee-on-belly pressure and the opponent’s defensive reaction to slide/step into mount without giving them a guard-recovery lane.',setup:'Begin in stable knee-on-belly with upper-body/hip control and the far leg posted for balance.',grips:['Control upper body and/or far hip so the opponent cannot freely turn underneath as you move the knee.'],baseManipulation:'Make the opponent carry pressure and react; when their near-side hip/knee space opens, block that recovery path as your knee crosses.',bodyPosition:'Keep your chest over the opponent and transfer weight smoothly from knee-on-belly into both knees around the torso.',steps:['Establish stable knee-on-belly.','Control the opponent’s upper body/hip and wait for a defensive reaction.','Bring the knee across the torso toward the far side while keeping hip space blocked.','Slide/step the trailing leg around the opponent’s legs before they insert a knee.','Set both knees/feet into a stable mount base.','Settle your hips and respond to the immediate bridge before attacking.'],finish:'Finish in stable mount with the opponent’s elbows/hips controlled.',mechanism:'Knee-on-belly forces defensive frames and hip movement; maintaining upper-body/hip control lets you occupy the space those reactions create with mount.',cues:['Pressure creates reaction.','Block the knee-recovery lane.','Transfer weight smoothly.','Settle mount before attack.'],mistakes:['Jumping to mount with no hip control.','Leaving space for the near knee to re-enter.','Attacking immediately before stabilizing mount.'],troubleshooting:[{problem:'They catch half guard during the transition.',fix:'Control the near hip/knee line longer and move the trailing leg only after your lead knee has blocked recovery.'}],reactions:['If they turn away instead of framing, follow the back exposure rather than forcing mount.'],followUps:['Mount Control Cycle','Back control','Arm triangle from side control'],variations:['Sliding knee-on-belly to mount','Reaction-based mount transition'],drilling:['Partner alternates frame, bridge, and turn-away reactions; top player chooses mount only when the hip lane opens.']},
'D’Arce from side control':{goal:'Use the opponent’s turned posture/underhook to thread a deep head-and-arm D’Arce and finish with angle rather than arm strength.',setup:'Begin side control as the opponent turns in or reaches an underhook, exposing the space under the far armpit.',grips:['Thread your arm under the near armpit and across the neck toward the far side.','Secure the biceps/hand configuration only after the threading arm is deep enough.'],baseManipulation:'Keep the opponent’s trapped shoulder driven toward the neck and prevent them from squaring their shoulders.',bodyPosition:'Sprawl/angle around the head-and-arm structure so your torso reinforces the choke without twisting the neck.',steps:['Recognize the underhook/turn-in reaction.','Thread the choking arm deeply under the armpit and across the neck.','Connect the D’Arce grip.','Control the opponent’s head/shoulder line so they cannot square up.','Sprawl/walk to the angle that drives their trapped shoulder into the neck.','Remove remaining space and apply gradual pressure.'],finish:'Controlled head-and-arm compression; release immediately on the tap.',mechanism:'Your forearm compresses one side of the neck while the opponent’s own trapped shoulder closes the other side.',cues:['Reaction creates entry.','Thread deep.','Shoulder into neck.','Angle before squeeze.'],mistakes:['Shallow threading arm.','Trying to squeeze from square position.','Cranking the head instead of closing the shoulder/neck space.'],troubleshooting:[{problem:'My arms fatigue.',fix:'Deepen the thread and improve the body angle before increasing squeeze.'}],reactions:['If the opponent retracts the underhook, return to side-control pressure or take the exposed back/mount lane.'],followUps:['Back control','Mount','Side control'],variations:['D’Arce from side-control underhook reaction'],drilling:['Partner gives controlled turn-in/underhook; top player threads and establishes angle before any finishing pressure.']}
};


const transitionInstruction:Record<string,Partial<BjjTechnique>>={
'Pendulum escape to guard / half guard':{goal:'Use a timed pendulum of the legs and hips from bottom north–south to turn your body back toward the opponent and recover guard or half guard.',setup:'Begin under north–south with your neck protected and elbows inside. First create enough shoulder/hip mobility that your torso is not completely pinned.',grips:['Frame structurally against the opponent’s shoulders/hips rather than pushing with extended arms.','Keep elbows close enough to protect inside space as you begin rotating.'],baseManipulation:'Use frames and a small bridge/hip shift to make the opponent’s weight travel away from the side where your legs need to swing.',bodyPosition:'Keep shoulders mobile and use the legs as a counterweight. Your hips swing in an arc while your torso rotates to face the opponent again.',steps:['Protect the neck and establish compact frames.','Create a small pressure shift with bridge/hip movement.','Swing the legs in a pendulum arc to generate hip rotation.','Turn your shoulders and pelvis toward the opponent as the legs travel.','Insert the first knee/leg into the newly opened space.','Recover the second leg or clamp half guard if full guard is not available.','Square your hips and establish a functional guard before attacking.'],finish:'Finish facing the opponent with at least one meaningful inside leg position—guard or half guard.',mechanism:'The leg pendulum supplies rotational momentum while frames preserve enough space for your hips to turn back underneath the top player.',cues:['Protect neck.','Shift pressure first.','Legs create rotation.','Get a knee inside.'],mistakes:['Trying to bench-press the opponent away.','Swinging legs while shoulders remain completely pinned.','Rotating but failing to insert a knee.'],troubleshooting:[{problem:'My hips rotate but they follow me.',fix:'Create the pressure shift first and use your frame to preserve the lane for the first knee.'}],reactions:['If full guard is blocked, accept half guard/inside position and continue recovery rather than forcing the second leg through.'],followUps:['Half guard','Open guard','Replace guard from side control'],variations:['Pendulum recovery to half guard','Pendulum recovery to full/open guard'],drilling:['Start with light north–south pressure and rep only pressure shift → pendulum → first knee insertion.']},
'Shoulder-roll back take':{goal:'Use the opponent’s north–south pressure/angle to rotate underneath on the shoulder and emerge behind their hip/shoulder line for back exposure.',setup:'Begin from bottom north–south when the opponent’s weight and arm position leave a rotational lane around one shoulder.',grips:['Maintain a connection to the opponent’s torso/arm/hip so the roll moves you around them rather than simply away.'],baseManipulation:'Encourage the opponent’s weight past your center, then rotate through the space behind that pressure.',bodyPosition:'Roll across the shoulder/upper back—not the head or cervical spine—and keep the hips active enough to follow the rotation.',steps:['Protect your neck and identify the lighter shoulder/rotational lane.','Create a small bridge/frame reaction that shifts the opponent’s weight.','Turn onto the shoulder and begin the roll underneath/around their upper body.','Keep a torso/hip connection as your hips follow the shoulders.','Bring your knees/base underneath you as you emerge beside/behind them.','Secure the hip/seatbelt or other back-control connection before chasing hooks.'],finish:'Finish with meaningful back/hip control and then establish full back control.',mechanism:'The roll uses the top player’s forward/north–south pressure as momentum while your shoulder rotation changes which side of their body you occupy.',cues:['Weight past you.','Shoulder, never neck.','Stay connected during roll.','Control hip before hooks.'],mistakes:['Rolling with no connection to the opponent.','Loading the neck/head.','Emerging behind them but failing to control the hips.'],troubleshooting:[{problem:'They simply turn and face me.',fix:'Maintain the torso/hip connection through the roll and secure their hip immediately as you emerge.'}],reactions:['If the back is unavailable, use the rotation to recover guard or come to a kneeling top exchange.'],followUps:['Back control','Turtle · top','Seated guard'],variations:['North–south shoulder-roll back exposure'],drilling:['Practice the shoulder pathway solo, then add a cooperative partner and require hip control at the endpoint.']},
'Sit through':{goal:'From bottom turtle, create an opening under/around the opponent’s control and rotate your hips through to face them or come on top.',setup:'Begin in compact turtle with elbows/knees connected and neck protected.',grips:['Control or monitor the opponent’s near arm/waist connection so you know which side is safe to rotate through.'],baseManipulation:'Make the opponent’s pressure travel over one shoulder/side, then remove the supporting hip/knee from underneath that pressure.',bodyPosition:'Keep one hand/foot available as a base while the opposite hip threads underneath. Stay compact enough that your neck is not exposed.',steps:['Protect the neck and identify the opponent’s dominant control side.','Build a stable hand/foot/knee base.','Create a small forward/side pressure reaction.','Lift the appropriate hip and thread the opposite leg/hip through underneath your torso.','Rotate your chest to face the opponent while keeping their arm/body controlled.','Rebuild your base immediately in seated guard, kneeling, or top position.'],finish:'Finish facing the opponent with a stable base—not halfway turned with your back exposed.',mechanism:'The sit-through removes your hips from the line of top pressure and rotates your torso around the opponent’s control arm.',cues:['Neck safe first.','Pressure over one side.','Hip threads through.','Face them at finish.'],mistakes:['Sitting through while the opponent controls the neck.','Extending both arms and collapsing the base.','Stopping with the back still exposed.'],troubleshooting:[{problem:'They follow and stay behind me.',fix:'Control/monitor their near arm and rotate your chest fully to face them rather than only moving the hips.'}],reactions:['If they block the sit-through, return compact and choose a different turtle escape instead of extending farther.'],followUps:['Seated guard','Wrestle-up','Sit out to rear turtle'],variations:['Basic sit-through from turtle'],drilling:['Partner gives one-sided pressure; bottom identifies the safe side and finishes facing the partner.']},
'Sit out to rear turtle':{goal:'Rotate out from bottom turtle toward the opponent’s rear/side position, clearing their control and rebuilding a safer base.',setup:'Begin compact in turtle with the opponent controlling from one side.',grips:['Monitor/control the near arm or waist connection so it cannot freely follow your hip rotation.'],baseManipulation:'Shift the opponent’s weight toward the front/side, then rotate your hips behind the line of their control.',bodyPosition:'Keep head protected and shoulders above a compact base while one leg steps/sits out behind.',steps:['Identify which side the opponent is controlling.','Protect the neck and control the near connection.','Shift weight onto the supporting hand/knee.','Sit/step the opposite hip and leg toward the rear opening.','Rotate the torso so the opponent’s control slides past your hip line.','Rebuild knees/feet underneath and face or disengage safely.'],finish:'Finish with the opponent no longer securely behind your hips and with a stable base for the next action.',mechanism:'The hip rotation changes the alignment between their upper-body control and your pelvis, forcing them to reattach while you rebuild position.',cues:['Protect neck.','Control near arm.','Hip clears control line.','Rebuild base.'],mistakes:['Rotating while the neck is exposed.','Moving the hip but leaving the shoulders behind.','Failing to rebuild posture after clearing.'],troubleshooting:[{problem:'They stay glued to my back.',fix:'Address the near-side arm/waist connection before rotating and move shoulders with hips.'}],reactions:['If they abandon back control to front-headlock, return to compact defense and address the neck first.'],followUps:['Seated guard','Technical stand-up','Wrestle-up'],variations:['Rear sit-out from turtle'],drilling:['Start with a single side-control connection and practice clearing it before adding resistance.']},
'Sit out to frontal cone':{goal:'Use a sit-out rotation to bring your torso toward the opponent’s front/side, clearing rear turtle pressure and establishing a facing position.',setup:'Begin in turtle with neck protected and awareness of the opponent’s arm/head placement.',grips:['Control/monitor the arm that would follow your rotation and protect against front-headlock exposure.'],baseManipulation:'Draw the opponent’s weight forward, then rotate the hips under and around so their pressure passes beyond your base.',bodyPosition:'Stay compact through the shoulders and move the hips in a tight arc; do not leave the neck extended during the turn.',steps:['Secure neck protection and identify the opponent’s controlling arm.','Create a stable post with the appropriate hand/foot.','Shift their pressure forward enough to lighten your hips.','Thread/sit the hip through toward the frontal opening.','Rotate your chest toward the opponent and clear their arm from behind your hip line.','Rebuild a kneeling/seated facing base.'],finish:'Finish facing the opponent with neck safe and hands available to grip/frame.',mechanism:'The sit-out changes your hip orientation underneath forward pressure, converting a rear-control alignment into a frontal exchange.',cues:['Neck first.','Make hips light.','Tight rotation.','Finish facing.'],mistakes:['Turning into a guillotine/front headlock.','Wide, slow hip movement.','Stopping before shoulders face the opponent.'],troubleshooting:[{problem:'My head gets caught as I turn.',fix:'Protect the neck and control the relevant arm before initiating the sit-out.'}],reactions:['If front-head control develops, stop the sit-out and solve the head/arm control before continuing.'],followUps:['Seated guard','Single leg','Technical stand-up'],variations:['Frontal sit-out from turtle'],drilling:['Partner applies light rear pressure; bottom scores only when they finish facing with neck protected.']},
'Donkey-kick guard replacement':{goal:'Create forward space from turtle and kick/extend the hips enough to bring the legs back between you and the opponent for guard recovery.',setup:'Begin compact in turtle when the opponent is behind/above but not securely controlling both hips and upper body.',grips:['Use hands/forearms as safe posts/frames while protecting the neck; do not leave arms extended where they can be isolated.'],baseManipulation:'Drive your hips away from the opponent’s pressure to lengthen the space behind/under you, then rotate the legs into that space.',bodyPosition:'Keep head protected and shoulders stable while the hips extend; immediately retract the legs into a defensive guard structure.',steps:['Protect the neck and identify that the opponent’s hip control is loose enough to create distance.','Build stable hand/forearm posts.','Drive/kick the hips away to create separation.','As space opens, turn the hips and bring one leg between you and the opponent.','Recover the second leg or establish half/open guard.','Square your hips and replace hand posts with leg frames.'],finish:'Finish facing the opponent with a functional guard.',mechanism:'Explosive hip extension creates distance faster than the top player can follow; the legs then occupy that distance as stronger frames.',cues:['Only when hips are not locked down.','Create distance, then legs inside.','Neck protected.','Square up.'],mistakes:['Kicking while the opponent has a tight seatbelt/hip lock.','Creating distance but leaving legs behind.','Extending arms dangerously.'],troubleshooting:[{problem:'They follow my hips immediately.',fix:'The control was too secure for this escape; return compact and clear the hip/upper-body connection first.'}],reactions:['If only one leg enters, accept half guard and continue recovery.'],followUps:['Open guard','Half guard','Seated guard'],variations:['Turtle donkey-kick guard recovery'],drilling:['Top partner alternates loose and tight hip control; bottom chooses the escape only when separation is available.']},
'Mongol roll':{goal:'Use a rolling turtle escape to redirect top pressure and emerge in guard, a scramble, or top position while protecting the neck.',setup:'Begin in turtle with the opponent’s weight committed enough to one side/front that a roll can carry their pressure past your base.',grips:['Maintain control/awareness of the opponent’s near arm/body connection so they cannot freely post and follow.'],baseManipulation:'Load the opponent’s pressure over the rolling shoulder and remove the base underneath that direction.',bodyPosition:'Round the body and roll across shoulder/upper back rather than the neck. Keep elbows/knees compact through the rotation.',steps:['Protect the neck and identify the direction of committed pressure.','Control the near connection and bring the opponent’s weight toward the rolling shoulder.','Tuck/round the body and initiate the roll over the shoulder.','Carry hips through while keeping contact with the opponent.','Use the rotation to clear their rear control.','Come up into guard, a scramble, or top position and immediately establish control.'],finish:'Finish in a recognizable safe position rather than remaining inverted/half-rolled.',mechanism:'The roll converts the opponent’s committed top pressure into rotational momentum and removes the stable turtle base they were controlling.',cues:['Pressure chooses direction.','Shoulder, not neck.','Stay compact.','Come up with control.'],mistakes:['Rolling against the opponent’s weight.','Loading the cervical spine.','Rolling without controlling where the opponent can post.'],troubleshooting:[{problem:'They post and stay on top.',fix:'Control the relevant arm/post and make sure their weight is committed before initiating the roll.'}],reactions:['If they disengage instead of following, use the space to recover guard or stand.'],followUps:['Guard recovery','Wrestle-up','Top scramble'],variations:['Academy-specific Mongol roll'],drilling:['Learn the shoulder-roll path solo, then add a partner giving predictable one-sided pressure.'],notes:'“Mongol roll” terminology and exact mechanics can be academy-specific; confirm your school’s version.'},
'Kimura counter from turtle':{goal:'Recognize an opponent attacking a Kimura/figure-four against your turtle arm, protect the shoulder, and use their arm commitment to recover position or reverse.',setup:'Begin in turtle as the opponent isolates a wrist/elbow and starts building a figure-four.',grips:['Anchor the threatened hand to your body/leg or connect your hands to prevent the elbow from being separated.','Control the opponent’s arm/body connection once the shoulder is safe.'],baseManipulation:'Keep the elbow close and rotate your whole body with the pressure rather than allowing the arm to be twisted independently.',bodyPosition:'Stay compact with the threatened shoulder connected to the torso; move knees/hips to follow the arm instead of leaving the shoulder behind.',steps:['Recognize wrist control before the figure-four becomes fully extended.','Anchor the threatened hand and pull the elbow toward your ribs.','Turn your torso/knees so the shoulder follows the direction of pressure.','Use the opponent’s committed arms to create space on the opposite side.','Recover guard, face them, or come up as the grip loosens.','Re-establish a safe base before attacking.'],finish:'Finish with the shoulder neutral and the opponent’s figure-four cleared.',mechanism:'A Kimura requires the arm to rotate independently of the torso. Anchoring the elbow/hand and moving the whole body shortens the lever and denies that separation.',cues:['Protect shoulder first.','Elbow to ribs.','Move whole body with pressure.','Escape position after grip loosens.'],mistakes:['Trying to straighten the arm against a locked figure-four.','Leaving hips stationary while the shoulder twists.','Counterattacking before the shoulder is safe.'],troubleshooting:[{problem:'The shoulder is already extended behind me.',fix:'Prioritize tapping/safety over a late explosive counter; train this defense from earlier stages.'}],reactions:['Their two-hand commitment can open a guard-recovery or turn-in lane once your shoulder is protected.'],followUps:['Guard recovery','Sit through','Wrestle-up'],variations:['Early Kimura counter from turtle'],drilling:['Start before the figure-four is locked and progressively deepen the attack; stop well before painful shoulder range.']},
'Clock choke':{goal:'Use a deep collar grip and your body circling around a turtled opponent to tighten a gi choke while controlling their shoulders/hips.',setup:'Begin on top of turtle with stable control and access to the far/deep collar.',grips:['Feed the choking hand deeply into the far/opposite collar across the neck.','Use the second hand to control the near arm, lapel, hip, or leg according to your version so the opponent cannot freely rotate.'],baseManipulation:'Keep the opponent’s shoulders/head low and prevent them from simply sitting up or turning to face you as you circle.',bodyPosition:'Place your weight over the upper back/shoulder line and walk your feet/body around the head like clock hands while the collar grip stays fixed.',steps:['Stabilize top turtle and protect against a roll/sit-out.','Establish the deep choking collar grip.','Secure a secondary control that limits the opponent’s rotation.','Drop/settle your weight over the shoulder line.','Walk your feet/body around the opponent’s head while keeping the collar grip anchored.','Remove slack and allow the circling body position to tighten the choke.','Release immediately on the tap.'],finish:'Finish through collar alignment and circling pressure, not a violent neck pull.',mechanism:'The fixed collar grip becomes a tightening loop as your body circles around the neck while the opponent’s torso is prevented from following.',cues:['Deep collar.','Control rotation.','Walk around the head.','Body tightens choke.'],mistakes:['Shallow grip.','Trying to pull the collar with arms while staying stationary.','Circling without controlling the opponent’s body.'],troubleshooting:[{problem:'They turn and follow my circle.',fix:'Improve the secondary hip/arm control and keep their shoulders weighted before walking.'}],reactions:['If they roll to relieve pressure, follow safely into top control rather than forcing the choke through the roll.'],followUps:['Back take from turtle','Side control','Back control'],variations:['Classic clock choke'],drilling:['Practice grip and circling with no finish, then add progressive resistance.']},
'Back take from turtle':{goal:'Control the turtled opponent’s shoulders and hips, create a safe opening, and move behind them into seatbelt/back control.',setup:'Begin on top of turtle with your weight connected and your knees/feet positioned to follow hip movement.',grips:['Secure a seatbelt, tight waist, or upper-body control that connects your chest to their shoulders.','Control a hip/near leg as needed so they cannot freely sit out or roll.'],baseManipulation:'Break the alignment between shoulders and hips so one side of the back becomes available while preventing the opponent from turning to face you.',bodyPosition:'Stay chest-to-back/shoulder connected and move your hips around them; avoid reaching for hooks before controlling the upper body.',steps:['Stabilize turtle and identify the opponent’s likely sit-out/roll direction.','Secure upper-body control such as a seatbelt/tight waist.','Control or block the near hip so they cannot turn freely.','Create an angle to one side and move your chest behind their shoulder line.','Insert the first hook or establish hip control as space opens.','Bring the second leg/control in only after the torso/hips are connected.','Settle back control before attacking the neck.'],finish:'Finish with chest-to-back connection, hip control/hooks, and a secure seatbelt.',mechanism:'Upper-body and hip controls stop the opponent from rotating as you move around the outside of their turtle into the space behind the shoulders.',cues:['Chest connection first.','Control hip.','Angle around, do not climb straight over.','Hooks after control.'],mistakes:['Reaching for hooks with no seatbelt.','Sitting behind them while their hips are free to turn.','Attacking neck before back position is stable.'],troubleshooting:[{problem:'They turn and face me as I move behind.',fix:'Block/control the near hip and keep chest pressure on the shoulder line throughout the transition.'}],reactions:['If they roll, follow with the seatbelt and use the roll to establish back control.'],followUps:['Rear naked choke','Collar choke from back','Technical mount'],variations:['Seatbelt back take','Hip-block back take'],drilling:['Top scores only after chest connection + hip control; hooks alone do not count.']},
'Cross choke from turtle':{goal:'Use opposing collar grips against a turtled opponent to create two-sided neck compression while controlling their posture.',setup:'Begin on top of turtle with access to both gi collars and stable shoulder/hip control.',grips:['Establish a deep first cross-collar grip.','Secure the opposing collar with the second hand while keeping elbows structurally close.'],baseManipulation:'Keep the opponent’s head/shoulders from rising and prevent them from rotating their torso to follow the collar pressure.',bodyPosition:'Stay weighted over the upper back with a mobile base so you can follow rolls/sit-outs.',steps:['Stabilize turtle.','Feed the first collar grip deeply.','Secure the second opposing grip without losing top control.','Align wrists/forearms along the neck.','Keep the shoulders weighted and remove collar slack.','Apply gradual opposing collar pressure while maintaining your base.'],finish:'Controlled collar choke with immediate release on the tap.',mechanism:'Opposing collar/wrist pressure compresses both sides of the neck while top control prevents the opponent from creating rotational space.',cues:['Deep grips.','Weight shoulders.','Elbows close.','Choke without losing base.'],mistakes:['Chasing grips while hips become uncontrolled.','Shallow first grip.','Flaring elbows.'],troubleshooting:[{problem:'They roll me while I grip fight.',fix:'Re-establish hip/shoulder control and widen your base before committing both hands.'}],reactions:['If they expose the back while defending collars, transition to back control.'],followUps:['Back take from turtle','Clock choke','Back control'],variations:['Turtle cross-collar choke'],drilling:['Partner gives light sit-out/roll reactions while top maintains base and collar structure.']},
'Helicopter / butt choke':{goal:'Use an academy-specific rotational collar-control sequence from top turtle/back exposure to tighten a choke while moving around the opponent’s hips/head.',setup:'Begin with top control and a secure collar connection before initiating the rotational movement.',grips:['Establish the collar/choking grip specified by your academy and maintain a second control on the opponent’s body/garment.'],baseManipulation:'Prevent the opponent’s shoulders and hips from freely following your rotation so the movement tightens rather than loosens the collar structure.',bodyPosition:'Keep your weight connected and rotate around the opponent with a controlled base; avoid uncontrolled spinning across the neck.',steps:['Stabilize top turtle/back exposure.','Secure the required collar grip before rotating.','Control the opponent’s torso/hip with the second connection.','Move your hips/legs around the opponent in the academy-specific helicopter/butt-choke pathway.','Keep collar tension while your body angle changes.','Settle the finishing position and apply gradual pressure.'],finish:'Controlled collar choke; release immediately on the tap.',mechanism:'The rotational movement changes body angle while fixed collar control removes slack and closes the space around the neck.',cues:['Grip before rotation.','Control torso.','Rotation tightens collar.','No uncontrolled spin.'],mistakes:['Spinning before grips are secure.','Losing hip/shoulder control.','Using neck torque instead of collar compression.'],troubleshooting:[{problem:'The choke gets looser as I rotate.',fix:'Your collar/body connection is not fixed; reset the grips before repeating the movement.'}],reactions:['If the opponent turns with you, follow into back/side control rather than forcing the choke.'],followUps:['Back control','Clock choke','Side control'],variations:['Academy-specific helicopter/butt choke'],drilling:['Learn the rotational path without finishing pressure, then add collar tension gradually.'],notes:'Terminology and exact choreography vary by academy; confirm this technique’s school-specific details with your coach.'},
'Guillotine from turtle':{goal:'Capture the neck as the turtled opponent exposes their head, control their posture, and apply a safe guillotine/front-head choke without losing top position.',setup:'Begin in front/side of turtle when the opponent’s head is available below your arm line.',grips:['Wrap the neck with the choking arm and secure the academy-preferred guillotine grip.','Use the second hand to reinforce the choking wrist/hand while controlling head position.'],baseManipulation:'Keep the opponent’s head below their hips/shoulders enough that they cannot simply posture out or drive through you.',bodyPosition:'Sprawl or angle your hips to support the grip and prevent being rolled underneath; keep neck pressure controlled.',steps:['Capture the head as it becomes exposed.','Secure the choking grip with minimal slack.','Control the opponent’s posture with your chest/hips.','Angle/sprawl so they cannot drive directly into you.','Adjust the forearm/wrist line for the guillotine variation.','Apply gradual pressure with torso and grip together.'],finish:'Controlled choke pressure; never explosively crank the neck.',mechanism:'Head control plus forearm/wrist alignment compresses the neck while your sprawl/angle prevents posture recovery.',cues:['Capture head, then grip.','Remove slack.','Sprawl/angle.','Body plus arms.'],mistakes:['Sitting backward before controlling the opponent.','Arm-squeezing with loose head position.','Allowing the opponent to drive through the hips.'],troubleshooting:[{problem:'They keep coming forward and freeing the head.',fix:'Improve your sprawl/head control and angle rather than pulling backward with the arms.'}],reactions:['If they hand-fight the neck successfully, transition to front-head control/back take rather than burning out the arms.'],followUps:['Back take from turtle','Front headlock','D’Arce from turtle'],variations:['Arm-in/arm-out guillotine structures depend on academy preference.'],drilling:['Practice capture, grip, and sprawl with no finish before adding progressive resistance.']},
'D’Arce from turtle':{goal:'Thread a deep head-and-arm connection around a turtled opponent’s exposed arm/neck and finish by driving their shoulder into the neck.',setup:'Begin from front/side turtle when one arm is extended/available enough to create the D’Arce threading lane.',grips:['Thread the choking arm under the armpit and across the neck toward the far side.','Secure the biceps/hand configuration after the arm is sufficiently deep.'],baseManipulation:'Keep the opponent from squaring their shoulders and retracting the trapped arm.',bodyPosition:'Sprawl/walk to an angle where the opponent’s own shoulder closes one side of the neck.',steps:['Identify the exposed arm/head relationship.','Thread the choking arm deeply under the armpit and across the neck.','Secure the D’Arce grip.','Control the head/shoulder line so the opponent cannot square up.','Walk/sprawl to the finishing angle.','Remove space and apply gradual compression.'],finish:'Controlled head-and-arm choke; release on the tap.',mechanism:'Your forearm closes one side of the neck while the trapped shoulder is driven into the other.',cues:['Thread deep.','Trap shoulder.','Angle first.','Then squeeze.'],mistakes:['Shallow thread.','Squeezing while square.','Cranking head instead of compressing shoulder/neck.'],troubleshooting:[{problem:'No choke despite hard squeeze.',fix:'Deepen the thread and improve shoulder-to-neck alignment before using more force.'}],reactions:['If the arm disappears, transition to back/front-head control instead of forcing a shallow D’Arce.'],followUps:['Back take from turtle','Anaconda choke','Front headlock'],variations:['D’Arce from turtle/front headlock'],drilling:['Partner presents the threading lane; top establishes angle before any finishing pressure.']},
'Anaconda choke':{goal:'Wrap the opponent’s head and arm from a front-head/turtle position, connect the figure-four, and use a controlled roll/angle to compress the neck.',setup:'Begin from front headlock/turtle when one arm and the head can be captured together.',grips:['Thread the choking arm around the neck and under the far armpit, then secure your biceps/figure-four configuration.','Control the head/arm tightly enough that the opponent cannot retract the shoulder.'],baseManipulation:'Fold the opponent’s head/arm toward each other and use the roll/angle to put their trapped shoulder into the neck.',bodyPosition:'Stay chest-connected through the transition. Roll across shoulder/back safely rather than diving onto the head.',steps:['Capture the head and one arm in the anaconda threading path.','Secure the figure-four grip and remove slack.','Bring the opponent’s elbow/shoulder inward toward their neck.','Choose the safe roll/angle and keep chest connection.','Roll/turn so the opponent lands with their trapped shoulder compressed toward the neck.','Walk/adjust your body to remove remaining space.','Apply gradual finishing pressure.'],finish:'Controlled blood-choke pressure with immediate release on the tap.',mechanism:'Your arm compresses one carotid while the opponent’s trapped shoulder is folded into the other; the roll establishes the angle that closes the loop.',cues:['Head and arm together.','No slack.','Shoulder into neck.','Roll for angle, not spectacle.'],mistakes:['Loose figure-four before rolling.','Rolling without controlling the trapped arm.','Trying to neck-crank instead of creating shoulder compression.'],troubleshooting:[{problem:'They pop their head out during the roll.',fix:'Tighten the head-and-arm connection and remove slack before initiating rotation.'}],reactions:['If the opponent blocks the roll, maintain front-head control and switch to D’Arce/back-take lanes.'],followUps:['D’Arce from turtle','Back take from turtle','Front headlock'],variations:['Standard anaconda from front headlock/turtle'],drilling:['Practice capture and controlled roll without finish; add gradual choke only after stable endpoint.']}
};


const mountBackInstruction:Record<string,Partial<BjjTechnique>>={
'Upa escape':{goal:'Trap one side of the mounted opponent’s base, bridge their center beyond that trapped side, and roll into top position.',setup:'Begin under mount with elbows close, neck protected, and feet close enough to your hips to generate a strong bridge.',grips:['Control the opponent’s arm on the escape side so they cannot post.','Trap/block the foot or lower leg on the same side so they cannot widen their base.'],baseManipulation:'Remove both same-side posts—arm and leg—then drive the opponent’s center diagonally over that missing corner.',bodyPosition:'Bring heels close enough to drive through the floor. Bridge toward a shoulder rather than straight upward.',steps:['Protect your elbows/neck and survive the mount first.','Choose one side and trap that arm so the hand cannot post.','Trap the same-side foot/leg with your own leg.','Bring your feet underneath your hips and connect your upper body to the opponent.','Bridge explosively but directionally toward the trapped-side shoulder.','Turn with the bridge and follow the opponent over.','Immediately establish posture/top guard position rather than leaving arms extended.'],finish:'Finish on top inside guard/half guard with posture and limb safety restored.',mechanism:'Mount is stable because the top player can post hands and widen knees/feet. Removing both posts on one side leaves no base when your bridge moves their center beyond that edge.',cues:['Trap arm and foot on same side.','Bridge to shoulder, not ceiling.','Hips high.','Come up into posture.'],mistakes:['Bridging before trapping the posts.','Bridging straight upward.','Trying to roll with arm strength.','Coming on top with hands exposed.'],troubleshooting:[{problem:'They post and stay mounted.',fix:'Identify which same-side post you failed to remove before bridging again.'},{problem:'They feel too heavy to roll.',fix:'Move their center with a high diagonal hip bridge; do not try to twist them with your arms.'}],reactions:['If they widen/post to stop the upa, their elbow-knee space may open for the bridge hip escape.'],followUps:['Bridge hip escape from mount','Top guard posture'],variations:['Classic trap-and-roll / upa'],drilling:['Pause after trapping arm + foot and verify both posts are actually gone before bridging.','Add top-player post reactions and chain to elbow-knee escape.']},
'Bridge hip escape from mount':{goal:'Use bridge pressure to make the mounted opponent adjust, then hip-escape and insert a knee/elbow frame to recover half guard or full guard.',setup:'Begin under mount with elbows inside and feet close to the hips.',grips:['Frame with elbows/forearms inside the opponent’s thigh/hip line; avoid straight-arm pushing.'],baseManipulation:'Bridge first to make the top player post/lighten a knee, then move your hips away from that knee so your own knee can enter the space.',bodyPosition:'Turn onto your side during the hip escape; remaining flat prevents the knee and elbow from reconnecting.',steps:['Protect inside elbow position.','Bridge strongly enough to make the opponent react or lighten one side.','As their weight shifts, turn onto your side.','Hip-escape away while keeping your elbow/knee lane protected.','Bring the near knee underneath/inside the opponent’s leg.','Recover half guard first if necessary, then continue to full/open guard.','Square your hips once a functional guard exists.'],finish:'Finish with at least one leg inside and a recognizable guard rather than remaining pinned under mount.',mechanism:'The bridge temporarily changes the top player’s weight distribution; the hip escape then moves your pelvis far enough for the knee to replace the lost space.',cues:['Bridge creates reaction.','Get on your side.','Elbow and knee reconnect.','Accept half guard if needed.'],mistakes:['Shrimping while flat.','Pushing on the opponent with straight arms.','Trying to insert the knee before creating a weight shift.'],troubleshooting:[{problem:'Their knee follows my hip escape.',fix:'Bridge more effectively first and keep your elbow-knee lane protected as your hips move.'}],reactions:['A wide post to stop your bridge may create the exact knee-entry space you need.'],followUps:['Half guard','Open guard','Upa escape'],variations:['Elbow-knee mount escape','Bridge-to-half-guard recovery'],drilling:['Alternate upa and elbow-knee escape based on whether the top player keeps or widens their base.']},
'Cross choke from mount':{goal:'Use mount control and deep opposing collar grips to compress both sides of the neck without giving up your base.',setup:'Begin from stable mount with the opponent’s bridge/elbow-knee escape contained.',grips:['Feed the first hand deeply into the opposite collar near the neck.','Secure the second opposing collar grip while keeping elbows structurally close.'],baseManipulation:'Use knees/feet/hips to follow bridges so your hands can work without becoming your only posts.',bodyPosition:'Stay balanced over the torso; lower chest/head as needed while keeping hips responsive to bridges.',steps:['Stabilize mount before reaching for collars.','Establish the first deep cross-collar grip.','Maintain base while feeding the second grip.','Align wrists/forearms along both sides of the neck.','Remove slack and bring elbows toward a strong compact position.','Lower/angle your torso while maintaining mount.','Apply gradual pressure.'],finish:'Controlled collar choke with immediate release on the tap.',mechanism:'Opposing collar grips compress the carotid regions while mount prevents the opponent from easily creating distance.',cues:['Mount first.','Deep first grip.','Elbows compact.','Keep hips responsive.'],mistakes:['Reaching both hands before stabilizing mount.','Shallow collar grip.','Squeezing while elbows flare.'],troubleshooting:[{problem:'I get rolled while setting grips.',fix:'Your hands replaced your base before your hips/knees were controlling the bridge; stabilize first.'}],reactions:['If they push an elbow/arm across to defend, use the arm position for armbar/arm-triangle pathways.'],followUps:['Armbar from mount','Arm triangle from side control','Technical mount'],variations:['Palm-up cross choke from mount'],drilling:['Top player must maintain mount through light bridges while establishing grips; finish only after balance is stable.']},
'Armbar from mount':{goal:'Isolate an arm while maintaining mount, climb above the shoulder line, and transition tightly into an armbar.',setup:'Begin in stable mount after the opponent exposes an elbow through framing or choke defense.',grips:['Control the target wrist/arm and keep the elbow separated from the ribs.','Use head/shoulder control or an underhook-style connection until your legs replace the mount pin.'],baseManipulation:'Climb your knees higher as the opponent’s elbows separate, reducing their ability to bridge/turn underneath the transition.',bodyPosition:'Stay close to the shoulder and pivot around the isolated arm; do not fall backward from low mount.',steps:['Stabilize mount and isolate one arm above the opponent’s shoulder line.','Climb your knees high enough to control the shoulders.','Shift weight so one leg can become light without losing balance.','Bring the first leg high beside/under the shoulder and pivot your hips.','Pass the other leg over the head while keeping the elbow captured.','Sit close with the elbow above your hip line.','Pinch knees, control wrist orientation, and extend hips gradually.'],finish:'Controlled elbow extension; release immediately on the tap.',mechanism:'High mount isolates the shoulder; your legs then replace mount control while your hips become the elbow fulcrum.',cues:['Isolate before transition.','Climb high.','Stay close to shoulder.','Elbow over hips.'],mistakes:['Falling back from low mount.','Throwing the leg over while the elbow can retract.','Creating space around the shoulder.'],troubleshooting:[{problem:'They escape as I swing the leg over.',fix:'Climb higher and maintain elbow/head control until both legs have replaced your mount pressure.'}],reactions:['If the arm retracts, return to stable mount or follow their turn into technical mount/back exposure.'],followUps:['Technical mount','Back control','Mount Control Cycle'],variations:['S-mount armbar','Standard mount armbar'],drilling:['Pause at high mount, pivot, leg-over-head, and seated armbar checkpoints.']},
'Ezekiel choke':{goal:'Use your sleeves/forearms from mount to create a compact two-sided neck compression while keeping positional control.',setup:'Begin from stable mount with your arms already connected around/near the opponent’s head and shoulders.',grips:['Slide one hand inside your opposite sleeve as taught.','Use the free hand/forearm to cross the neck and connect to the sleeve-supported structure.'],baseManipulation:'Keep hips/knees responsive to bridges; do not sacrifice mount by reaching far away from your center.',bodyPosition:'Stay chest-connected and compact, bringing the forearms into position with minimal space.',steps:['Stabilize mount.','Position one forearm/arm behind or beside the opponent’s head according to your academy’s version.','Secure your own sleeve with the supporting hand.','Bring the second forearm/hand across the neck.','Close the space while keeping elbows compact.','Apply gradual forearm/sleeve pressure without losing mount.'],finish:'Controlled choke pressure; release immediately on the tap.',mechanism:'The sleeve-supported forearm structure closes both sides/front-side neck space with less dependence on grip strength.',cues:['Compact arms.','Sleeve connection first.','Keep mount.','Pressure gradually.'],mistakes:['Reaching so far that the opponent can bridge you.','Loose sleeve connection.','Driving uncontrolled pressure into the face/jaw.'],troubleshooting:[{problem:'I lose mount while reaching the choke.',fix:'Settle hips and make the hand positions smaller/closer to your center before committing both arms.'}],reactions:['Defensive hand fighting can expose elbows for higher mount/armbar attacks.'],followUps:['Armbar from mount','Cross choke from mount','Technical mount'],variations:['Gi Ezekiel from mount'],drilling:['Maintain mount through light bridge resistance while assembling the grip slowly.']},
'Gift-wrap to back-mount transition':{goal:'Use a gift-wrap arm configuration to turn the mounted opponent onto their side and move behind their shoulders/hips into back control.',setup:'Begin from mount when you can bring one of the opponent’s arms across their torso/face line and keep it there.',grips:['Control the opponent’s wrist across their body and secure the arm with your opposite arm/under-head connection to create the gift wrap.'],baseManipulation:'The crossed arm limits the opponent’s ability to post/turn back toward you and gives you a lever to rotate their shoulders.',bodyPosition:'Shift into technical mount as the opponent turns; keep your chest attached to their upper back/shoulder.',steps:['Stabilize mount and move the opponent’s arm across their centerline.','Secure the gift-wrap connection so the arm cannot simply retract.','Use the control to turn the opponent onto their side.','Slide into technical mount while keeping chest-to-shoulder connection.','Move your torso behind their shoulder line and establish a seatbelt.','Insert the first hook/hip control before releasing the gift wrap.','Settle full back control.'],finish:'Finish chest-to-back with seatbelt and hip/hook control before attacking.',mechanism:'The gift wrap fixes one arm across the torso, limiting the opponent’s ability to rotate toward you while providing a handle to expose the back.',cues:['Arm across center.','Turn them, don’t chase back.','Technical mount bridge.','Seatbelt before release.'],mistakes:['Letting go of the wrist before seatbelt/hip control exists.','Jumping to hooks without upper-body connection.','Leaving space as the opponent turns.'],troubleshooting:[{problem:'They square back to me.',fix:'Keep the gift wrap and chest pressure until your torso is behind their shoulder line.'}],reactions:['If they refuse to turn, use the isolated arm for mount attacks instead of forcing back exposure.'],followUps:['Rear naked choke','Single-wing choke from back','Technical mount'],variations:['Gift-wrap back take from mount'],drilling:['Require three checkpoints: gift wrap → technical mount → seatbelt/back control.']},
'Triangle from mount':{goal:'Use high mount/arm isolation to create a one-arm-in head-and-arm relationship, then lock a triangle while retaining top control or transitioning safely.',setup:'Begin from high mount after separating one elbow/arm from the opponent’s defensive frame.',grips:['Control one wrist/arm across or away so one arm remains inside the triangle and the other outside.','Control head/posture as your leg crosses the shoulder/neck line.'],baseManipulation:'Pin the opponent’s shoulders and isolate the arm before lifting a leg; their inability to turn freely makes the leg transition safer.',bodyPosition:'Climb high and keep your weight forward/connected while threading the leg over the shoulder.',steps:['Stabilize high mount and isolate one arm.','Move the opponent’s arm into a one-in/one-out relationship.','Shift weight safely and bring your leg over the neck/shoulder.','Lock your legs into the triangle configuration while maintaining top balance.','Adjust angle so the trapped shoulder is driven into the neck.','Finish from top if stable or transition to the controlled finishing orientation taught by your academy.','Apply gradual pressure.'],finish:'Controlled triangle compression; release immediately on the tap.',mechanism:'Your thigh closes one side of the neck while the opponent’s trapped shoulder closes the other; high mount provides the isolation needed to build the structure.',cues:['High mount first.','One arm in, one out.','Leg high on neck.','Angle before squeeze.'],mistakes:['Trying to throw the leg over from low/unstable mount.','Losing arm isolation.','Squeezing while square with space around the shoulder.'],troubleshooting:[{problem:'They turn and escape as my leg comes over.',fix:'Climb higher and pin shoulders/arm before making the leg light.'}],reactions:['If the triangle does not close, return to mount/armbar rather than falling off position.'],followUps:['Armbar from mount','Mount Control Cycle'],variations:['Mounted triangle','Mounted triangle to bottom finish'],drilling:['Build the position without finishing; top must retain balance throughout the leg transition.']},
'Armbar from technical mount':{goal:'Use technical mount to isolate the upper arm/shoulder, pivot tightly around the head, and enter an armbar without losing chest connection.',setup:'Begin in technical mount with the opponent on their side and your upper body controlling their shoulders.',grips:['Control the exposed arm/wrist and keep the elbow above/away from the ribs.','Maintain head/shoulder connection until your legs replace it.'],baseManipulation:'Technical mount prevents the opponent from squaring their hips/shoulders while you isolate the upper arm.',bodyPosition:'Stay tight behind/above the shoulder and pivot around the head with your hips close.',steps:['Stabilize technical mount.','Isolate the exposed arm and keep the elbow captured.','Shift your weight so the leg near the head becomes mobile.','Pivot tightly and bring the leg over the head.','Sit close to the shoulder with the elbow above your hip line.','Pinch knees and control wrist orientation.','Extend hips gradually.'],finish:'Controlled elbow extension with immediate release on the tap.',mechanism:'Technical mount isolates the opponent’s shoulder line; your pivot converts that positional isolation into an elbow fulcrum.',cues:['Control side position first.','Elbow captured.','Tight pivot.','Sit close.'],mistakes:['Pivoting before the arm is isolated.','Leaving space around the shoulder/head.','Falling backward too early.'],troubleshooting:[{problem:'They pull the arm out during my pivot.',fix:'Keep the elbow connected to your torso and maintain wrist control until your legs are fully positioned.'}],reactions:['If the arm retracts, stay in technical mount and attack back/collar pathways.'],followUps:['Single-wing choke from technical mount','Gift-wrap back take','Back control'],variations:['Technical-mount armbar'],drilling:['Rep the pivot while partner tries only to retract the elbow.']},
'Single-wing choke from technical mount':{goal:'Use technical mount/back exposure to establish a deep collar grip and one-sided shoulder control, then tighten the collar choke without losing the position.',setup:'Begin in technical mount with the opponent turned on their side and their upper back controlled.',grips:['Feed the choking hand deep into the far/opposite collar near the neck.','Use the other arm/hand to control the shoulder, arm, lapel, or leg according to your academy’s single-wing finish.'],baseManipulation:'Keep the opponent’s shoulders turned away from you so they cannot square up and relieve collar pressure.',bodyPosition:'Stay chest-connected behind the shoulder with knees/feet controlling hip rotation.',steps:['Stabilize technical mount.','Feed the deep choking collar grip.','Secure the secondary control that prevents shoulder rotation.','Keep your chest behind the opponent’s upper shoulder line.','Remove collar slack and adjust your elbow/wrist line.','Use your body angle to tighten the choke gradually.'],finish:'Controlled collar compression; release immediately on the tap.',mechanism:'The deep collar grip compresses one side of the neck while the secondary control and technical mount prevent the torso from rotating to create space.',cues:['Deep collar.','Control shoulder rotation.','Chest behind them.','Body angle tightens choke.'],mistakes:['Shallow grip.','Losing hip control while reaching.','Trying to arm-squeeze without controlling rotation.'],troubleshooting:[{problem:'They turn back toward me.',fix:'Re-establish technical mount hip/shoulder control before tightening the collar.'}],reactions:['If they defend the collar with both hands, use the arm commitment to transition to back/armbar control.'],followUps:['Armbar from technical mount','Gift-wrap back take','Back control'],variations:['Academy-specific single-wing collar finish'],drilling:['Maintain technical mount through turning resistance while feeding the collar.']},
'Bow choke from technical mount':{goal:'Use a deep collar grip plus lower-body/pants control from technical mount to bow the opponent’s body and tighten a gi choke.',setup:'Begin technical mount with the opponent on their side and collar access.',grips:['Feed a deep collar grip across the neck.','Control the opponent’s pants/leg/hip with the other hand according to the bow-choke variation.'],baseManipulation:'The collar and lower-body control oppose each other, limiting the opponent’s ability to straighten/rotate their body.',bodyPosition:'Stay behind the shoulder/hip line and rotate your torso/legs to create the bow shape without jerking the neck.',steps:['Stabilize technical mount.','Secure the deep collar grip.','Reach/control the lower-body anchor used in your variation.','Keep the opponent on their side with chest/hip connection.','Rotate/extend your body so the collar and lower-body controls draw opposite ends of the opponent’s body.','Remove slack and apply gradual collar pressure.'],finish:'Controlled gi choke; release immediately on the tap.',mechanism:'Opposing collar and lower-body anchors prevent the torso from following the choke and increase collar tension around the neck.',cues:['Deep collar first.','Own shoulder and hip.','Opposing anchors.','Rotate, don’t yank.'],mistakes:['Reaching for the pants before controlling the upper body.','Losing technical mount during rotation.','Pulling violently on the collar.'],troubleshooting:[{problem:'They square up while I reach the leg.',fix:'Keep chest/hip control and secure the collar/shoulder position before reaching farther.'}],reactions:['If lower-body control is unavailable, retain technical mount and switch to single-wing/back-take pathways.'],followUps:['Single-wing choke from technical mount','Gift-wrap back take','Back control'],variations:['Bow-and-arrow style choke from technical mount'],drilling:['Practice collar + lower-body connection and body rotation with no finishing pressure.']},
'Rocking-chair back take':{goal:'Use technical mount and a controlled rocking motion to move the opponent’s hips off the mat and insert back-control hooks/hip control.',setup:'Begin technical mount with strong upper-body connection behind the opponent’s shoulders.',grips:['Secure a seatbelt or equivalent chest-to-back connection before rocking.'],baseManipulation:'Connect the opponent’s shoulders and hips to your torso so when you rock, their pelvis follows instead of staying planted.',bodyPosition:'Sit close behind the hips with your chest attached to the upper back; rock as one connected unit.',steps:['Establish technical mount and seatbelt/upper-body control.','Bring your hips close behind the opponent.','Use your legs/base to rock the opponent’s weight toward you.','As their hips become light, insert the first hook/hip control.','Rock/adjust to create space for the second hook or body-triangle pathway.','Settle chest-to-back and control the hips.'],finish:'Finish in stable back control with seatbelt and lower-body control.',mechanism:'The rocking motion temporarily unloads the opponent’s hips while the seatbelt keeps their torso attached, allowing your legs to occupy the freed space.',cues:['Seatbelt first.','Hips close.','Rock as one unit.','Hooks when hips are light.'],mistakes:['Trying to insert hooks against fully weighted hips.','Rocking without upper-body connection.','Falling away and creating space.'],troubleshooting:[{problem:'Their hips stay glued to the mat.',fix:'Move your hips closer and connect the seatbelt/chest before rocking.'}],reactions:['If they resist the rock by turning, follow the turn into gift-wrap/back-control transitions.'],followUps:['Rear naked choke','Collar choke from back','Single-wing choke from back'],variations:['Rocking-chair back take'],drilling:['Partner keeps hips moderately heavy; top must create the light moment before inserting a hook.']},
'Gift-wrap back take':{goal:'Use the gift-wrap from technical mount to prevent the opponent from turning toward you and transition behind them into back control.',setup:'Begin technical mount with the opponent’s arm crossed and secured in a gift wrap.',grips:['Maintain wrist control across the opponent’s torso and secure the wrap around/behind the head or shoulder.'],baseManipulation:'The crossed arm blocks the opponent’s rotation toward you and gives leverage to keep their shoulders turned away.',bodyPosition:'Keep chest attached to their upper back and hips close as you move behind the shoulder line.',steps:['Secure the gift wrap in technical mount.','Keep the opponent’s arm across their centerline.','Move your chest farther behind their shoulders while controlling the hip line.','Establish a seatbelt before releasing the gift-wrap structure.','Insert first hook/hip control as space opens.','Settle full back control.'],finish:'Chest-to-back, seatbelt, and lower-body control established before attacking.',mechanism:'The gift wrap immobilizes one arm across the torso, preventing the opponent from using it to turn and giving you time to occupy the back.',cues:['Keep arm across.','Chest behind shoulder.','Seatbelt before release.','Control hips.'],mistakes:['Releasing gift wrap too early.','Chasing hooks before controlling upper body.','Allowing hips to separate.'],troubleshooting:[{problem:'They turn into me as I transition.',fix:'Maintain the crossed-arm control and move your chest behind them before changing grips.'}],reactions:['If they refuse to turn further, attack from technical mount rather than forcing the back take.'],followUps:['Rear naked choke','Single-wing choke from back','Armbar from technical mount'],variations:['Gift-wrap back take'],drilling:['Require gift wrap → seatbelt → hook sequence without losing chest contact.']},
'Technical mount to mount transition':{goal:'Return safely from technical mount to square mount when the opponent turns flat, without leaving a knee/elbow escape lane.',setup:'Begin in stable technical mount as the opponent attempts to square their shoulders/hips back to the mat.',grips:['Control upper body/arm and monitor the near hip so their knee cannot enter during your transition.'],baseManipulation:'Follow the opponent’s turn and occupy the hip space before they can connect elbow to knee.',bodyPosition:'Keep weight centered over the torso while sliding the technical-mount knee/foot back into a symmetrical mount base.',steps:['Recognize the opponent flattening/squaring.','Maintain upper-body control while following their shoulders.','Block the near hip/knee recovery lane.','Slide/reposition your legs into standard mount as their back reaches the mat.','Set both knees/feet into a responsive base.','Settle against the immediate bridge before attacking.'],finish:'Stable square mount with elbows/hips controlled.',mechanism:'Following the opponent’s flattening keeps your weight aligned while blocking the knee-entry lane prevents their turn from becoming guard recovery.',cues:['Follow the turn.','Block hip lane.','Re-square legs.','Settle before attack.'],mistakes:['Jumping legs across and exposing half guard.','Letting upper-body control go during the transition.','Attacking before mount stabilizes.'],troubleshooting:[{problem:'They catch my leg in half guard.',fix:'Control the near hip/knee line and move the trailing leg only after the lead knee blocks recovery.'}],reactions:['If they turn away again, return to technical mount/back exposure rather than forcing square mount.'],followUps:['Mount Control Cycle','Gift-wrap to back-mount transition','Cross choke from mount'],variations:['Technical mount to standard mount'],drilling:['Partner alternates flat/side posture; top follows between mount and technical mount without attacking.']},
'Bridge hip-out to half guard':{goal:'From back control defense, get shoulders toward the mat, move hips outside the opponent’s hook line, and capture a leg into half guard.',setup:'Begin with the opponent on your back. First protect the choking side/neck and identify the safer escape side.',grips:['Two-on-one or priority hand control on the choking arm.','Control/monitor the opponent’s lower-body hook on the escape side.'],baseManipulation:'Move your shoulders toward the mat on the safe side so the opponent loses chest-to-back alignment, then hip out beyond their knee/hook.',bodyPosition:'Keep chin/neck protected and slide your upper back toward the mat before trying to turn into the opponent.',steps:['Protect the neck and control the choking hand/arm.','Choose the safe side and work your shoulder toward the mat.','Clear/manage the hook on that side.','Bridge/hip out so your pelvis moves beyond the opponent’s knee line.','Turn toward the opponent only after your shoulders are no longer trapped chest-to-back.','Capture their leg between yours to establish half guard.','Rebuild frames/underhook as appropriate.'],finish:'Finish facing the opponent in functional half guard with the neck safe.',mechanism:'Back control depends on chest-to-back alignment and hooks controlling the hips. Putting a shoulder on the mat breaks upper-body alignment; clearing the hook lets the hips rotate to face the opponent.',cues:['Neck first.','Shoulder to mat.','Clear hook.','Then turn.'],mistakes:['Turning into the opponent while chest-to-back is still intact.','Fighting hooks before protecting the neck.','Clearing a hook but leaving hips inside their knee line.'],troubleshooting:[{problem:'They follow my turn and keep my back.',fix:'Get your shoulder truly to the mat and hips beyond the hook before trying to face them.'}],reactions:['If they switch choking sides, reset hand priority and reassess the safe side rather than continuing blindly.'],followUps:['Half guard','Replace guard from side control'],variations:['Back escape to half guard'],drilling:['Start with seatbelt/hooks but no choke; require shoulder-to-mat checkpoint before turning.']},
'Feet-crossed ankle lock counter':{goal:'Recognize when a back controller crosses their feet in a vulnerable configuration and apply the academy-approved ankle/foot entanglement without neglecting neck defense.',setup:'Begin while defending back control; this counter is only relevant when the opponent crosses their feet in the specific unsafe position your academy teaches.',grips:['Neck/choking-hand defense remains first priority.','Use your legs to trap/control the crossed feet rather than abandoning hand defense to reach downward.'],baseManipulation:'Fix the crossed ankles against your body/leg structure so the opponent cannot simply uncross before pressure is applied.',bodyPosition:'Keep your upper body defensively responsible while positioning your legs over/around the crossed ankles.',steps:['Protect your neck first.','Confirm the opponent’s feet are crossed in the vulnerable location.','Use your own leg configuration to trap the crossed ankles.','Keep the feet fixed while applying only the academy-approved pressure direction.','Apply pressure gradually and release immediately on the tap.','Use the opponent’s uncrossing/reaction to continue your positional escape.'],finish:'Controlled ankle/foot pressure only in the legal/taught configuration; positional escape remains the larger goal.',mechanism:'Crossed feet can create a lever where one ankle/foot is compressed against the other and your leg structure, but exact mechanics and legality depend on placement/rules.',cues:['Neck first.','Only if feet are crossed correctly.','Trap before pressure.','Use reaction to escape.'],mistakes:['Ignoring a choke to attack the feet.','Applying pressure when the feet are not in the taught vulnerable position.','Explosive leg pressure.'],troubleshooting:[{problem:'I cannot secure the counter.',fix:'Return attention to back escape; never force a foot attack while your neck/position remains compromised.'}],reactions:['When the opponent uncrosses their feet, immediately continue hip/hook escape rather than chasing the submission.'],followUps:['Bridge hip-out to half guard','Rear naked choke defense'],variations:['Academy/ruleset-specific crossed-feet counter'],drilling:['Practice recognition and trapping with zero finishing pressure first.'],notes:'Exact crossed-feet counter mechanics and legality vary; confirm your academy/ruleset version before using submission pressure.'},
'Rear naked choke defense':{goal:'Survive the immediate neck threat, control the choking arm, improve shoulder/head position, and dismantle back control before attempting to turn.',setup:'Begin with the opponent on your back and a seatbelt/choking threat present.',grips:['Prioritize two hands on the choking hand/wrist/forearm when needed.','Control the opponent’s top/choking arm before fighting secondary hooks unless the neck is already safe.'],baseManipulation:'Prevent the choking arm from getting fully behind/under the chin, then work your shoulders toward the mat on the safer side to break chest-to-back alignment.',bodyPosition:'Chin tucked as a temporary layer—not the whole defense—while shoulders and hips move toward escape alignment.',steps:['Immediately identify and control the choking arm.','Use both hands as needed to keep the forearm from sealing under the chin/around the neck.','Choose the safer side based on arm/head position.','Work your head/shoulder toward the mat while maintaining hand control.','Clear the relevant hook/hip control.','Move hips outside the opponent’s knee line.','Turn to face only after chest-to-back alignment is broken.'],finish:'Finish with the neck free and the opponent no longer securely behind your shoulders/hips.',mechanism:'RNC finishing pressure requires an unobstructed choking arm plus chest-to-back control. Hand control buys time; shoulder-to-mat and hook clearance remove the positional structure.',cues:['Hands fight choke first.','Chin is delay, not defense.','Shoulder to mat.','Turn only after alignment breaks.'],mistakes:['Fighting hooks while the choking hand is free.','Relying on chin tuck alone.','Turning into the choke while the opponent remains chest-to-back.'],troubleshooting:[{problem:'Their arm keeps slipping under my chin.',fix:'Use earlier two-on-one hand control and keep the choking wrist/hand away from the neck line before working lower-body escape.'}],reactions:['If they switch arms/sides, immediately switch hand priority and reassess the safe shoulder-to-mat direction.'],followUps:['Bridge hip-out to half guard','Half guard'],variations:['Early RNC hand-fighting defense','Back-control positional escape'],drilling:['Begin with seatbelt and progressively deeper choking-arm positions; bottom’s first scoring action is always correct hand control.']},
'Rear naked choke':{goal:'From stable back control, isolate the neck, slide the choking arm into position, and close a controlled rear naked choke without sacrificing hip/chest connection.',setup:'Begin with chest-to-back connection, seatbelt, and reliable lower-body control.',grips:['Use the seatbelt to control shoulders while hand-fighting for access to the neck.','Once the choking arm is deep, secure the biceps with that hand and place the reinforcing hand behind/around the head—not where it can be easily peeled.'],baseManipulation:'Keep the opponent’s shoulders and hips aligned with your torso so they cannot turn toward the choking arm.',bodyPosition:'Head stays close to the opponent’s head and chest glued to upper back; hooks/body triangle control hips while hands attack.',steps:['Stabilize back control before attacking.','Win the hand fight and create a lane under/around the chin.','Slide the choking arm deeply so the elbow aligns under the chin/centerline.','Secure your biceps with the choking hand.','Hide/place the reinforcing hand behind the head/shoulder line.','Bring elbows together/expand chest while maintaining head and hip connection.','Apply gradual pressure and release immediately on the tap.'],finish:'Controlled blood-choke pressure; never wrench the jaw/neck.',mechanism:'The choking forearm and biceps compress both sides of the neck while the reinforcing hand and chest-to-back control prevent space/rotation.',cues:['Position before neck.','Win hand fight.','Elbow under center.','Hide second hand.'],mistakes:['Attacking neck with loose hip control.','Choking arm too shallow.','Reinforcing hand exposed for easy peeling.','Cranking jaw instead of improving position.'],troubleshooting:[{problem:'They peel my hands every time.',fix:'Improve hand-fighting sequence and hide the reinforcing hand only after the choking arm is deep.'}],reactions:['If the chin/hand defense stays strong, attack their arm/collar or improve positional control instead of forcing the face.'],followUps:['Collar choke from back','Single-wing choke from back','Armbar from back'],variations:['Short choke / RNC hand-fighting sequences vary by academy.'],drilling:['Start from secure back control and score only for clean neck access; add finishing pressure last.']},
'Collar choke from back':{goal:'Use a deep gi collar grip from back control and opposing body/hand control to tighten the collar around the neck.',setup:'Begin with stable seatbelt/back control and access to the opponent’s collar.',grips:['Feed the choking hand deep into the collar near the neck.','Use the second hand to control the opposite collar/lapel, shoulder, arm, or lower body depending on the variation.'],baseManipulation:'Keep chest-to-back and hip control so the opponent cannot rotate with the collar tension.',bodyPosition:'Stay behind the shoulder line with head close and hips connected; use torso angle to remove slack.',steps:['Stabilize back control.','Feed the choking collar grip as deep as possible without losing position.','Secure the secondary control used by your variation.','Keep the opponent’s shoulders aligned with your chest.','Remove collar slack by adjusting your torso/elbow angle.','Apply gradual collar pressure while retaining lower-body control.'],finish:'Controlled gi choke; release immediately on the tap.',mechanism:'The collar becomes a fixed loop around the neck while chest-to-back/secondary control prevents the opponent from rotating to create slack.',cues:['Back control first.','Deep collar.','No slack.','Body angle finishes.'],mistakes:['Reaching for collar while hooks/hips are loose.','Shallow grip.','Arm-pulling instead of using torso angle.'],troubleshooting:[{problem:'They rotate toward the choking side.',fix:'Re-establish hip/shoulder alignment and use the secondary control to stop rotation before tightening.'}],reactions:['If both hands defend the collar, their arm position may open armbar/trapping opportunities.'],followUps:['Rear naked choke','Single-wing choke from back','Armbar from back'],variations:['Basic back collar choke','Bow-and-arrow style pathways'],drilling:['Maintain back position while partner hand-fights the collar; finishing pressure only after positional retention is reliable.']},
'Single-wing choke from back':{goal:'Use a deep collar grip and one-sided shoulder/arm control from the back to create a stable gi choking structure.',setup:'Begin in secure back control with the opponent’s shoulders/hips aligned to your torso.',grips:['Feed one hand deep into the far/opposite collar.','Use the other arm/hand to control the shoulder, arm, lapel, or leg according to your academy’s single-wing variation.'],baseManipulation:'Prevent the opponent from rotating toward the choking side while the collar grip tightens.',bodyPosition:'Keep chest glued to the upper back and head close; lower-body control follows hip escape attempts.',steps:['Stabilize back control.','Establish the deep collar grip.','Secure the secondary shoulder/arm control.','Keep the opponent’s torso aligned with yours.','Remove collar slack through elbow/torso angle.','Apply gradual choking pressure while maintaining hooks/hip control.'],finish:'Controlled collar choke with immediate release on the tap.',mechanism:'The deep collar compresses the neck while the secondary control prevents the shoulder/torso rotation needed to relieve pressure.',cues:['Deep collar.','Control shoulder.','Chest-to-back stays.','Angle, don’t yank.'],mistakes:['Losing hooks while chasing the grip.','Shallow collar connection.','Trying to finish with arm strength alone.'],troubleshooting:[{problem:'They turn and loosen the collar.',fix:'Control their shoulder/hip rotation first; the choke depends on positional alignment.'}],reactions:['Strong hand defense can expose the arm for trapping/armbar pathways.'],followUps:['Rear naked choke','Armbar from back','Collar choke from back'],variations:['Academy-specific single-wing back choke'],drilling:['Partner attempts slow shoulder rotation while attacker maintains back alignment and collar structure.']},
'Armbar from back':{goal:'Use back control and the opponent’s defensive arm position to isolate an arm, rotate around the shoulder, and transition to an armbar without giving a free escape.',setup:'Begin from stable back control when an arm becomes separated during neck/collar defense.',grips:['Control the target wrist/arm while maintaining a seatbelt or shoulder connection as long as possible.'],baseManipulation:'Keep the opponent’s shoulder/torso connected while you move your hips around the isolated arm so they cannot simply turn and withdraw the elbow.',bodyPosition:'Stay tight to the shoulder; your leg over the head and hip position must replace the back-control connection before you release it.',steps:['Stabilize back control and isolate the defensive arm.','Control the wrist/elbow and prevent the elbow from returning to the ribs.','Shift your hip angle while keeping chest/shoulder connection.','Bring the appropriate leg over the opponent’s head/face line under control.','Rotate/sit so the elbow is captured above your hip line.','Pinch knees and control wrist orientation.','Extend hips gradually.'],finish:'Controlled elbow extension; release immediately on the tap.',mechanism:'Back control isolates the shoulder; your transition keeps the elbow separated until your hips/legs become the armbar fulcrum and torso control.',cues:['Isolate from hand fight.','Stay connected during transition.','Leg replaces chest control.','Elbow over hips.'],mistakes:['Letting go of back control before the arm is secured.','Throwing the leg loosely over the head.','Creating space around the shoulder.'],troubleshooting:[{problem:'They turn and escape as I attack the arm.',fix:'Maintain seatbelt/shoulder connection longer and ensure the leg/head control replaces it before rotating away.'}],reactions:['If the arm retracts, return to neck/collar attacks rather than chasing it out of position.'],followUps:['Rear naked choke','Collar choke from back','Back control'],variations:['Back-control armbar'],drilling:['Transition from hand-fighting back control to arm isolation without finishing; add elbow extension only after retention is stable.']}
};


const standingInstruction:Record<string,Partial<BjjTechnique>>={
'Jab / cross combo':{goal:'Use a straight lead-rear punching combination to manage distance, protect yourself, and create a safe opportunity to disengage or transition to grappling.',setup:'Begin from a balanced fighting stance with hands protecting the head and chin tucked.',grips:[],baseManipulation:'The jab occupies vision/guard and tests distance; the cross follows through the opening while the rear hip and foot rotate together.',bodyPosition:'Stay balanced with knees soft, chin protected, and the non-punching hand returning to the face. Do not let either punch pull your head beyond your base.',steps:['Establish stance and safe distance.','Extend the lead hand straight along the shortest path while the rear hand protects the face.','Retract the jab immediately.','Rotate rear hip/shoulder and drive the cross straight while the lead hand returns to guard.','Recover both hands and stance before moving, clinching, or disengaging.'],finish:'Finish balanced and protected rather than admiring the combination.',mechanism:'Straight punches travel efficiently while coordinated hip/shoulder rotation adds force without sacrificing stance.',cues:['Hands return home.','Straight lines.','Chin protected.','Finish in stance.'],mistakes:['Dropping the opposite hand.','Overreaching past the feet.','Throwing only with the arms.'],troubleshooting:[{problem:'I lose balance on the cross.',fix:'Shorten the punch and rotate around a stable base rather than reaching your head/shoulders past the lead foot.'}],reactions:['If distance closes, transition to frames/clinch rather than continuing to punch from a collapsed range.'],followUps:['Body lock · head in front takedown','Snap down · sprawl · take the back'],variations:['Basic orthodox/southpaw jab-cross'],drilling:['Shadowbox slowly with full guard recovery; add pads only after stance and hand return remain consistent.']},
'Push kick':{goal:'Use the sole/ball of the foot as a frame-like kick to manage distance and create room to disengage.',setup:'Begin in a balanced stance with hands protecting the head.',grips:[],baseManipulation:'Lift the knee first, then extend the hip/leg into the opponent’s center while the standing leg keeps your center underneath you.',bodyPosition:'Stay tall enough to recover the kicking leg quickly; do not lean so far back that you cannot move afterward.',steps:['Establish distance and guard.','Lift the kicking knee along the centerline.','Extend the foot toward the torso/hip line while keeping hands up.','Retract the leg immediately along the same path.','Replace the foot into stance and move/disengage.'],finish:'Finish back in a mobile guarded stance.',mechanism:'The leg creates a long structural frame that can interrupt forward movement while keeping your upper body available for protection.',cues:['Knee first.','Hands stay up.','Push, retract, recover stance.'],mistakes:['Dropping hands.','Leaving the leg extended.','Leaning excessively backward.'],troubleshooting:[{problem:'I get off balance after contact.',fix:'Reduce reach and prioritize fast retraction to stance over maximum force.'}],reactions:['If the kick is crowded/caught, recover the leg and protect balance rather than continuing to extend.'],followUps:['Technical stand-up','Jab / cross combo'],variations:['Front push kick / teep-style distance management'],drilling:['Light pad work emphasizing chamber, extension, retraction, and immediate movement.']},
'Cover hook punches':{goal:'Protect the head against looping punches, stay structurally sound, and create a safe exit or clinch entry.',setup:'Begin in stance as a hook/looping strike approaches.',grips:[],baseManipulation:'Use forearm/upper-arm structure against the side of the head while keeping feet underneath you; do not rely on reaching to catch the punch.',bodyPosition:'Chin tucked, elbow connected, shoulder raised, opposite hand protecting the other side.',steps:['Recognize the looping line.','Bring the near-side hand/forearm tight to the temple with elbow connected.','Keep eyes/head oriented and opposite hand protecting.','Absorb/redirect through the arm and body structure without turning away blindly.','Immediately move out, frame, or enter a safe clinch as appropriate.'],finish:'Finish protected and moving to safety rather than remaining stationary in punching range.',mechanism:'A compact cover places skeletal/arm structure between the strike and vulnerable head targets while preserving balance for the next action.',cues:['Compact cover.','Do not reach for hook.','Opposite hand stays home.','Move after contact.'],mistakes:['Flared elbow leaving gaps.','Closing eyes/turning completely away.','Standing still after the cover.'],troubleshooting:[{problem:'The punch still wraps around the guard.',fix:'Tighten the hand/forearm to the head and improve distance/angle rather than extending the arm outward.'}],reactions:['Use the attacker’s close range to clinch only if safe; otherwise prioritize exit.'],followUps:['Body lock · head in front takedown','Jab / cross combo'],variations:['Single-side high cover','Double cover under flurries'],drilling:['Start with slow predictable hooks and increase speed only while compact structure and vision remain.']},
'Parry against straight punches':{goal:'Redirect a straight punch minimally off line while preserving stance and creating an exit or counter/clinch opportunity.',setup:'Begin in stance at a distance where you can see the straight punch develop.',grips:[],baseManipulation:'Move the incoming hand only enough to miss your centerline; excessive swatting creates openings and costs time.',bodyPosition:'Keep chin protected, elbows near the body, and head subtly off the incoming line when appropriate.',steps:['Maintain guard and watch the opponent’s upper body.','Use the near/opposite hand as taught to make brief contact with the incoming wrist/forearm.','Redirect the punch just outside your head/body line.','Return the parrying hand immediately to guard.','Move angle/distance or enter a controlled clinch if available.'],finish:'Finish protected and off the original attack line.',mechanism:'A small lateral redirection changes the endpoint of a linear strike without requiring you to stop its full force head-on.',cues:['Small parry.','Do not chase hand.','Return to guard.','Move your feet too.'],mistakes:['Big swatting motion.','Dropping the opposite hand.','Parrying without changing distance/angle.'],troubleshooting:[{problem:'I keep getting hit by the second punch.',fix:'Make the parry smaller and return the hand immediately while maintaining the opposite-side guard.'}],reactions:['If the attacker overextends, use the opening to disengage or clinch rather than lingering at punching range.'],followUps:['Jab / cross combo','Body lock · head in front takedown'],variations:['Inside/outside parry depending on stance and academy method'],drilling:['Slow straight-punch feeds emphasizing minimal movement and immediate guard recovery.']},
'Standing rear naked choke':{goal:'Control from behind and apply a standing rear naked choke structure while maintaining balance and avoiding unsafe backward falls.',setup:'Begin behind the opponent with chest-to-back connection and stable foot position.',grips:['Seatbelt-style upper-body control before neck access.','Choking arm slides around the neck; reinforcing hand completes the RNC structure only after balance is controlled.'],baseManipulation:'Keep the opponent’s shoulders connected to your chest and your feet positioned so their turning/pulling cannot easily topple you.',bodyPosition:'Head close to theirs, knees soft, hips underneath your torso; avoid leaning backward with the opponent.',steps:['Establish chest-to-back/seatbelt control.','Stabilize your standing base.','Win hand position and slide the choking arm around the neck.','Secure the RNC grip while keeping your head close.','Maintain upright balance and controlled connection.','Apply gradual choke pressure; release immediately on the tap.'],finish:'Controlled choke from a stable standing base; in training, avoid dragging/falling backward.',mechanism:'The RNC compresses both sides of the neck while chest-to-back control prevents the opponent from turning to relieve pressure.',cues:['Control before choke.','Stable feet.','Head close.','Never fall backward in training.'],mistakes:['Chasing the neck without controlling torso.','Crossing/over-narrowing feet.','Leaning backward to add force.'],troubleshooting:[{problem:'They turn to face me.',fix:'Re-establish shoulder/hip connection before attacking the neck.'}],reactions:['If control deteriorates, prioritize safe positional control/disengagement rather than forcing the choke.'],followUps:['Rear body lock takedown','Back control'],variations:['Standing RNC structure'],drilling:['Practice positional control and hand-fighting with no finish before adding gradual choke pressure.']},
'Defend side headlock with punches':{goal:'Protect against strikes first, stabilize posture, then escape/control a standing side-headlock situation without sacrificing balance.',setup:'Begin caught in a standing side headlock with potential punches.',grips:['Immediate hand/forearm protection around head/face as needed.','Control the opponent’s waist/hip and/or choking/headlocking arm according to your academy escape.'],baseManipulation:'Bring your hips/base underneath you and prevent the opponent from pulling your head far outside your feet.',bodyPosition:'Protect the neck, posture as much as possible, and stay close enough that the opponent cannot freely generate punching space.',steps:['Cover/protect against the immediate punches.','Stabilize your feet and bring your hips underneath your torso.','Close distance/control the opponent’s hip/waist so they cannot freely strike or rotate.','Address the headlocking arm and create posture/space using the academy-taught escape.','Turn/step to a safer angle while maintaining balance.','Disengage or establish controlled top/clinch position.'],finish:'Finish with your head free and the striking threat controlled or safely disengaged.',mechanism:'Strike protection buys time; closing space reduces punching leverage, while posture and hip/arm control dismantle the headlock.',cues:['Punches first.','Get base underneath you.','Close striking space.','Then escape head.'],mistakes:['Trying to pry the headlock while eating punches.','Pulling backward with poor base.','Creating punching distance before the head is safe.'],troubleshooting:[{problem:'I cannot posture because they pull my head down.',fix:'Control their hip/waist and move your feet underneath the pull before trying to lift with your neck/back.'}],reactions:['If the opponent releases the headlock to strike, use the release to cover and disengage/control distance.'],followUps:['Body lock · head in front takedown','Technical stand-up'],variations:['Academy-specific side-headlock escape with strike awareness'],drilling:['Start with touch-level punches and freeze after each defensive priority; increase continuity only when protection remains first.']},
'Standing guillotine':{goal:'Control an exposed head/neck from standing and apply a guillotine structure while maintaining base.',setup:'Begin when the opponent’s head drops below/alongside your arm line during a clinch or takedown exchange.',grips:['Wrap the choking arm around the neck and secure the academy-preferred guillotine grip.','Reinforcing hand supports the choking wrist/hand without creating unnecessary neck torque.'],baseManipulation:'Control posture so the opponent cannot simply stand tall or drive cleanly through your hips.',bodyPosition:'Keep feet underneath you and hips positioned to resist forward drive; do not fall backward casually in training.',steps:['Capture the exposed head/neck.','Secure the choking grip with minimal slack.','Control the opponent’s posture and establish a stable stance.','Adjust forearm/wrist alignment for the choke variation.','Use body position to prevent forward pressure from collapsing you.','Apply gradual pressure or transition safely if the standing finish is not secure.'],finish:'Controlled choke pressure from stable position; release immediately on the tap.',mechanism:'Forearm/wrist alignment closes the neck while posture control prevents the opponent from lengthening the space.',cues:['Head control first.','Remove slack.','Base before squeeze.','No uncontrolled falling.'],mistakes:['Pulling with arms while opponent remains upright.','Falling backward without control.','Neck cranking from poor alignment.'],troubleshooting:[{problem:'They drive through me.',fix:'Improve hip/foot position and posture control before increasing grip pressure.'}],reactions:['If they defend posture successfully, transition to front-head/clinch control rather than forcing the choke.'],followUps:['Snap down to front headlock takedown','D’Arce from turtle'],variations:['Standing arm-in/arm-out guillotine structures'],drilling:['Practice capture, base, and alignment with no finish before gradual resistance.']},
'Standing guillotine defense':{goal:'Protect the neck, restore posture, control the attacker’s hips/arm, and remove your head from a standing guillotine without worsening the choke.',setup:'Begin caught in a standing guillotine/front-head grip.',grips:['Immediately control the choking wrist/forearm with both hands as needed.','Establish hip/body control so the attacker cannot freely sit/fall into a stronger finish.'],baseManipulation:'Bring your feet/hips underneath you and drive posture toward the safe side rather than pulling the head straight backward.',bodyPosition:'Keep the neck long/aligned where possible and move the whole body with the trapped head.',steps:['Hand-fight the choking arm immediately.','Stabilize your feet and prevent the attacker from freely pulling you forward/down.','Control their hip/body and move toward the safe side specified by your academy.','Improve posture by moving your legs/torso rather than yanking the neck.','Create space at the choking wrist/forearm.','Slip the head free and immediately establish safe distance or control.'],finish:'Finish with the neck free and posture/base restored.',mechanism:'Hand control reduces choking pressure while posture and hip control prevent the attacker from closing distance/angle needed for the finish.',cues:['Hands on choke first.','Move whole body.','Control hips.','Do not yank neck backward.'],mistakes:['Ignoring the choking hand.','Trying to posture with neck strength alone.','Allowing attacker to sit/fall into guard while grip is deep.'],troubleshooting:[{problem:'The choke tightens as I posture.',fix:'Improve wrist/forearm control and move toward the safe angle rather than pulling straight away.'}],reactions:['If the attacker releases to transition, use the moment to establish posture/distance instead of chasing them.'],followUps:['Body lock · head in front takedown','Technical stand-up'],variations:['Academy-specific standing guillotine escape'],drilling:['Begin with loose grip and progressively deepen only while defender preserves correct hand priority.']},
'Defend against strikes in guard':{goal:'From bottom guard in a striking context, protect the head, control posture/distance, and create a path to clinch, sweep, stand, or disengage.',setup:'Begin on bottom with the opponent between/near your legs and able to strike.',grips:['Use wrist/biceps/head/upper-body controls appropriate to distance; prioritize preventing clean punching posture.'],baseManipulation:'Either keep the opponent close enough that strikes cannot generate full force or create enough distance/angle to safely stand—avoid the middle range where they can posture and hit.',bodyPosition:'Head protected, hips active, knees/feet controlling distance; do not lie flat passively beneath striking posture.',steps:['Cover the immediate strike line.','Control wrists/biceps/head and break the opponent’s posture if they are close.','Use knees/feet/guard to manage hip distance and prevent stable striking posture.','Create an angle rather than remaining square and flat.','Choose the safest available outcome: clinch/control, sweep/wrestle up, technical stand-up, or disengage.','Re-protect the head during every transition.'],finish:'Finish in safer control or standing distance rather than remaining in an open striking exchange from bottom.',mechanism:'Striking power needs posture and distance. Guard controls that posture/distance while angles create routes to escape or reverse.',cues:['Protect head first.','No comfortable punching posture.','Too close or far—avoid middle range.','Get up when safe.'],mistakes:['Treating sport guard grips as sufficient while strikes are available.','Remaining flat.','Opening distance without a stand-up plan.'],troubleshooting:[{problem:'They keep posturing and striking.',fix:'Use stronger posture control/angle or create a deliberate technical-stand-up lane instead of staying at their ideal range.'}],reactions:['If they retreat to create striking distance, use that space to stand rather than following from your back.'],followUps:['Technical stand-up','Hip bump / sit-up sweep','Seated guard'],variations:['Closed/open guard strike management'],drilling:['Use touch-only strikes and require the bottom player to verbalize whether they are closing distance or standing.']},
'Pull to guard':{goal:'Transition from standing grips to a controlled guard without simply sitting underneath an unbalanced opponent.',setup:'Begin with reliable upper-body grips/connections and enough posture control to keep the opponent from freely stepping away or attacking during the descent.',grips:['Establish collar/sleeve or appropriate no-gi upper-body controls before sitting.'],baseManipulation:'Connect to the opponent and disturb posture enough that your descent pulls them into your guard rather than leaving you disconnected on the floor.',bodyPosition:'Keep one foot/base available as you lower; place your hips deliberately and bring the legs into control immediately.',steps:['Establish meaningful grips.','Create a small posture/balance reaction.','Keep upper-body connection as you lower your level.','Place a foot/leg to manage the opponent’s hip while sitting under control.','Bring the second leg into closed/open guard structure.','Immediately establish posture/inside-position control.'],finish:'Finish in an intentional guard with grips and distance control.',mechanism:'Connection and kuzushi keep the opponent engaged while your hips transition underneath, preventing a free passing opportunity.',cues:['Grip before sit.','Pull them into your space.','Legs connect immediately.','No disconnected sitting.'],mistakes:['Sitting with no grips.','Falling backward flat.','Letting the opponent step around the legs during descent.'],troubleshooting:[{problem:'They immediately pass as I sit.',fix:'Improve upper-body connection and place the first leg as a frame/control before your hips reach the floor.'}],reactions:['If the opponent strongly retreats, follow to seated guard/stand rather than falling flat.'],followUps:['Seated guard','Scissor Sweep','Seated single · collar drag / wrist grip'],variations:['Gi collar-sleeve guard pull','No-gi connection-based guard pull'],drilling:['Pause at standing connection, first foot placement, and established guard checkpoints.']},
'Snap down · sprawl · take the back':{goal:'Break standing posture with a snap-down, respond to the opponent’s level/forward reaction with a sprawl, then circle behind to back/turtle control.',setup:'Begin from standing head/arm ties with your hips ready to move backward.',grips:['Control the head/collar tie and an arm/upper-body connection so the snap affects the torso rather than only the neck.'],baseManipulation:'Pull the head/shoulders below the hips while stepping your own feet away; if they drive forward, sprawl hips onto the shoulder line and remove their ability to stand underneath you.',bodyPosition:'Head up, hips heavy during sprawl, chest connected; circle around the arms rather than reaching over the back.',steps:['Establish head-and-arm control.','Step/angle while snapping the head/shoulders downward.','If the opponent drives/changes level, shoot your legs back and place hips heavy in the sprawl.','Control the front-head/arm line and prevent them from rebuilding posture.','Circle toward the open side while staying heavy.','Move behind the elbows/shoulders and secure waist/seatbelt control.','Settle top turtle/back position.'],finish:'Finish behind the opponent with upper-body/hip control before inserting hooks or attacking.',mechanism:'The snap puts weight onto the hands/head line; the sprawl denies forward leg access; circling exploits the opponent’s extended turtle/front-head posture.',cues:['Snap with feet.','Hips heavy on sprawl.','Circle around arms.','Control before hooks.'],mistakes:['Pulling only with arms.','Sprawling with hips high.','Trying to jump to the back before controlling front head/arms.'],troubleshooting:[{problem:'They posture immediately after the snap.',fix:'Move your feet/angle and connect the snap to their shoulders/arm rather than tugging only the head.'}],reactions:['If they stay upright, transition to another standing attack; if they drop to turtle, circle immediately.'],followUps:['Back take from turtle','Guillotine from turtle','D’Arce from turtle'],variations:['Snap-down to go-behind','Snap-down/sprawl to back'],drilling:['Partner alternates staying upright and driving forward; attacker chooses snap continuation or sprawl/circle.']},
'Single leg defense':{goal:'Protect your base when an opponent captures one leg, prevent them from controlling your hips, and recover the leg or establish dominant upper-body control.',setup:'Begin as the opponent connects to one leg from standing.',grips:['Use head/shoulder control, whizzer/overhook, frames, or wrist control according to their position.'],baseManipulation:'Make the captured leg heavy and keep your hips away/angled so the opponent cannot easily bring your knee/hip into their center.',bodyPosition:'Balance over the free leg with hips active; avoid standing tall and letting the captured leg become a long lever.',steps:['Immediately widen/adjust balance on the free foot.','Control the opponent’s head/upper body and establish a whizzer/frame when available.','Turn the captured knee/hip into a safer alignment and make the leg heavy.','Move your hips away or apply sprawl-like pressure as their grip allows.','Peel/circle the captured leg free while maintaining upper-body control.','Re-square into stance or circle behind if their posture breaks.'],finish:'Finish with both feet safely underneath you or with established top/front-head control.',mechanism:'Single-leg finishes require connection between your leg and the attacker’s hips/torso. Head/upper-body control plus hip distance breaks that connection and restores your base.',cues:['Balance first.','Control head/shoulder.','Heavy captured leg.','Hips away.'],mistakes:['Hopping upright with no upper-body control.','Pulling the leg while the opponent’s hips stay connected.','Turning the knee into an unsafe angle.'],troubleshooting:[{problem:'They keep running me down while I hop.',fix:'Stop treating it as a foot race—establish head/whizzer control and change the hip connection.'}],reactions:['If their posture collapses, transition to front-head/sprawl/go-behind rather than merely resetting.'],followUps:['Snap down · sprawl · take the back','Back take from turtle'],variations:['Whizzer single-leg defense','Sprawl/head-control single defense'],drilling:['Start from established single-leg connection and progressively increase finishing pressure while defender maintains safe knee alignment.']},
'Body lock · head in front takedown':{goal:'Use a tight body lock and head position to move the opponent’s feet, remove a post, and finish into controlled top position.',setup:'Begin chest-to-chest/side-on in a body lock with your head positioned safely in front/along the opponent as taught.',grips:['Connect hands around the torso with a tight gable/palm-to-palm style lock.','Keep elbows close so the lock connects your torso to theirs.'],baseManipulation:'Move the opponent before attacking the legs: pressure with head/chest, step them into a reaction, then block/trip/pick the foot that becomes light.',bodyPosition:'Hips close only after upper-body connection is earned; knees bent, head structurally placed, feet able to drive and circle.',steps:['Establish a tight body lock.','Set head/chest position and bring your torso connection close.','Drive/circle to make the opponent step.','Identify the foot/post that becomes light or predictable.','Block/trip that leg while continuing upper-body pressure.','Follow the opponent to the mat without releasing torso control.','Land in stable top position before advancing.'],finish:'Controlled top position with chest/hip connection maintained through landing.',mechanism:'The body lock turns two torsos into a connected system; head/chest pressure moves the opponent’s center while the leg action removes the post they need to recover.',cues:['Connect first.','Move their feet.','Attack the light post.','Follow to top.'],mistakes:['Trying to trip stationary feet.','Loose elbows/body lock.','Closing hips before controlling upper body.'],troubleshooting:[{problem:'The trip feels like a strength contest.',fix:'Create a step/reaction first; the leg action should remove a compromised post rather than move their whole body alone.'}],reactions:['If they widen the target leg, change direction or attack the newly light opposite post.'],followUps:['Side control','Mount','Rear body lock takedown'],variations:['Head-in-front body-lock trip','Knee-pick/body-lock finish'],drilling:['Move partner three directions and call out the light foot before attempting the finish.']},
'Rear body lock takedown':{goal:'From behind, control the opponent’s hips/torso, move their base, and return them safely to the mat while staying behind the shoulders.',setup:'Begin behind the opponent with chest-to-back connection and hands locked around the waist/torso.',grips:['Tight waist/body lock with elbows close.','Keep lock around the torso/waist rather than reaching low where posture is lost.'],baseManipulation:'Pull/drive the hips off alignment and block/trip a leg as the opponent steps; avoid lifting a stable opponent solely with the back.',bodyPosition:'Head close, chest connected, hips underneath your own shoulders, knees bent.',steps:['Secure rear body lock and chest-to-back connection.','Position your feet so you can drive/circle without crossing them.','Move the opponent until one foot becomes light or their hips shift.','Block/trip the appropriate leg or perform the controlled return taught by your academy.','Keep their torso connected as they descend.','Follow to top/back control and stabilize.'],finish:'Land safely behind/on top with torso/hip control.',mechanism:'Rear body control prevents the opponent from facing you; moving their hips and removing a stepping post collapses the base without requiring a high-amplitude lift.',cues:['Chest-to-back.','Move before finish.','Block a stepping post.','Safe return.'],mistakes:['Trying to suplex/lift from poor posture.','Crossing feet while following.','Releasing the lock during descent.'],troubleshooting:[{problem:'They stay too stable to trip.',fix:'Drive/circle until they step; do not attack planted balanced feet.'}],reactions:['If they turn to face you, transition to front body lock rather than clinging to a lost rear angle.'],followUps:['Back control','Side control'],variations:['Rear body-lock trip','Controlled mat return'],drilling:['Practice moving partner to produce steps before any finish; use controlled landings only.']},
'Snap down to front headlock takedown':{goal:'Break posture with head-and-arm control, bring the opponent to hands/knees, and secure front-head top position.',setup:'Begin from standing collar tie/head-and-arm contact.',grips:['Control the head and an arm/triceps/upper-body connection so the snap transfers into the shoulders.'],baseManipulation:'Step away/angle as you pull the shoulders below the hips, forcing the opponent’s hands/knees toward the mat.',bodyPosition:'Keep your own head up and hips ready to sprawl if they drive into your legs.',steps:['Establish head-and-arm control.','Create forward pressure/reaction so the opponent resists upright.','Step/angle and snap the head/shoulders downward.','Follow their level change with chest pressure rather than standing back up.','Sprawl if needed to deny leg access.','Secure front-head control and circle/settle.'],finish:'Finish in stable front-head/top turtle control.',mechanism:'The snap redirects an upright/forward-reacting posture downward while your feet move away from the base they would use to recover.',cues:['Move feet with snap.','Control shoulder, not just head.','Hips ready to sprawl.','Stay heavy after they drop.'],mistakes:['Arm-only snap.','Pulling head without controlling torso/arm.','Standing upright after opponent drops.'],troubleshooting:[{problem:'They pop right back up.',fix:'Follow with chest/front-head pressure and keep your feet moving away from their rebuilding base.'}],reactions:['If they shoot underneath, sprawl; if they turtle, circle to back or attack front headlock.'],followUps:['Guillotine from turtle','D’Arce from turtle','Back take from turtle'],variations:['Snap-down go-behind','Snap-down front headlock'],drilling:['Rep snap to stable front-head checkpoint before adding submissions/go-behinds.']},
'Double leg':{goal:'Change level, penetrate to the hips/legs, connect both legs, and drive/corner the opponent to the mat while protecting your neck and posture.',setup:'Begin from stance after creating an opening with grips, hand fighting, or a reaction.',grips:['Wrap/control behind both knees/thighs while keeping elbows connected.'],baseManipulation:'Move your body underneath the opponent’s center, then turn the corner or drive through an angle so their feet cannot stay beneath their hips.',bodyPosition:'Head/chest upright and connected at the torso/hip line; lead knee penetrates between/near feet without collapsing posture.',steps:['Create a reaction/opening.','Lower your level with legs rather than bending at the waist.','Penetration-step deep enough to connect your shoulder/head to the torso/hip line.','Wrap both legs with elbows tight.','Bring the trail leg up so your base is underneath you.','Drive through and turn the corner while collecting the legs.','Follow to top and establish control.'],finish:'Finish on top with posture and hip control rather than stopping at the takedown impact.',mechanism:'Your level change places your center below theirs; leg control removes their ability to step while driving/cornering moves their center outside the remaining base.',cues:['Level change, don’t bow.','Deep penetration.','Elbows tight.','Turn corner.'],mistakes:['Shooting from too far away.','Head down/hips behind.','Stopping on both knees.','Driving straight into a strong sprawl indefinitely.'],troubleshooting:[{problem:'They sprawl heavily.',fix:'Keep posture, angle/corner, and transition rather than continuing a collapsed straight-line drive.'}],reactions:['Sprawl can lead to single-leg/body-lock/front-head exchanges depending on position.'],followUps:['Side control','Body lock · head in front takedown','Single leg'],variations:['Double-leg corner finish','Drive-through double'],drilling:['Level-change and penetration reps first; add partner sprawl reaction only after posture stays intact.']},
'Single leg':{goal:'Capture one leg with strong head/upper-body position, disconnect it from the opponent’s base, and finish by running, turning, tripping, or returning them safely.',setup:'Begin from stance after hand fighting or a level-change opening.',grips:['Connect hands/arms around the captured leg close to your torso.','Use head/shoulder position against the opponent’s torso to control posture.'],baseManipulation:'Bring the captured leg away from the opponent’s center and force them to balance on one post; then move that remaining post or their upper body.',bodyPosition:'Stay upright enough that the opponent cannot easily sprawl your head to the mat; hips/feet underneath you.',steps:['Create an opening and level change.','Connect to one leg with head/shoulder position.','Pull the leg tight to your body.','Come up into a strong base rather than remaining extended on the floor.','Move the opponent so their free foot must hop/step.','Choose the appropriate finish based on reaction—run the pipe, trip, shelf, or controlled return.','Follow to top control.'],finish:'Controlled top position with the captured leg/hips managed through landing.',mechanism:'Removing one leg converts the opponent’s base to a single post; head/upper-body pressure and movement then make that remaining post insufficient.',cues:['Leg tight to body.','Head controls posture.','Come up strong.','Move the standing foot.'],mistakes:['Holding the leg at arm’s length.','Head low/outside with poor posture.','Trying to finish without moving the opponent.'],troubleshooting:[{problem:'They hop forever and stay upright.',fix:'Use head/upper-body pressure and change direction to move the standing foot rather than pulling harder on the captured leg.'}],reactions:['Whizzer/hip pressure may call for a different finish or transition to body lock.'],followUps:['Body lock · head in front takedown','Side control'],variations:['Run-the-pipe single','Inside/outside single finishes'],drilling:['Capture and hold stable single-leg posture; partner gives light hopping/whizzer reactions before finishes.']},
'Uchi mata':{goal:'Use upper-body kuzushi and hip/inner-thigh elevation to project the opponent forward/diagonally while maintaining control into the landing.',setup:'Begin from standing grips with the opponent’s posture and stepping pattern controlled.',grips:['Use collar/sleeve or equivalent upper-body connections to turn the shoulders and keep the opponent attached.'],baseManipulation:'Draw the opponent forward onto a light leg/forward corner before entering; the reap/elevating leg acts after kuzushi, not against a square stable base.',bodyPosition:'Turn your hips/body into the throw with posture tall enough to rotate; the support foot and upper-body pull establish the direction.',steps:['Establish grips and create forward/diagonal kuzushi.','Step into the turning entry while keeping the opponent connected.','Rotate your hips/torso so their center moves over/alongside your support base.','Bring the reaping/elevating leg up the inside thigh line as taught.','Continue upper-body rotation while the leg elevates the compromised base.','Maintain grips and follow to a controlled top landing.'],finish:'Controlled landing with top position and no uncontrolled head/neck impact.',mechanism:'Kuzushi moves the opponent onto a forward corner; torso rotation and inner-thigh elevation remove the remaining support underneath that direction.',cues:['Kuzushi before leg.','Turn whole body.','Support foot matters.','Follow grips to top.'],mistakes:['Swinging the leg against a square opponent.','Bending forward and losing posture.','Entering too far from the opponent’s center.'],troubleshooting:[{problem:'My leg swings but they barely move.',fix:'Improve upper-body kuzushi and entry depth before trying to elevate harder.'}],reactions:['If they step around the throw, follow the stepping reaction into trips/body-lock attacks.'],followUps:['O uchi gari · major inside trip','Ko uchi gari · minor inside trip','Top control'],variations:['Gi uchi mata','Body-lock/whizzer-style uchi mata mechanics'],drilling:['Practice kuzushi + entry without throwing; add controlled elevation/landing with coach supervision.']},
'O goshi · hip throw':{goal:'Break the opponent forward, place your hips across/below their center, and rotate them over the hip shelf into a controlled landing.',setup:'Begin from close standing grips with enough upper-body control to turn the opponent’s shoulders.',grips:['Control an arm/sleeve and wrap/control the torso/waist as taught.'],baseManipulation:'Pull the opponent forward and onto their toes/forward corner before placing your hips under their center.',bodyPosition:'Turn your back/hips across the opponent while keeping knees bent and spine structurally strong; feet position creates the rotation lane.',steps:['Establish close upper-body grips.','Create forward kuzushi.','Step across and turn so your hips enter in front of/below the opponent’s center.','Bring your second foot around to complete the hip position.','Keep the opponent connected to your torso.','Extend/rotate through legs and hips while guiding the upper body over the hip shelf.','Maintain control into the landing.'],finish:'Controlled top landing with grips retained.',mechanism:'Kuzushi loads the opponent onto your hip shelf; leg extension and torso rotation then carry their center over a base they no longer own.',cues:['Pull first.','Hips under center.','Stay connected.','Legs and rotation—not back lift.'],mistakes:['Entering hips too far away.','Trying to lift with lower back.','No forward kuzushi.'],troubleshooting:[{problem:'They feel impossibly heavy.',fix:'They are likely not loaded onto your hips; improve kuzushi and hip depth before lifting.'}],reactions:['If they step around the hip, follow into trips or reset rather than wrenching the throw.'],followUps:['Side control','Mount'],variations:['O-goshi hip throw'],drilling:['Entry/fit-in reps before any throw; use controlled breakfalls and coach supervision.']},
'Tai otoshi':{goal:'Use strong upper-body kuzushi and a turning entry to project the opponent over a blocking leg line while keeping the knee safe.',setup:'Begin from standing grips with the opponent moving into a forward/diagonal corner.',grips:['Collar/sleeve or equivalent controls steer shoulders and the posting arm.'],baseManipulation:'Pull/turn the opponent’s center beyond their forward corner; the extended leg blocks the recovery path rather than sweeping their leg.',bodyPosition:'Rotate your torso strongly while placing the blocking leg safely with knee alignment protected; do not load bodyweight through a twisted knee.',steps:['Create forward/diagonal kuzushi with grips and footwork.','Turn your torso into the throwing direction.','Place the blocking leg across the opponent’s movement path in the academy-taught safe alignment.','Continue pulling/rotating their upper body beyond the blocked base.','Keep your own support knee/hip structurally aligned.','Guide the opponent over the leg line and maintain grips into landing.'],finish:'Controlled throw to top position.',mechanism:'The opponent’s center is pulled beyond the feet while the blocking leg prevents the recovery step that would restore balance.',cues:['Kuzushi first.','Leg blocks; it does not kick.','Protect your knee alignment.','Rotate upper body through.'],mistakes:['Trying to sweep with the blocking leg.','Placing the knee in a vulnerable twisted line.','Entering without forward kuzushi.'],troubleshooting:[{problem:'They step around the block.',fix:'Improve shoulder turn/kuzushi and timing so the leg intercepts an already committed step.'}],reactions:['If they retract the step, transition to another trip/throw rather than forcing the block.'],followUps:['Top control','O uchi gari · major inside trip'],variations:['Tai-otoshi entry details vary by academy/body type'],drilling:['Fit-in reps and controlled crash-pad throwing under coach supervision; prioritize knee safety.']},
'Seoi nage':{goal:'Turn underneath the opponent’s controlled arm/shoulder, load their center onto your back/shoulder line, and project them forward safely.',setup:'Begin from standing grips with forward kuzushi and control of an arm/upper body.',grips:['Control the sleeve/arm and establish the academy-taught lapel/under-arm connection.'],baseManipulation:'Pull the opponent forward so their weight travels onto the toes and over your turning entry.',bodyPosition:'Turn deeply with knees bent and hips/feet underneath you; keep the controlled arm connected to your torso.',steps:['Establish grips and forward kuzushi.','Step and turn underneath the controlled arm.','Bring your feet/hips into the throwing alignment while keeping knees bent.','Connect the opponent’s shoulder/upper body to your back/shoulder line.','Continue pulling forward as your legs extend/rotate.','Guide the opponent over your shoulder/back line.','Maintain control into landing.'],finish:'Controlled throw with safe follow-through/top control.',mechanism:'Forward kuzushi loads the opponent onto your turning frame; leg extension and rotation move their center over a base they cannot recover.',cues:['Pull them forward.','Turn all the way in.','Arm stays connected.','Legs drive the throw.'],mistakes:['Turning in while opponent is sitting back.','Loose arm connection.','Trying to bend/lift with the back.'],troubleshooting:[{problem:'They remain behind my hips.',fix:'Increase forward kuzushi and complete your turn before attempting the projection.'}],reactions:['If they circle around the entry, transition to trips/body-lock rather than forcing the shoulder throw.'],followUps:['Top control','Ko uchi gari · minor inside trip'],variations:['Standing seoi nage; drop versions require separate coaching and knee considerations'],drilling:['Fit-in/uchikomi repetitions first; throw only with safe breakfall partners and supervision.']},
'O soto gari · major outer trip':{goal:'Break the opponent backward/diagonally, control their upper body, and reap/block the outside supporting leg while driving their center beyond it.',setup:'Begin from grips with close enough distance to control the opponent’s shoulder line.',grips:['Collar/upper-body grip controls posture while sleeve/arm control limits posting/turning.'],baseManipulation:'Drive the opponent’s weight onto the heel/outside corner of the leg you intend to reap so that leg cannot freely step away.',bodyPosition:'Chest/head pressure stays connected as your reaping leg travels behind/outside the opponent’s leg.',steps:['Establish grips and step to create backward/outside kuzushi.','Bring your torso/head pressure through the opponent’s upper body.','Place your support foot close enough for the reaping leg to reach without leaning.','Swing/reap the target leg while continuing upper-body drive.','Keep grips and follow the opponent down under control.'],finish:'Land in stable top control while avoiding uncontrolled knee impact.',mechanism:'Upper-body pressure moves the center behind the target heel while the reap removes that weighted support.',cues:['Weight onto target heel.','Chest drives.','Reap a loaded leg.','Follow to top.'],mistakes:['Reaping before moving upper body.','Standing too far away.','Leaning back while kicking the leg.'],troubleshooting:[{problem:'Their leg simply steps away.',fix:'Commit their weight to it first with head/chest and grip direction.'}],reactions:['If they step back to avoid the reap, attack the new stance with inside trips or reset.'],followUps:['Side control','O uchi gari · major inside trip'],variations:['O-soto-gari'],drilling:['Kuzushi and reaping-path reps before controlled throws.']},
'O uchi gari · major inside trip':{goal:'Drive the opponent’s weight onto one leg and reap that leg from the inside while controlling the upper body.',setup:'Begin from standing grips/body connection at close range.',grips:['Upper-body grips keep the opponent connected and steer their weight onto the target leg.'],baseManipulation:'Pressure/turn until the target foot is weighted; circle your reaping leg inside and remove that post as the torso continues moving.',bodyPosition:'Stay upright and close with support foot under your center; do not reach the reaping leg from too far away.',steps:['Establish grips and close distance.','Drive/steer the opponent onto the target leg.','Step your support foot into useful range.','Circle/reap the target leg from the inside.','Continue upper-body pressure through the direction of the missing post.','Follow to controlled top position.'],finish:'Controlled takedown into top control.',mechanism:'The inside reap removes a leg that has already been loaded by upper-body kuzushi, leaving the center unsupported.',cues:['Load the leg first.','Stay close.','Reap inside.','Upper body keeps moving.'],mistakes:['Fishing for the foot with no kuzushi.','Reaching and losing posture.','Stopping upper-body pressure during the reap.'],troubleshooting:[{problem:'Their foot keeps escaping.',fix:'Make them commit weight to it before circling the reap.'}],reactions:['If they widen/withdraw the leg, use the changed stance for outer trips or body-lock direction changes.'],followUps:['O soto gari · major outer trip','Ko uchi gari · minor inside trip','Top control'],variations:['O-uchi-gari'],drilling:['Footwork/reap path with cooperative stepping before live entries.']},
'Ko uchi gari · minor inside trip':{goal:'Catch a lightly weighted/stepping foot from the inside and remove it while upper-body control prevents balance recovery.',setup:'Begin from grips during movement when the opponent steps or narrows their stance.',grips:['Use collar/sleeve or body connection to steer posture and time the step.'],baseManipulation:'Make the target foot light/stepping or momentarily weighted at the edge, then reap/block it before the opponent can settle.',bodyPosition:'Stay close enough that the foot action is small and precise; upper body continues steering.',steps:['Move the opponent with grips/pressure.','Identify the stepping or narrow inside foot.','Place your support foot to maintain balance.','Hook/reap the target heel/foot from the inside with a small action.','Continue steering the upper body into the removed base.','Follow to top or immediately chain to the next attack.'],finish:'Controlled takedown or meaningful off-balance that leads directly to the next technique.',mechanism:'A small inside foot reap works because timing removes a post during transition rather than trying to kick away a fully settled stance.',cues:['Timing over force.','Small foot action.','Upper body steers.','Chain if they recover.'],mistakes:['Big kicking motion.','Attacking a heavy settled foot.','Stopping hand/upper-body movement.'],troubleshooting:[{problem:'The reap feels weak.',fix:'Improve timing—catch the foot during the step/weight transfer instead of after it is planted.'}],reactions:['A widened recovery step often creates O-uchi/O-soto/body-lock opportunities.'],followUps:['O uchi gari · major inside trip','O soto gari · major outer trip','Body lock · head in front takedown'],variations:['Ko-uchi-gari'],drilling:['Continuous movement drill: score only when the reap is timed during a step.']},
'Outside trip / sasae':{goal:'Use upper-body steering and a foot block/trip on the outside/front of the opponent’s stepping leg to redirect their center beyond the blocked post.',setup:'Begin from grips/body connection while the opponent is stepping or resisting your pressure.',grips:['Control shoulders/arm so your hands and torso turn the opponent around the blocked foot.'],baseManipulation:'Draw or drive the opponent into a committed step, then block/check that foot/ankle while turning the upper body past it.',bodyPosition:'Stay balanced on the support leg and use a small precise foot block rather than a large kick.',steps:['Establish grips and move the opponent.','Create a step into the target side.','Place your support foot for balance and angle.','Block/check the target foot/ankle with your free foot in the academy-taught position.','Continue turning/pulling the upper body beyond the blocked step.','Maintain grips and follow to top.'],finish:'Controlled takedown into stable top position.',mechanism:'The foot block prevents a recovery step while upper-body rotation sends the center beyond that missing base.',cues:['Create the step.','Block, don’t kick.','Hands turn the torso.','Follow to top.'],mistakes:['Trying to sweep a planted heavy leg.','Large kicking action.','Foot block without upper-body kuzushi.'],troubleshooting:[{problem:'They step over my block.',fix:'Improve timing and upper-body steering so the block meets a committed step rather than a free leg.'}],reactions:['If they retract the foot, chain to inside/outer trips based on the new stance.'],followUps:['O uchi gari · major inside trip','O soto gari · major outer trip','Body lock · head in front takedown'],variations:['Outside trip','Sasae-style foot block; exact direction/placement depends on academy terminology'],drilling:['Movement drill with cooperative stepping; add controlled throws only after timing is reliable.']}
};

const detailedByName=new Map([...starterTechniques,...movementCompetencies].map(t=>[t.name.toLowerCase(),t]));

const areaIdByName=new Map(competencyAreas.map(a=>[a.name,a.id]));
export const instructionalCoverage=[
 {area:'Movement',total:movementCompetencies.length,complete:movementCompetencies.filter(t=>!!t.goal&&t.steps.length>0).length},
 ...curriculumSeeds.map(group=>({area:group.area,total:group.names.length,complete:group.names.filter(name=>!!detailedByName.get(name.toLowerCase())||!!guardBottomInstruction[name]||!!guardTopInstruction[name]||!!halfGuardTopInstruction[name]||!!sideControlBottomInstruction[name]||!!sideControlTopInstruction[name]||!!transitionInstruction[name]||!!mountBackInstruction[name]||!!standingInstruction[name]).length}))
];
export const curriculumCompetencies:BjjTechnique[]=curriculumSeeds.flatMap(group=>group.names.map(name=>{
 const detailed=detailedByName.get(name.toLowerCase());
 if(detailed)return {...detailed,position:group.area,competencyAreaId:areaIdByName.get(group.area)};
 const instruction=guardBottomInstruction[name]??guardTopInstruction[name]??halfGuardTopInstruction[name]??sideControlBottomInstruction[name]??sideControlTopInstruction[name]??transitionInstruction[name]??mountBackInstruction[name]??standingInstruction[name];
 const base={id:'competency-'+slug(group.area)+'-'+slug(name),name,position:group.area,competencyAreaId:areaIdByName.get(group.area),category:'Competency',applicability:['Gi','No-Gi'] as ('Gi'|'No-Gi')[],status:'Learning' as TechniqueStatus,competency:'Not assessed' as CompetencyStatus,tags:['Competency',instruction?'Instruction complete':'Instruction pending'],setup:'',steps:[],cues:[],mistakes:[],followUps:[],notes:''};
 return instruction?{...base,...instruction}:base;
}));
export function seedCompetencyTechniques(existing:BjjTechnique[]){
 const seeds=[...movementCompetencies.map(t=>({...t,competencyAreaId:'movement'})),...curriculumCompetencies];
 const seedNames=new Set(seeds.map(t=>t.name.toLowerCase()));
 const extras=existing.filter(t=>!seedNames.has(t.name.toLowerCase()));
 const byName=new Map(existing.map(t=>[t.name.toLowerCase(),t]));
 const merged=seeds.map(seed=>{
  const saved=byName.get(seed.name.toLowerCase());
  if(!saved)return seed;
  return {...seed,id:saved.id||seed.id,status:saved.status??seed.status,competency:saved.competency??seed.competency,notes:saved.notes??seed.notes,focus:saved.focus??seed.focus,focusNote:saved.focusNote??seed.focusNote,gameFollowUpIds:saved.gameFollowUpIds??seed.gameFollowUpIds,gameReaction:saved.gameReaction??seed.gameReaction,videoUrl:saved.videoUrl??seed.videoUrl,tags:Array.from(new Set([...seed.tags,...saved.tags.filter(x=>!['Instruction pending','Instruction complete'].includes(x))]))};
 });
 return [...extras,...merged]
}
